use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?;
    let scope = Scope::root(tenant);
    let limit = NonZeroUsize::new(4).expect("four is non-zero");

    let failing: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let body = |_step: Scope, id: u32| {
        let fetch = fetch.clone();
        let failing = Arc::clone(&failing);
        async move {
            match fetch.fetch(id).await {
                Ok(value) => Ok(value),
                Err(_) => {
                    if let Ok(mut slot) = failing.lock() {
                        *slot = Some(id);
                    }
                    Err(FlowError::failed("fetch failed"))
                }
            }
        }
    };

    let outcome = within(
        &scope,
        "aggregate",
        deadline,
        each(&scope, "fetch", Some(limit), ids, body),
    )
    .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(error) => {
            if error.is_cancelled() {
                return Err(SolveError::Cancelled);
            }
            if matches!(error, FlowError::TimedOut { .. }) {
                return Err(SolveError::Deadline);
            }
            let id = failing.lock().ok().and_then(|slot| *slot).unwrap_or(0);
            Err(SolveError::Fetch { id })
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let scope = Scope::root(Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?);
    let concurrency = NonZeroUsize::new(4).expect("4 is non-zero");
    let failure: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let work = each(&scope, "fetch", Some(concurrency), ids, |_step, id| {
        let fetch = fetch.clone();
        let failure = failure.clone();
        async move {
            // A failure observed by any sibling suppresses every fetch that has
            // not yet started, so no new fetch begins once one has failed.
            let already_failed = failure
                .lock()
                .map(|seen| seen.is_some())
                .unwrap_or(true);
            if already_failed {
                return Ok::<u64, FlowError>(0);
            }

            match fetch.fetch(id).await {
                Ok(value) => Ok::<u64, FlowError>(value),
                Err(_) => {
                    let mut seen = failure.lock().unwrap_or_else(|e| e.into_inner());
                    if seen.is_none() {
                        *seen = Some(id);
                    }
                    Ok::<u64, FlowError>(0)
                }
            }
        }
    });

    let outcome = within(&scope, "solve", deadline, work).await;

    let failing = *failure.lock().unwrap_or_else(|e| e.into_inner());

    match outcome {
        Ok(values) => match failing {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Ok(values.into_iter().sum()),
        },
        Err(err) => match failing {
            Some(id) => Err(SolveError::Fetch { id }),
            None if err.is_cancelled() => Err(SolveError::Cancelled),
            None => Err(SolveError::Deadline),
        },
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let limit: NonZeroUsize = match at_most(4) {
        Ok(limit) => limit,
        Err(_) => return Err(SolveError::Cancelled),
    };

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let body = {
        let failed = Arc::clone(&failed);
        move |_step: Scope, id: u32| {
            let fetch = fetch.clone();
            let failed = Arc::clone(&failed);
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        let mut slot =
                            failed.lock().unwrap_or_else(|poison| poison.into_inner());
                        if slot.is_none() {
                            *slot = Some(id);
                        }
                        Err(FlowError::failed(format!("fetch {} failed", id)))
                    }
                }
            }
        }
    };

    let outcome = within(
        &scope,
        "aggregate",
        deadline,
        each(&scope, "fetch", Some(limit), ids, body),
    )
    .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(FlowError::Cancelled { .. }) => Err(SolveError::Cancelled),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FlowError::Failed { .. }) => {
            let recorded = *failed.lock().unwrap_or_else(|poison| poison.into_inner());
            match recorded {
                Some(id) => Err(SolveError::Fetch { id }),
                None => Err(SolveError::Cancelled),
            }
        }
        Err(_) => Err(SolveError::Cancelled),
    }
}

use std::future::Future;
use std::marker::Unpin;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

type FetchFuture = Pin<Box<dyn Future<Output = (u32, Result<u64, FetchError>)>>>;

struct TimerState {
    deadline: Instant,
    expired: bool,
    stop: bool,
    waker: Option<Waker>,
}

struct Timer {
    shared: Arc<(Mutex<TimerState>, Condvar)>,
    handle: Option<JoinHandle<()>>,
}

impl Timer {
    fn new(deadline: Instant) -> Timer {
        let shared = Arc::new((
            Mutex::new(TimerState {
                deadline,
                expired: false,
                stop: false,
                waker: None,
            }),
            Condvar::new(),
        ));

        let worker = shared.clone();
        let handle = std::thread::spawn(move || {
            let (mutex, condvar) = &*worker;
            let mut state = mutex.lock().unwrap_or_else(|e| e.into_inner());
            loop {
                if state.stop || state.expired {
                    return;
                }
                let now = Instant::now();
                if now >= state.deadline {
                    state.expired = true;
                    let waker = state.waker.take();
                    drop(state);
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }
                let wait = state.deadline - now;
                let (next, _) = condvar
                    .wait_timeout(state, wait)
                    .unwrap_or_else(|e| e.into_inner());
                state = next;
            }
        });

        Timer {
            shared,
            handle: Some(handle),
        }
    }

    fn register(&self, waker: &Waker) {
        let (mutex, _) = &*self.shared;
        let mut state = mutex.lock().unwrap_or_else(|e| e.into_inner());
        if state.expired {
            drop(state);
            waker.wake_by_ref();
        } else {
            state.waker = Some(waker.clone());
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        let (mutex, condvar) = &*self.shared;
        {
            let mut state = mutex.lock().unwrap_or_else(|e| e.into_inner());
            state.stop = true;
        }
        condvar.notify_all();
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

struct Solve {
    ids: std::vec::IntoIter<u32>,
    fetcher: Fetcher,
    deadline: Instant,
    in_flight: Vec<FetchFuture>,
    sum: u64,
    timer: Timer,
}

impl Unpin for Solve {}

impl Solve {
    fn new(ids: Vec<u32>, fetcher: Fetcher, deadline: Duration) -> Solve {
        let deadline = Instant::now() + deadline;
        Solve {
            ids: ids.into_iter(),
            fetcher,
            deadline,
            in_flight: Vec::new(),
            sum: 0,
            timer: Timer::new(deadline),
        }
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        loop {
            if Instant::now() >= this.deadline {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let mut index = 0;
            while index < this.in_flight.len() {
                match this.in_flight[index].as_mut().poll(cx) {
                    Poll::Ready((_, Ok(value))) => {
                        this.sum += value;
                        this.in_flight.swap_remove(index);
                    }
                    Poll::Ready((id, Err(_))) => {
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => {
                        index += 1;
                    }
                }
            }

            let mut started = false;
            while this.in_flight.len() < MAX_IN_FLIGHT {
                match this.ids.next() {
                    Some(id) => {
                        let fetcher = this.fetcher.clone();
                        let future: FetchFuture = Box::pin(async move {
                            let result = fetcher.fetch(id).await;
                            (id, result)
                        });
                        this.in_flight.push(future);
                        started = true;
                    }
                    None => break,
                }
            }

            if this.in_flight.is_empty() {
                return Poll::Ready(Ok(this.sum));
            }

            if started {
                continue;
            }

            this.timer.register(cx.waker());
            return Poll::Pending;
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solve::new(ids, fetch, deadline).await
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let scope = match Tenant::new("aggregate") {
        Ok(tenant) => Scope::root(tenant),
        Err(_) => return Err(SolveError::Cancelled),
    };

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let body = async {
        let values = each(
            &scope,
            "fetch",
            NonZeroUsize::new(4),
            ids,
            |_step, id| {
                let fetch = fetch.clone();
                let failed = Arc::clone(&failed);
                async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok(value),
                        Err(_) => {
                            if let Ok(mut slot) = failed.lock() {
                                *slot = Some(id);
                            }
                            Err(FlowError::failed("fetch failed"))
                        }
                    }
                }
            },
        )
        .await?;
        Ok::<u64, FlowError>(values.into_iter().sum())
    };

    match within(&scope, "solve", deadline, body).await {
        Ok(sum) => Ok(sum),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(_) => match failed.lock().map(|slot| *slot) {
            Ok(Some(id)) => Err(SolveError::Fetch { id }),
            _ => Err(SolveError::Cancelled),
        },
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let scope = Scope::root(Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?);

    let failed_id = Arc::new(Mutex::new(None::<u32>));
    let failed = Arc::clone(&failed_id);

    let body = move |_step: Scope, id: u32| {
        let fetch = fetch.clone();
        let failed = Arc::clone(&failed);
        async move {
            match fetch.fetch(id).await {
                Ok(value) => Ok::<u64, FlowError>(value),
                Err(_) => {
                    *failed.lock().unwrap() = Some(id);
                    Err(FlowError::failed("fetch failed"))
                }
            }
        }
    };

    let run = each(&scope, "fetch", NonZeroUsize::new(4), ids, body);

    match within(&scope, "solve", deadline, run).await {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(error) => {
            if let Some(id) = *failed_id.lock().unwrap() {
                Err(SolveError::Fetch { id })
            } else if matches!(&error, FlowError::TimedOut { .. }) {
                Err(SolveError::Deadline)
            } else if error.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
    }
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{at_most, each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
