        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let scope_ref: &Scope = &scope;

    let limit = match at_most(4) {
        Ok(limit) => limit,
        Err(_) => return Err(SolveError::Cancelled),
    };

    let failing: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failing_in = failing.clone();

    let outcome = within(scope_ref, "solve", deadline, async move {
        each(scope_ref, "fetch", Some(limit), ids, move |_step, id| {
            let fetch = fetch.clone();
            let failing = failing_in.clone();
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        if let Ok(mut slot) = failing.lock() {
                            if slot.is_none() {
