                            }
                        }
                        Err(FlowError::failed("fetch failed"))
                    }
                }
            }
        })
        .await
    })
    .await;

    match outcome {
        Ok(values) => Ok(values.into_iter().sum()),
        Err(err) => {
            if matches!(err, FlowError::TimedOut { .. }) {
                Err(SolveError::Deadline)
            } else {
                match failing.lock().ok().and_then(|slot| *slot) {
                    Some(id) => Err(SolveError::Fetch { id }),
                    None => Err(SolveError::Cancelled),
                }
            }
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{self, RecvTimeoutError, Sender};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, ()>> + Send>>;

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    Solve::new(ids, fetch, deadline).await
}

struct Solve {
    ids: Vec<u32>,
    next: usize,
    fetch: Fetcher,
    deadline: Instant,
    sum: u64,
    inflight: Vec<(u32, FetchFuture)>,
    waker: Arc<Mutex<Option<Waker>>>,
    expired: Arc<AtomicBool>,
    _timer: Sender<()>,
}

impl Unpin for Solve {}

impl Solve {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Self {
        let waker: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
        let expired = Arc::new(AtomicBool::new(false));
        let (tx, rx) = mpsc::channel::<()>();

        let slot = Arc::clone(&waker);
        let flag = Arc::clone(&expired);
        std::thread::spawn(move || {
            if let Err(RecvTimeoutError::Timeout) = rx.recv_timeout(deadline) {
                flag.store(true, Ordering::SeqCst);
                let woken = slot.lock().ok().and_then(|mut s| s.take());
                if let Some(w) = woken {
                    w.wake();
                }
            }
        });

        Solve {
            ids,
            next: 0,
            fetch,
            deadline: Instant::now() + deadline,
            sum: 0,
            inflight: Vec::new(),
            waker,
            expired,
            _timer: tx,
        }
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if let Ok(mut slot) = this.waker.lock() {
            *slot = Some(cx.waker().clone());
        }

        loop {
            if this.inflight.is_empty() && this.next >= this.ids.len() {
                return Poll::Ready(Ok(this.sum));
            }

            if this.expired.load(Ordering::SeqCst) || Instant::now() >= this.deadline {
                this.inflight.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            while this.inflight.len() < MAX_IN_FLIGHT && this.next < this.ids.len() {
                let id = this.ids[this.next];
                this.next += 1;
                let fetcher = this.fetch.clone();
                let fut: FetchFuture =
                    Box::pin(async move { fetcher.fetch(id).await.map_err(|_| ()) });
                this.inflight.push((id, fut));
            }

            let mut progressed = false;
            let mut i = 0;
            while i < this.inflight.len() {
                match this.inflight[i].1.as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        this.sum += value;
                        this.inflight.swap_remove(i);
                        progressed = true;
                    }
                    Poll::Ready(Err(())) => {
                        let id = this.inflight[i].0;
                        this.inflight.clear();
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => {
                        i += 1;
                    }
                }
            }

            if !progressed {
                return Poll::Pending;
            }
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Instant;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

struct ClockState {
    waker: Option<Waker>,
    stopped: bool,
}

struct Clock {
    state: Mutex<ClockState>,
    ready: Condvar,
    expired: AtomicBool,
}

impl Clock {
    fn new() -> Self {
        Clock {
            state: Mutex::new(ClockState {
                waker: None,
                stopped: false,
            }),
            ready: Condvar::new(),
            expired: AtomicBool::new(false),
        }
    }

    fn register(&self, waker: &Waker) {
        self.state.lock().unwrap().waker = Some(waker.clone());
    }

    fn stop(&self) {
        let mut state = self.state.lock().unwrap();
        state.stopped = true;
        self.ready.notify_all();
    }

    fn expire(&self) {
        self.expired.store(true, Ordering::SeqCst);
        let waker = {
            let mut state = self.state.lock().unwrap();
            if state.stopped {
                return;
            }
            state.waker.take()
        };
        if let Some(waker) = waker {
            waker.wake();
        }
    }
}

type FetchFuture<'a> =
    Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>> + Send + 'a>>;

struct Aggregate<'a> {
    fetcher: &'a ai_task_support::Fetcher,
    ids: std::vec::IntoIter<u32>,
    remaining: usize,
    active: Vec<(u32, FetchFuture<'a>)>,
    sum: u64,
    deadline: Option<Instant>,
    clock: Arc<Clock>,
}

impl<'a> Aggregate<'a> {
    fn expired(&self) -> bool {
        self.clock.expired.load(Ordering::SeqCst)
            || self.deadline.map_or(false, |at| Instant::now() >= at)
    }
}

impl<'a> Future for Aggregate<'a> {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = unsafe { self.get_unchecked_mut() };
        this.clock.register(cx.waker());

        loop {
            if this.remaining == 0 && this.active.is_empty() {
                return Poll::Ready(Ok(this.sum));
            }
            if this.expired() {
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let fetcher = this.fetcher;
            while this.active.len() < MAX_IN_FLIGHT {
                match this.ids.next() {
                    Some(id) => {
                        this.remaining -= 1;
                        let future: FetchFuture<'a> = Box::pin(fetcher.fetch(id));
                        this.active.push((id, future));
                    }
                    None => break,
                }
            }

            let mut progressed = false;
            let mut index = 0;
            while index < this.active.len() {
                let outcome = {
                    let (id, future) = &mut this.active[index];
                    match future.as_mut().poll(cx) {
                        Poll::Ready(Ok(value)) => Ok(Some(value)),
                        Poll::Ready(Err(_)) => Err(*id),
                        Poll::Pending => Ok(None),
                    }
                };
                match outcome {
                    Ok(Some(value)) => {
                        this.sum += value;
                        this.active.swap_remove(index);
                        progressed = true;
                    }
                    Err(id) => return Poll::Ready(Err(SolveError::Fetch { id })),
                    Ok(None) => index += 1,
                }
            }

            if progressed {
                continue;
            }
            if this.expired() {
                return Poll::Ready(Err(SolveError::Deadline));
            }
            return Poll::Pending;
        }
    }
}

impl<'a> Drop for Aggregate<'a> {
    fn drop(&mut self) {
        self.clock.stop();
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let total = ids.len();
    let deadline_at = Instant::now().checked_add(deadline);
    let clock = Arc::new(Clock::new());

    if let Some(at) = deadline_at {
        let clock = Arc::clone(&clock);
        std::thread::spawn(move || {
            let mut state = clock.state.lock().unwrap();
            loop {
                if state.stopped {
                    return;
                }
                let now = Instant::now();
                if now >= at {
                    break;
                }
                let waited = clock.ready.wait_timeout(state, at - now).unwrap();
                state = waited.0;
            }
            drop(state);
            clock.expire();
        });
    }

    let aggregate = Aggregate {
        fetcher: &fetch,
        ids: ids.into_iter(),
        remaining: total,
        active: Vec::new(),
        sum: 0,
        deadline: deadline_at,
        clock,
    };

    aggregate.await
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{each, within, FlowError, ResultExt, Scope, Tenant};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let tenant = match Tenant::new("aggregate") {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let limit = match NonZeroUsize::new(4) {
        Some(limit) => limit,
        None => return Err(SolveError::Cancelled),
    };

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_body = Arc::clone(&failed);

    let result = within(&scope, "solve", deadline, async {
        let values = each(
            &scope,
            "fetch",
            Some(limit),
            ids,
            move |_step: Scope, id: u32| {
                let fetch = fetch.clone();
                let failed = Arc::clone(&failed_body);
                async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok(value),
                        Err(err) => {
                            if let Ok(mut slot) = failed.lock() {
                                if slot.is_none() {
                                    *slot = Some(id);
                                }
                            }
                            let failed_fetch: Result<u64, _> = Err(err);
                            failed_fetch.or_fail()
                        }
                    }
                }
            },
        )
        .await?;
        Ok::<u64, FlowError>(values.into_iter().sum())
    })
    .await;

    match result {
        Ok(sum) => Ok(sum),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(err) if err.is_cancelled() => Err(SolveError::Cancelled),
        Err(_) => {
            let id = match failed.lock() {
                Ok(slot) => *slot,
                Err(poisoned) => *poisoned.into_inner(),
            }
            .unwrap_or(0);
            Err(SolveError::Fetch { id })
        }
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let a_stage = stage.clone();
        let fetch_a = async move {
            a_stage
                .run(StageName::FetchA)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchA,
                })
        };

        let b_stage = stage.clone();
        let fetch_b = async move {
            b_stage
                .run(StageName::FetchB)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchB,
                })
        };

        let _ = Join2::new(fetch_a, fetch_b).await?;

        let combine_stage = stage.clone();
        let _ = async move {
            combine_stage
                .run(StageName::Combine)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::Combine,
                })
        }
        .await?;

        let published = async move {
            stage
                .run(StageName::Publish)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::Publish,
                })
        }
        .await?;

        Ok(Published::from(published))
    };

    WithDeadline::new(work, deadline).await
}

struct Join2<A, B> {
    a: Pin<Box<A>>,
    b: Pin<Box<B>>,
    a_out: Option<Artifact>,
    b_out: Option<Artifact>,
}

impl<A, B> Join2<A, B> {
    fn new(a: A, b: B) -> Self {
        Self {
            a: Box::pin(a),
            b: Box::pin(b),
            a_out: None,
            b_out: None,
        }
    }
}

impl<A, B> Future for Join2<A, B>
where
    A: Future<Output = Result<Artifact, PipelineError>>,
    B: Future<Output = Result<Artifact, PipelineError>>,
{
    type Output = Result<(Artifact, Artifact), PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.a_out.is_none() {
            match this.a.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.a_out = Some(value),
                Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                Poll::Pending => {}
            }
        }

        if this.b_out.is_none() {
            match this.b.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => this.b_out = Some(value),
                Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                Poll::Pending => {}
            }
        }

        if this.a_out.is_some() && this.b_out.is_some() {
            let a = this.a_out.take().expect("fetch a resolved");
            let b = this.b_out.take().expect("fetch b resolved");
            return Poll::Ready(Ok((a, b)));
        }

        Poll::Pending
    }
}

struct TimerState {
    fired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

struct WithDeadline<F> {
    inner: Pin<Box<F>>,
    timer: Arc<TimerState>,
}

impl<F> WithDeadline<F> {
    fn new(inner: F, limit: Duration) -> Self {
        let timer = Arc::new(TimerState {
            fired: AtomicBool::new(false),
            waker: Mutex::new(None),
        });

        let shared = Arc::clone(&timer);
        let _ = thread::spawn(move || {
            thread::sleep(limit);
            shared.fired.store(true, Ordering::SeqCst);
            let waker = shared
                .waker
                .lock()
                .ok()
                .and_then(|mut slot| slot.take());
            if let Some(waker) = waker {
                waker.wake();
            }
        });

        Self {
            inner: Box::pin(inner),
            timer,
        }
    }
}

impl<F> Future for WithDeadline<F>
where
    F: Future<Output = Result<Published, PipelineError>>,
{
    type Output = Result<Published, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.timer.fired.load(Ordering::SeqCst) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        match this.inner.as_mut().poll(cx) {
            Poll::Ready(outcome) => Poll::Ready(outcome),
            Poll::Pending => {
                if let Ok(mut slot) = this.timer.waker.lock() {
                    *slot = Some(cx.waker().clone());
                }
                if this.timer.fired.load(Ordering::SeqCst) {
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                Poll::Pending
            }
        }
    }
}

use std::num::NonZeroUsize;
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let raced = within(&scope, "pipeline", deadline, async {
        Ok::<Result<Published, PipelineError>, FlowError>(run(&scope, &stage).await)
    })
    .await;

    match raced {
        Ok(outcome) => outcome,
        Err(error) => Err(classify(error)),
    }
}

async fn run(scope: &Scope, stage: &Stage) -> Result<Published, PipelineError> {
    let fetched = each(
        scope,
        "fetch",
        NonZeroUsize::new(2),
        vec![StageName::FetchA, StageName::FetchB],
        |_step, name| {
            let stage = stage;
            async move {
                let outcome = stage.run(name).await;
                Ok::<_, FlowError>(outcome)
            }
        },
    )
    .await;

    let fetched = match fetched {
        Ok(values) => values,
        Err(_) => return Err(PipelineError::Deadline),
    };

    for (index, outcome) in fetched.iter().enumerate() {
        if outcome.is_err() {
            let name = match index {
                0 => StageName::FetchA,
                _ => StageName::FetchB,
            };
            return Err(PipelineError::Stage { name });
        }
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

fn classify(error: FlowError) -> PipelineError {
    match error {
        FlowError::Cancelled { .. } => PipelineError::Cancelled,
        FlowError::TimedOut { .. } => PipelineError::Deadline,
        _ => PipelineError::Deadline,
    }
}

use std::future::{poll_fn, Future};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = run_pipeline(&stage);
    match Instant::now().checked_add(deadline) {
        Some(at) => race_deadline(at, pipeline).await,
        None => pipeline.await,
    }
}

async fn run_pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    let _fetches = join2(fetch_a(stage), fetch_b(stage)).await?;
    combine(stage).await?;
    publish(stage).await
}

async fn fetch_a(stage: &Stage) -> Result<Artifact, PipelineError> {
    match stage.run(StageName::FetchA).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::FetchA,
        }),
    }
}

async fn fetch_b(stage: &Stage) -> Result<Artifact, PipelineError> {
    match stage.run(StageName::FetchB).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::FetchB,
        }),
    }
}

async fn combine(stage: &Stage) -> Result<Artifact, PipelineError> {
    match stage.run(StageName::Combine).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Combine,
        }),
    }
}

async fn publish(stage: &Stage) -> Result<Published, PipelineError> {
    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

async fn join2<FA, FB, A, B, E>(first: FA, second: FB) -> Result<(A, B), E>
where
    FA: Future<Output = Result<A, E>>,
    FB: Future<Output = Result<B, E>>,
{
    let mut first = Box::pin(first);
    let mut second = Box::pin(second);
    let mut first_value: Option<A> = None;
    let mut second_value: Option<B> = None;

    poll_fn(|cx: &mut Context<'_>| -> Poll<Result<(A, B), E>> {
        if first_value.is_none() {
            match first.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => first_value = Some(value),
                Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                Poll::Pending => {}
            }
        }

        if second_value.is_none() {
            match second.as_mut().poll(cx) {
                Poll::Ready(Ok(value)) => second_value = Some(value),
                Poll::Ready(Err(error)) => return Poll::Ready(Err(error)),
                Poll::Pending => {}
            }
        }

        match (first_value.take(), second_value.take()) {
            (Some(a), Some(b)) => Poll::Ready(Ok((a, b))),
            (a, b) => {
                first_value = a;
                second_value = b;
                Poll::Pending
            }
        }
    })
    .await
}

async fn race_deadline<F>(at: Instant, future: F) -> Result<Published, PipelineError>
where
    F: Future<Output = Result<Published, PipelineError>>,
{
    let mut future = Box::pin(future);
    let mut deadline = Deadline::new(at);

    poll_fn(|cx: &mut Context<'_>| -> Poll<Result<Published, PipelineError>> {
        if let Poll::Ready(()) = deadline.poll_tick(cx) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        future.as_mut().poll(cx)
    })
    .await
}

struct DeadlineState {
    done: AtomicBool,
    fired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

struct Deadline {
    at: Instant,
    state: Arc<DeadlineState>,
    worker: Option<std::thread::JoinHandle<()>>,
}

impl Deadline {
    fn new(at: Instant) -> Self {
        let state = Arc::new(DeadlineState {
            done: AtomicBool::new(false),
            fired: AtomicBool::new(false),
            waker: Mutex::new(None),
        });

        let worker_state = Arc::clone(&state);
        let worker = std::thread::Builder::new()
            .name("pipeline-deadline".to_owned())
            .spawn(move || deadline_worker(at, worker_state))
            .ok();

        Deadline { at, state, worker }
    }

    fn poll_tick(&mut self, cx: &mut Context<'_>) -> Poll<()> {
        if self.state.fired.load(Ordering::SeqCst) || Instant::now() >= self.at {
            return Poll::Ready(());
        }

        let mut slot = match self.state.waker.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        *slot = Some(cx.waker().clone());
        drop(slot);

        if self.state.fired.load(Ordering::SeqCst) {
            return Poll::Ready(());
        }

        Poll::Pending
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        self.state.done.store(true, Ordering::SeqCst);
        if let Some(worker) = &self.worker {
            worker.thread().unpark();
        }
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

fn deadline_worker(at: Instant, state: Arc<DeadlineState>) {
    loop {
        if state.done.load(Ordering::SeqCst) {
            return;
        }

        let now = Instant::now();
        if now >= at {
            break;
        }

        std::thread::park_timeout(at.saturating_duration_since(now));
    }

    if state.done.load(Ordering::SeqCst) {
        return;
    }

    state.fired.store(true, Ordering::SeqCst);

    let waker = match state.waker.lock() {
        Ok(mut guard) => guard.take(),
        Err(poisoned) => poisoned.into_inner().take(),
    };

    if let Some(waker) = waker {
        waker.wake();
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex, Weak};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: Stage,
    deadline: std::time::Duration,
) -> Result<Published, PipelineError> {
    let now = Instant::now();
    let deadline_at = now
        .checked_add(deadline)
        .or_else(|| now.checked_add(Duration::from_secs(3_153_600_000)))
        .unwrap_or(now);

    let clock = DeadlineClock::new(deadline_at);
    run_pipeline(&stage, &clock).await
}

async fn run_pipeline(
    stage: &Stage,
    clock: &Arc<DeadlineClock>,
) -> Result<Published, PipelineError> {
    let fetch_a = run_stage(stage, StageName::FetchA, clock);
    let fetch_b = run_stage(stage, StageName::FetchB, clock);
    let (_a, _b) = TryJoinArtifacts::new(fetch_a, fetch_b).await?;

    let _combined = run_stage(stage, StageName::Combine, clock).await?;
    let published = run_stage(stage, StageName::Publish, clock).await?;

    Ok(Published::from(published))
}

async fn run_stage(
    stage: &Stage,
    name: StageName,
    clock: &Arc<DeadlineClock>,
) -> Result<Artifact, PipelineError> {
    if clock.expired() {
        return Err(PipelineError::Deadline);
    }

    let call = async move {
        stage
            .run(name.clone())
            .await
            .map_err(|_| PipelineError::Stage { name })
    };

    match race(call, DeadlineWait::new(clock)).await {
        Either::Left(result) => {
            if clock.expired() {
                Err(PipelineError::Deadline)
            } else {
                result
            }
        }
        Either::Right(()) => Err(PipelineError::Deadline),
    }
}

enum Either<L, R> {
    Left(L),
    Right(R),
}

struct Race<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
}

fn race<A, B>(a: A, b: B) -> Race<A, B>
where
    A: Future,
    B: Future,
{
    Race {
        a: Some(Box::pin(a)),
        b: Some(Box::pin(b)),
    }
}

impl<A, B> Future for Race<A, B>
where
    A: Future,
    B: Future,
{
    type Output = Either<A::Output, B::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        let left = match this.a.as_mut() {
            Some(future) => match future.as_mut().poll(cx) {
                Poll::Ready(value) => Some(value),
                Poll::Pending => None,
            },
            None => None,
        };
        if let Some(value) = left {
            this.a = None;
            return Poll::Ready(Either::Left(value));
        }

        let right = match this.b.as_mut() {
            Some(future) => match future.as_mut().poll(cx) {
                Poll::Ready(value) => Some(value),
                Poll::Pending => None,
            },
            None => None,
        };
        if let Some(value) = right {
            this.b = None;
            return Poll::Ready(Either::Right(value));
        }

        Poll::Pending
    }
}

struct TryJoinArtifacts<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    a_value: Option<Box<Artifact>>,
    b_value: Option<Box<Artifact>>,
}

impl<A, B> TryJoinArtifacts<A, B>
where
    A: Future<Output = Result<Artifact, PipelineError>>,
    B: Future<Output = Result<Artifact, PipelineError>>,
{
    fn new(a: A, b: B) -> Self {
        TryJoinArtifacts {
            a: Some(Box::pin(a)),
            b: Some(Box::pin(b)),
            a_value: None,
            b_value: None,
        }
    }
}

impl<A, B> Future for TryJoinArtifacts<A, B>
where
    A: Future<Output = Result<Artifact, PipelineError>>,
    B: Future<Output = Result<Artifact, PipelineError>>,
{
    type Output = Result<(Artifact, Artifact), PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.a_value.is_none() {
            let outcome = match this.a.as_mut() {
                Some(future) => match future.as_mut().poll(cx) {
                    Poll::Ready(result) => Some(result),
                    Poll::Pending => None,
                },
                None => None,
            };
            if let Some(result) = outcome {
                this.a = None;
                match result {
                    Ok(value) => this.a_value = Some(Box::new(value)),
                    Err(error) => {
                        this.b = None;
                        return Poll::Ready(Err(error));
                    }
                }
            }
        }

        if this.b_value.is_none() {
            let outcome = match this.b.as_mut() {
                Some(future) => match future.as_mut().poll(cx) {
                    Poll::Ready(result) => Some(result),
                    Poll::Pending => None,
                },
                None => None,
            };
            if let Some(result) = outcome {
                this.b = None;
                match result {
                    Ok(value) => this.b_value = Some(Box::new(value)),
                    Err(error) => {
                        this.a = None;
                        return Poll::Ready(Err(error));
                    }
                }
            }
        }

        if this.a_value.is_some() && this.b_value.is_some() {
            match (this.a_value.take(), this.b_value.take()) {
                (Some(a), Some(b)) => return Poll::Ready(Ok((*a, *b))),
                _ => {}
            }
        }

        Poll::Pending
    }
}

struct WaiterCell {
    waker: Mutex<Option<Waker>>,
}

struct ClockState {
    deadline: Instant,
    fired: AtomicBool,
    stopped: Mutex<bool>,
    cond: Condvar,
    waiters: Mutex<Vec<Weak<WaiterCell>>>,
}

struct DeadlineClock {
    state: Arc<ClockState>,
    thread: Mutex<Option<JoinHandle<()>>>,
}

impl DeadlineClock {
    fn new(deadline: Instant) -> Arc<Self> {
        let state = Arc::new(ClockState {
            deadline,
            fired: AtomicBool::new(false),
            stopped: Mutex::new(false),
            cond: Condvar::new(),
            waiters: Mutex::new(Vec::new()),
        });

        let thread_state = Arc::clone(&state);
        let thread = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || run_clock(thread_state))
            .ok();

        Arc::new(DeadlineClock {
            state,
            thread: Mutex::new(thread),
        })
    }

    fn expired(&self) -> bool {
        self.state.fired.load(Ordering::Acquire) || Instant::now() >= self.state.deadline
    }
}

impl Drop for DeadlineClock {
    fn drop(&mut self) {
        if let Ok(mut stopped) = self.state.stopped.lock() {
            *stopped = true;
            self.state.cond.notify_all();
        }
        if let Ok(mut thread) = self.thread.lock() {
            if let Some(handle) = thread.take() {
                let _ = handle.join();
            }
        }
    }
}

fn run_clock(state: Arc<ClockState>) {
    let mut stopped = match state.stopped.lock() {
        Ok(guard) => guard,
        Err(_) => return,
    };

    while !*stopped {
        let now = Instant::now();
        if now >= state.deadline {
            break;
        }
        let remaining = state.deadline - now;
        match state.cond.wait_timeout(stopped, remaining) {
            Ok((guard, timeout)) => {
                stopped = guard;
                if timeout.timed_out() {
                    break;
                }
            }
            Err(_) => return,
        }
    }

    let expired = !*stopped;
    drop(stopped);

    if expired {
        state.fired.store(true, Ordering::Release);
        if let Ok(mut waiters) = state.waiters.lock() {
            for waiter in waiters.drain(..) {
                if let Some(cell) = waiter.upgrade() {
                    if let Ok(mut waker) = cell.waker.lock() {
                        if let Some(waker) = waker.take() {
                            waker.wake();
                        }
                    }
                }
            }
        }
    }
}

struct DeadlineWait {
    state: Arc<ClockState>,
    cell: Arc<WaiterCell>,
}

impl DeadlineWait {
    fn new(clock: &DeadlineClock) -> Self {
        let cell = Arc::new(WaiterCell {
            waker: Mutex::new(None),
        });
        if let Ok(mut waiters) = clock.state.waiters.lock() {
            waiters.retain(|waiter| waiter.strong_count() > 0);
            waiters.push(Arc::downgrade(&cell));
        }
        DeadlineWait {
            state: Arc::clone(&clock.state),
            cell,
        }
    }
}

impl Future for DeadlineWait {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();

        if this.state.fired.load(Ordering::Acquire) {
            return Poll::Ready(());
        }

        if let Ok(mut waker) = this.cell.waker.lock() {
            *waker = Some(cx.waker().clone());
        }

        if this.state.fired.load(Ordering::Acquire) {
            Poll::Ready(())
        } else {
            Poll::Pending
        }
    }
}

use std::num::NonZeroUsize;
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").map_err(|_| PipelineError::Cancelled)?;
    let scope = Scope::root(tenant);

    match within(&scope, "solve", deadline, async {
        Ok::<_, FlowError>(run(stage, &scope).await)
    })
    .await
    {
        Ok(result) => result,
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(_) => Err(PipelineError::Cancelled),
    }
}

async fn run(stage: Stage, scope: &Scope) -> Result<Published, PipelineError> {
    let limit = Some(NonZeroUsize::new(2).expect("two independent fetches"));
    let fetcher = stage.clone();

    let fetches = each(
        scope,
        "fetch",
        limit,
        [StageName::FetchA, StageName::FetchB],
        move |_step, name| {
            let fetcher = fetcher.clone();
            async move { Ok::<_, FlowError>(fetcher.run(name).await) }
        },
    )
    .await
    .map_err(|_| PipelineError::Cancelled)?;

    if fetches[0].is_err() {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }
    if fetches[1].is_err() {
        return Err(PipelineError::Stage {
            name: StageName::FetchB,
        });
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;
    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

use std::future::Future;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct DeadlineState {
    fired: bool,
    stopped: bool,
    waker: Option<Waker>,
}

struct DeadlineInner {
    state: Mutex<DeadlineState>,
    cv: Condvar,
}

struct Deadline {
    at: Instant,
    inner: Arc<DeadlineInner>,
}

impl Deadline {
    fn new(limit: Duration) -> Deadline {
        let now = Instant::now();
        let at = now
            .checked_add(limit)
            .unwrap_or_else(|| now + Duration::from_secs(60 * 60 * 24 * 365));
        let inner = Arc::new(DeadlineInner {
            state: Mutex::new(DeadlineState {
                fired: false,
                stopped: false,
                waker: None,
            }),
            cv: Condvar::new(),
        });
        let worker = Arc::clone(&inner);
        std::thread::spawn(move || {
            let mut guard = worker.state.lock().unwrap();
            loop {
                if guard.stopped || guard.fired {
                    return;
                }
                let now = Instant::now();
                if now >= at {
                    guard.fired = true;
                    let waker = guard.waker.take();
                    drop(guard);
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }
                let wait = at - now;
                let (next, _) = worker.cv.wait_timeout(guard, wait).unwrap();
                guard = next;
            }
        });
        Deadline { at, inner }
    }

    fn elapsed(&self) -> bool {
        let guard = self.inner.state.lock().unwrap();
        guard.fired || Instant::now() >= self.at
    }

    fn register(&self, waker: &Waker) {
        let mut guard = self.inner.state.lock().unwrap();
        match guard.waker.as_ref() {
            Some(existing) if existing.will_wake(waker) => {}
            _ => guard.waker = Some(waker.clone()),
        }
    }
}

impl Drop for Deadline {
    fn drop(&mut self) {
        let mut guard = self.inner.state.lock().unwrap();
        guard.stopped = true;
        self.inner.cv.notify_all();
    }
}

async fn with_deadline<F: Future>(
    deadline: &Deadline,
    fut: F,
) -> Result<F::Output, PipelineError> {
    let mut fut = Box::pin(fut);
    std::future::poll_fn(|cx: &mut Context<'_>| {
        if deadline.elapsed() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match fut.as_mut().poll(cx) {
            Poll::Ready(value) => Poll::Ready(Ok(value)),
            Poll::Pending => {
                deadline.register(cx.waker());
                if deadline.elapsed() {
                    Poll::Ready(Err(PipelineError::Deadline))
                } else {
                    Poll::Pending
                }
            }
        }
    })
    .await
}

async fn join_fetches(stage: &Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut a = Box::pin(stage.run(StageName::FetchA));
    let mut b = Box::pin(stage.run(StageName::FetchB));
    let mut done_a: Option<Artifact> = None;
    let mut done_b: Option<Artifact> = None;
    std::future::poll_fn(|cx: &mut Context<'_>| {
        if done_a.is_none() {
            if let Poll::Ready(result) = a.as_mut().poll(cx) {
                match result {
                    Ok(artifact) => done_a = Some(artifact),
                    Err(_) => {
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::FetchA,
                        }))
                    }
                }
            }
        }
        if done_b.is_none() {
            if let Poll::Ready(result) = b.as_mut().poll(cx) {
                match result {
                    Ok(artifact) => done_b = Some(artifact),
                    Err(_) => {
                        return Poll::Ready(Err(PipelineError::Stage {
                            name: StageName::FetchB,
                        }))
                    }
                }
            }
        }
        if done_a.is_some() && done_b.is_some() {
            Poll::Ready(Ok((done_a.take().unwrap(), done_b.take().unwrap())))
        } else {
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let deadline = Deadline::new(deadline);

    let (_a, _b) = match with_deadline(&deadline, join_fetches(&stage)).await {
        Ok(Ok(pair)) => pair,
        Ok(Err(err)) => return Err(err),
        Err(err) => return Err(err),
    };

    match with_deadline(&deadline, stage.run(StageName::Combine)).await {
        Ok(Ok(_combined)) => {}
        Ok(Err(_)) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            })
        }
        Err(err) => return Err(err),
    }

    match with_deadline(&deadline, stage.run(StageName::Publish)).await {
        Ok(Ok(artifact)) => Ok(Published::from(artifact)),
        Ok(Err(_)) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
        Err(err) => Err(err),
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, ResultExt, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);
    let fetch_stage: &Stage = &stage;
    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));

    let pipeline = async {
        let fetched = each(
            &scope,
            "fetch",
            NonZeroUsize::new(2),
            [StageName::FetchA, StageName::FetchB],
            |_scope, name| {
                let failed = Arc::clone(&failed);
                let stage = fetch_stage;
                async move {
                    let report = match &name {
                        StageName::FetchA => StageName::FetchA,
                        _ => StageName::FetchB,
                    };
                    let result = stage.run(name).await;
                    if result.is_err() {
                        let mut slot = failed.lock().unwrap();
                        if slot.is_none() {
                            *slot = Some(report);
                        }
                    }
                    result.or_fail()
                }
            },
        )
        .await;

        if fetched.is_err() {
            let name = {
                let mut slot = failed.lock().unwrap();
                slot.take()
            }
            .unwrap_or(StageName::FetchA);
            return Ok(Err(PipelineError::Stage { name }));
        }

        if stage.run(StageName::Combine).await.is_err() {
            return Ok(Err(PipelineError::Stage {
                name: StageName::Combine,
            }));
        }

        match stage.run(StageName::Publish).await {
            Ok(artifact) => Ok(Ok(Published::from(artifact))),
            Err(_) => {
                return Ok(Err(PipelineError::Stage {
                    name: StageName::Publish,
                }))
            }
        }
    };

    match within(&scope, "solve", deadline, pipeline).await {
        Ok(Ok(published)) => Ok(published),
        Ok(Err(error)) => Err(error),
        Err(flow) => Err(match flow {
            FlowError::TimedOut { .. } => PipelineError::Deadline,
            FlowError::Cancelled { .. } => PipelineError::Cancelled,
            _ => PipelineError::Deadline,
        }),
    }
}

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

#[derive(Clone, Copy)]
enum Fetch {
    A,
    B,
}

impl Fetch {
    fn stage_name(self) -> StageName {
        match self {
            Fetch::A => StageName::FetchA,
            Fetch::B => StageName::FetchB,
        }
    }
}

fn map_flow(error: FlowError) -> PipelineError {
    match error {
        FlowError::TimedOut { .. } => PipelineError::Deadline,
        _ => PipelineError::Cancelled,
    }
}

async fn run_pipeline(scope: &Scope, stage: &Stage) -> Result<Published, PipelineError> {
    let failures: Arc<Mutex<Option<Fetch>>> = Arc::new(Mutex::new(None));

    let fetched = each(
        scope,
        "fetch",
        None,
        vec![Fetch::A, Fetch::B],
        {
            let failures = Arc::clone(&failures);
            let stage = Stage::clone(stage);
            move |_child, which| {
                let failures = Arc::clone(&failures);
                let stage = Stage::clone(&stage);
                async move {
                    match stage.run(which.stage_name()).await {
                        Ok(_) => Ok::<(), FlowError>(()),
                        Err(_) => {
                            if let Ok(mut slot) = failures.lock() {
                                if slot.is_none() {
                                    *slot = Some(which);
                                }
                            }
                            Err(FlowError::failed("stage failed"))
                        }
                    }
                }
            }
        },
    )
    .await;

    if let Err(error) = fetched {
        let failed = failures.lock().ok().and_then(|mut slot| slot.take());
        return match failed {
            Some(which) => Err(PipelineError::Stage {
                name: which.stage_name(),
            }),
            None => Err(map_flow(error)),
        };
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = match Tenant::new("pipeline") {
        Ok(tenant) => tenant,
        Err(_) => return Err(PipelineError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let scope_ref = &scope;
    let stage_ref = &stage;

    let result = within(&scope, "pipeline", deadline, async move {
        Ok::<Result<Published, PipelineError>, FlowError>(run_pipeline(scope_ref, stage_ref).await)
    })
    .await;

    match result {
        Ok(inner) => inner,
        Err(error) => Err(map_flow(error)),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::script::{within, FlowError, Scope, Tenant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: &Stage, name: StageName) -> Result<Artifact, PipelineError> {
    match stage.run(name.clone()).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage { name }),
    }
}

async fn run_pipeline(stage: &Stage) -> Result<Published, PipelineError> {
    let _ = run_stage(stage, StageName::FetchA).await?;
    let _ = run_stage(stage, StageName::FetchB).await?;
    let _ = run_stage(stage, StageName::Combine).await?;
    let published = run_stage(stage, StageName::Publish).await?;
    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").expect("`pipeline` is a valid tenant name");
    let scope = Scope::root(tenant);

    let outcome = within(&scope, "pipeline", deadline, async move {
        Ok::<Result<Published, PipelineError>, FlowError>(run_pipeline(&stage).await)
    })
    .await;

    match outcome {
        Ok(result) => result,
        Err(error) if error.is_cancelled() => Err(PipelineError::Cancelled),
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct Fetches<FA, FB> {
    a: Option<Pin<Box<FA>>>,
    b: Option<Pin<Box<FB>>>,
    a_done: bool,
    b_done: bool,
}

impl<FA, FB> Future for Fetches<FA, FB>
where
    FA: Future<Output = Result<Artifact, StageError>>,
    FB: Future<Output = Result<Artifact, StageError>>,
{
    type Output = Result<(), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if !this.a_done {
            let polled = match this.a.as_mut() {
                Some(fut) => Some(fut.as_mut().poll(cx)),
                None => None,
            };
            match polled {
                Some(Poll::Ready(Ok(_))) => {
                    this.a = None;
                    this.a_done = true;
                }
                Some(Poll::Ready(Err(_))) => {
                    this.a = None;
                    this.b = None;
                    return Poll::Ready(Err(StageName::FetchA));
                }
                _ => {}
            }
        }

        if !this.b_done {
            let polled = match this.b.as_mut() {
                Some(fut) => Some(fut.as_mut().poll(cx)),
                None => None,
            };
            match polled {
                Some(Poll::Ready(Ok(_))) => {
                    this.b = None;
                    this.b_done = true;
                }
                Some(Poll::Ready(Err(_))) => {
                    this.a = None;
                    this.b = None;
                    return Poll::Ready(Err(StageName::FetchB));
                }
                _ => {}
            }
        }

        if this.a_done && this.b_done {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    }
}

struct Timer {
    duration: Duration,
    started: bool,
    fired: Arc<AtomicBool>,
    waker: Arc<Mutex<Option<Waker>>>,
    cancelled: Arc<AtomicBool>,
}

impl Timer {
    fn new(duration: Duration) -> Self {
        Timer {
            duration,
            started: false,
            fired: Arc::new(AtomicBool::new(false)),
            waker: Arc::new(Mutex::new(None)),
            cancelled: Arc::new(AtomicBool::new(false)),
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        self.cancelled.store(true, Ordering::SeqCst);
    }
}

impl Future for Timer {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();

        if this.fired.load(Ordering::SeqCst) {
            return Poll::Ready(());
        }

        {
            let mut slot = this.waker.lock().unwrap();
            *slot = Some(cx.waker().clone());
        }

        if !this.started {
            this.started = true;
            let fired = Arc::clone(&this.fired);
            let waker = Arc::clone(&this.waker);
            let cancelled = Arc::clone(&this.cancelled);
            let duration = this.duration;
            std::thread::spawn(move || {
                std::thread::sleep(duration);
                if cancelled.load(Ordering::SeqCst) {
                    return;
                }
                fired.store(true, Ordering::SeqCst);
                if let Some(w) = waker.lock().unwrap().take() {
                    w.wake();
                }
            });
        }

        Poll::Pending
    }
}

struct WithDeadline<F> {
    fut: Option<Pin<Box<F>>>,
    timer: Timer,
}

impl<F> Future for WithDeadline<F>
where
    F: Future,
{
    type Output = Option<F::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        let polled = match this.fut.as_mut() {
            Some(fut) => Some(fut.as_mut().poll(cx)),
            None => None,
        };
        if let Some(Poll::Ready(v)) = polled {
            this.fut = None;
            return Poll::Ready(Some(v));
        }

        if Pin::new(&mut this.timer).poll(cx).is_ready() {
            this.fut = None;
            return Poll::Ready(None);
        }

        Poll::Pending
    }
}

async fn run(stage: &Stage) -> Result<Published, PipelineError> {
    Fetches {
        a: Some(Box::pin(stage.run(StageName::FetchA))),
        b: Some(Box::pin(stage.run(StageName::FetchB))),
        a_done: false,
        b_done: false,
    }
    .await
    .map_err(|name| PipelineError::Stage { name })?;

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = WithDeadline {
        fut: Some(Box::pin(run(&stage))),
        timer: Timer::new(deadline),
    };

    match work.await {
        Some(result) => result,
        None => Err(PipelineError::Deadline),
    }
}

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};
use std::time::Duration;

use ai_task_support::recovery::{unit_step, World};
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{task, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TASK_NAME: &str = "recover";
const EFFECT: &str = "recover";

#[derive(Clone)]
struct Job {
    world: World,
    units: u32,
}

fn identity(store_dir: &Path) -> String {
    let mut hasher = DefaultHasher::new();
    store_dir.hash(&mut hasher);
    format!("recovery-{:016x}", hasher.finish())
}

async fn perform(scope: Scope, job: Job) -> Result<Result<u64, u32>, FlowError> {
    let mut total: u64 = 0;
    for index in 0..job.units {
        let step = scope.enter(&unit_step(index))?;
        match job.world.unit(&step, index).await {
            Ok(value) => total = total.saturating_add(value),
            Err(_) => return Ok(Err(index)),
        }
    }
    Ok(Ok(total))
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let tenant = identity(store_dir.as_path());
    let units = world.stats().len() as u32;

    let host = Host::builder(&tenant)
        .map_err(|_| RecoveryError::NoStore)?
        .store(store_dir)
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let task = task(TASK_NAME, |scope: Scope, job: Job| async move {
        perform(scope, job).await
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host
        .run(&task, Job { world: world.clone(), units })
        .await;

    if report.disposition().is_success() {
        match report.output() {
            Some(Ok(total)) => {
                let ledger = world.ledger();
                if !ledger.applied(EFFECT) {
                    ledger.apply(EFFECT);
                }
                Ok(*total)
            }
            Some(Err(index)) => Err(RecoveryError::Unit { index: *index }),
            None => Err(RecoveryError::Deadline),
        }
    } else {
        Err(RecoveryError::Deadline)
    }
}

use std::num::NonZeroUsize;
use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::{Store, UnitError, World};
use lgwks_bot::script::{each, FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

// Everything that must be identical between the first attempt and a resume.
// The run identity is a constant, never a fresh random value, so a later call
// with the same store_dir finds this run's committed records.
const TENANT: &str = "recover";
const TASK: &str = "recover";
const RUN_ID: &str = "recover";
const FANOUT_STEP: &str = "units";
const LEDGER_EFFECT: &str = "recover";
const UNIT_PREFIX: &str = "unit:";
const NO_LEDGER: &str = "no-ledger";
const MAX_AT_ONCE: usize = 8;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // Refuse before starting anything if there is no ledger to reach.
    let _ = world.ledger().ok_or(RecoveryError::NoLedger)?;

    // A durable store on disk, under the fixed run identity. The same
    // (store_dir, RUN_ID) pair on the second call is what lets the resumed
    // attempt replay records instead of re-running unit bodies.
    let store = Store::open(&store_dir, RUN_ID).map_err(|_| RecoveryError::NoStore)?;

    // Install the store on the host. The host applies `deadline` with `within`,
    // so a timeout drops the whole task body and every unit body it owns.
    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .store(store)
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let count = world.stats().len() as u32;
    let indices: Vec<u32> = (0..count).collect();
    let pool = Some(NonZeroUsize::new(MAX_AT_ONCE).ok_or(RecoveryError::NoStore)?);

    // One helper (drive) builds the task body; both this attempt and any resume
    // go through it, so the step names and ordering are identical each time.
    let body_world = world.clone();
    let body = move |scope: Scope, _input: ()| {
        let world = body_world.clone();
        let indices = indices.clone();
        async move { drive(scope, world, indices, pool).await }
    };

    let task = task(TASK, body).map_err(|_| RecoveryError::NoStore)?;

    // No detached task and no spawn: the returned future owns host.run, which
    // owns the body, which owns every unit body driven by `each`. Dropping this
    // future therefore drops all of them, leaving nothing live after SETTLE.
    let report = host.run(&task, ()).await;
    let disposition = report.disposition();

    match disposition {
        Disposition::Succeeded => report.output().copied().ok_or(RecoveryError::NoLedger),
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        Disposition::Failed | Disposition::Refused => Err(classify(report.error())),
    }
}

// The task body, reused by the first attempt and the resume. `each` runs the
// units with a bound and owns its bodies; on failure or drop it cancels and
// drops them, so nothing outlives this future.
async fn drive(
    scope: Scope,
    world: World,
    indices: Vec<u32>,
    pool: Option<NonZeroUsize>,
) -> Result<u64, FlowError> {
    let values = each(&scope, FANOUT_STEP, pool, indices, |unit_scope, index| {
        let world = world.clone();
        async move {
            match world.unit(&unit_scope, index).await {
                Ok(value) => Ok(value),
                // Carry the failing index out on the located error so the
                // caller can report `Unit { index }`.
                Err(UnitError::Unit { index }) => {
                    Err(FlowError::failed(format!("{UNIT_PREFIX}{index}")))
                }
            }
        }
    })
    .await?;

    let total = values.into_iter().fold(0u64, u64::saturating_add);

    // The harness's only deduplication is read-then-apply. On the resume the
    // effect was already committed, so this second read keeps applies() at 1.
    let ledger = match world.ledger() {
        Some(ledger) => ledger,
        None => return Err(FlowError::failed(NO_LEDGER)),
    };
    if !ledger.applied(LEDGER_EFFECT) {
        ledger.apply(LEDGER_EFFECT);
    }

    Ok(total)
}

// Map a located FlowError back to the small RecoveryError surface. A unit
// failure carries its index in the reason; everything else can only arise from
// the deadline/cancellation race, so it becomes Deadline.
fn classify(error: Option<&FlowError>) -> RecoveryError {
    match error {
        Some(FlowError::Failed { reason, .. }) => {
            let reason: &str = reason;
            if reason == NO_LEDGER {
                RecoveryError::NoLedger
            } else if let Some(index) = reason
                .strip_prefix(UNIT_PREFIX)
                .and_then(|raw| raw.parse::<u32>().ok())
            {
                RecoveryError::Unit { index }
            } else {
                RecoveryError::Deadline
            }
        }
        _ => RecoveryError::Deadline,
    }
}

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::script::{each, FlowError, Scope};
use lgwks_bot::task::{task, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

const TENANT: &str = "recovery";
const NAME: &str = "recover";
const EFFECT: &str = "recover";

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let ledger = world.ledger().ok_or(RecoveryError::NoLedger)?;
    let store = world.store(&store_dir).ok_or(RecoveryError::NoStore)?;

    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .store(store)
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let body = |scope: Scope, world: World| async move { run_units(&scope, world).await };
    let task = task(NAME, body).expect("the static task name is valid");

    let report = host.run(&task, world).await;

    match report.into_result() {
        Ok(total) => {
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        }
        Err(FlowError::TimedOut { .. }) | Err(FlowError::Cancelled { .. }) => {
            Err(RecoveryError::Deadline)
        }
        Err(err) => Err(RecoveryError::Unit { index: locate(&err) }),
    }
}

async fn run_units(scope: &Scope, world: World) -> Result<u64, FlowError> {
    let count = world.len() as u32;
    let values = each(
        scope,
        "units",
        None,
        0..count,
        move |unit: Scope, index: u32| {
            let world = world.clone();
            async move {
                world
                    .unit(&unit, index)
                    .await
                    .map_err(|UnitError::Unit { index }| {
                        FlowError::failed(format!("unit {index} failed"))
                    })
            }
        },
    )
    .await?;
    Ok(values.into_iter().sum())
}

fn locate(err: &FlowError) -> u32 {
    let at = match err {
        FlowError::Cancelled { at } => at.to_string(),
        FlowError::TimedOut { at, .. } => at.to_string(),
        FlowError::Exhausted { at, .. } => at.to_string(),
        FlowError::Failed { at, .. } => at.to_string(),
        FlowError::Transient { at, .. } => at.to_string(),
        FlowError::Bot { at, .. } => at.to_string(),
        _ => String::new(),
    };
    at.rsplit(|c: char| !c.is_ascii_digit())
        .find(|segment| !segment.is_empty())
        .and_then(|segment| segment.parse::<u32>().ok())
        .unwrap_or(0)
}

