const TENANT: &str = "recovery";

const EFFECT: &str = "recover";

const RUN: &str = "0f9d3a17c25b4e806b1de4372f5a9c60";

const STEP: &str = "units";

type Failed = Arc<Mutex<Option<u32>>>;

type Body = std::pin::Pin<Box<dyn std::future::Future<Output = Result<u64, FlowError>>>>;

fn recovery_task(
    world: World,
    failed: Failed,
) -> Result<lgwks_bot::task::Task<impl Fn(Scope, u32) -> Body>, RecoveryError> {
    let width = world.width();
    task(STEP, move |scope: Scope, _attempt: u32| -> Body {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        Box::pin(async move {
            let mut total: u64 = 0;
            for index in 0..width {
                match world.unit(&scope, index).await {
                    Ok(value) => total = total.saturating_add(value),
                    Err(UnitError::Unit { index }) => {
                        *failed.lock().unwrap_or_else(PoisonError::into_inner) = Some(index);
                        return Err(FlowError::failed(format!("unit {index} failed")));
                    }
                }
            }
            let ledger: Ledger = world.ledger().clone();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        })
    })
    .map_err(|_| RecoveryError::NoStore)
}

fn recovery_host(store_dir: &std::path::Path, deadline: Duration) -> Result<Host, RecoveryError> {
    Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .run_store(store_dir)
        .map_err(|_| RecoveryError::NoStore)?
        .build()
        .map_err(|_| RecoveryError::NoStore)
}

fn into_result(report: &lgwks_bot::task::Report<u64>, failed: &Failed) -> Result<u64, RecoveryError> {
    match report.disposition() {
        Disposition::Succeeded => report
            .output()
            .copied()
            .ok_or(RecoveryError::NoLedger),
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        _ => {
            let index = failed.lock().unwrap_or_else(PoisonError::into_inner);
            Err(match *index {
                Some(index) => RecoveryError::Unit { index },
                None => RecoveryError::NoStore,
            })
        }
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN).map_err(|_| RecoveryError::NoStore)?;
    let host = recovery_host(&store_dir, deadline)?;
    let failed: Failed = Arc::new(Mutex::new(None));
    let work = recovery_task(world.clone(), Arc::clone(&failed))?;

    let first = host.run(&work, 0u32).await;
    let settled = into_result(&first, &failed);
    if settled.is_ok() {
        return settled;
    }

    let resumed = host.resume(run, &work, 0u32).await;
    let settled = into_result(&resumed, &failed);
    settled?;
    let _ = world.ledger().applies();
    Ok(resumed.output().copied().ok_or(RecoveryError::NoLedger)?)
}

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::script::{self, FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

async fn drive(world: &World, scope: &Scope) -> Result<u64, u32> {
    let mut total = 0u64;
    for index in world.units() {
        match world.unit(scope, index).await {
            Ok(value) => total += value,
            Err(UnitError::Unit { index }) => return Err(index),
        }
    }
    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let ledger = world.ledger().ok_or(RecoveryError::NoLedger)?;

    let store = script::Store::open(&store_dir).map_err(|_| RecoveryError::NoStore)?;
    let host = Host::builder("recovery")
        .map_err(|_| RecoveryError::NoStore)?
        .store(store)
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let job = task::task("recover", |scope: Scope, world: World| async move {
        Ok::<Result<u64, u32>, FlowError>(drive(&world, &scope).await)
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.run(&job, world.clone()).await;

    match report.disposition() {
        Disposition::Succeeded => match report.output() {
            Some(Ok(total)) => {
                if !ledger.applied("recover") {
                    ledger.apply("recover");
                }
                Ok(*total)
            }
            Some(Err(index)) => Err(RecoveryError::Unit { index: *index }),
            None => Err(RecoveryError::Unit { index: 0 }),
        },
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        Disposition::Failed | Disposition::Refused => Err(RecoveryError::Unit { index: 0 }),
    }
}

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut pending = ids.into_iter();
    let mut set: JoinSet<(u32, Result<u64, FetchError>)> = JoinSet::new();
    let mut sum: u64 = 0;

    for _ in 0..MAX_IN_FLIGHT {
        let id = match pending.next() {
            Some(id) => id,
            None => break,
        };
        let fetch = fetch.clone();
        let _ = set.spawn(async move { (id, fetch.fetch(id).await) });
    }

    loop {
        let first = match set.join_next().await {
            Some(result) => result,
            None => break,
        };

        let mut ready = vec![first];
        while let Some(result) = set.try_join_next() {
            ready.push(result);
        }

        let completions = ready.len();
        let mut failure: Option<u32> = None;

        for result in ready {
            match result {
                Ok((id, Err(_))) => {
                    if failure.is_none() {
                        failure = Some(id);
                    }
                }
                Ok((_, Ok(value))) => {
                    if failure.is_none() {
                        sum += value;
                    }
                }
                Err(_) => {}
            }
        }

        if let Some(id) = failure {
            set.abort_all();
            return Err(SolveError::Fetch { id });
        }

        for _ in 0..completions {
            let id = match pending.next() {
                Some(id) => id,
                None => break,
            };
            let fetch = fetch.clone();
            let _ = set.spawn(async move { (id, fetch.fetch(id).await) });
        }
    }

    Ok(sum)
}

