    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let started = std::time::Instant::now();
    let mut pending = ids.into_iter();
    let mut total: u64 = 0;

    loop {
        let mut wave: Vec<u32> = Vec::with_capacity(4);
        for _ in 0..4 {
            match pending.next() {
                Some(id) => wave.push(id),
                None => break,
            }
        }

        if wave.is_empty() {
            return Ok(total);
        }

        let remaining = match deadline.checked_sub(started.elapsed()) {
            Some(left) if !left.is_zero() => left,
            _ => return Err(SolveError::Deadline),
        };

        let futures = wave.into_iter().map(|id| {
            let fetch = fetch.clone();
            async move { (id, fetch.fetch(id).await) }
        });

        match timeout(remaining, join_all_bounded(4, futures)).await {
            Ok(results) => {
                for (id, outcome) in results {
                    match outcome {
                        Ok(value) => total += value,
                        Err(_) => return Err(SolveError::Fetch { id }),
                    }
                }
            }
            Err(_) => return Err(SolveError::Deadline),
        }
    }
}

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
