use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let work = async move {
        let mut set: JoinSet<(u32, Result<u64, FetchError>)> = JoinSet::new();
        let mut next = 0usize;
        let mut sum: u64 = 0;

        while next < ids.len() && set.len() < MAX_IN_FLIGHT {
            let id = ids[next];
            next += 1;
            let fetcher = fetch.clone();
            let _ = set.spawn(async move { (id, fetcher.fetch(id).await) });
        }

        while let Some(joined) = set.join_next().await {
            match joined {
                Ok((id, Ok(value))) => {
                    sum += value;
                    if next < ids.len() {
                        let id = ids[next];
                        next += 1;
                        let fetcher = fetch.clone();
                        let _ = set.spawn(async move { (id, fetcher.fetch(id).await) });
                    }
                }
                Ok((id, Err(_))) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id });
                }
                Err(_) => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let a_stage = stage.clone();
    let b_stage = stage.clone();

    let fetches = [
        fetch(a_stage, StageName::FetchA),
        fetch(b_stage, StageName::FetchB),
    ];

    let mut results = join_all_bounded(2usize, fetches).await.into_iter();

    let a_ok = results.next().unwrap_or(false);
    if !a_ok {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }

    let b_ok = results.next().unwrap_or(false);
    if !b_ok {
        return Err(PipelineError::Stage {
            name: StageName::FetchB,
        });
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

async fn fetch(stage: Stage, name: StageName) -> bool {
    stage.run(name).await.is_ok()
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type Fetch = Result<(StageName, Artifact), StageName>;

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let (_a, _b) = fetch_both(&stage).await?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

async fn fetch_both(stage: &Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut set: JoinSet<Fetch> = JoinSet::new();

    let a_stage = stage.clone();
    let _ = set.spawn(async move {
        a_stage
            .run(StageName::FetchA)
            .await
            .map(|artifact| (StageName::FetchA, artifact))
            .map_err(|_| StageName::FetchA)
    });

    let b_stage = stage.clone();
    let _ = set.spawn(async move {
        b_stage
            .run(StageName::FetchB)
            .await
            .map(|artifact| (StageName::FetchB, artifact))
            .map_err(|_| StageName::FetchB)
    });

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while let Some(joined) = set.join_next().await {
        match joined {
            Ok(Ok((name, artifact))) => match name {
                StageName::FetchA => a = Some(artifact),
                StageName::FetchB => b = Some(artifact),
                _ => {}
            },
            Ok(Err(name)) => return Err(PipelineError::Stage { name }),
            Err(_) => return Err(PipelineError::Cancelled),
        }
    }

    match (a, b) {
        (Some(a), Some(b)) => Ok((a, b)),
        _ => Err(PipelineError::Cancelled),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type FetchOutcome = (StageName, Result<Artifact, StageError>);

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut fetches: JoinSet<FetchOutcome> = JoinSet::new();

    let stage_a = stage.clone();
    fetches.spawn(async move { (StageName::FetchA, stage_a.run(StageName::FetchA).await) });

    let stage_b = stage.clone();
    fetches.spawn(async move { (StageName::FetchB, stage_b.run(StageName::FetchB).await) });

    let mut artifact_a: Option<Artifact> = None;
    let mut artifact_b: Option<Artifact> = None;
    let mut failure: Option<PipelineError> = None;

    while artifact_a.is_none() || artifact_b.is_none() {
        match fetches.join_next().await {
            Some(Ok((name, Ok(artifact)))) => match name {
                StageName::FetchA => artifact_a = Some(artifact),
                StageName::FetchB => artifact_b = Some(artifact),
                _ => {}
            },
            Some(Ok((name, Err(_stage_error)))) => {
                failure = Some(PipelineError::Stage { name });
                break;
            }
            Some(Err(_join_error)) => {
                failure = Some(PipelineError::Cancelled);
                break;
            }
            None => {
                failure = Some(PipelineError::Cancelled);
                break;
            }
        }
    }

    fetches.abort_all();
    drop(fetches);

    if let Some(error) = failure {
        return Err(error);
    }

    if artifact_a.is_none() || artifact_b.is_none() {
        return Err(PipelineError::Cancelled);
    }

    if stage.run(StageName::Combine).await.is_err() {
        return Err(PipelineError::Stage {
            name: StageName::Combine,
        });
    }

    match stage.run(StageName::Publish).await {
        Ok(published) => Ok(Published::from(published)),
        Err(_stage_error) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type FetchOutcome = (StageName, Result<Artifact, StageError>);

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut fetches: JoinSet<FetchOutcome> = JoinSet::new();

    let fetch_a_stage = stage.clone();
    let _fetch_a = fetches.spawn(async move {
        let result = fetch_a_stage.run(StageName::FetchA).await;
        (StageName::FetchA, result)
    });

    let fetch_b_stage = stage.clone();
    let _fetch_b = fetches.spawn(async move {
        let result = fetch_b_stage.run(StageName::FetchB).await;
        (StageName::FetchB, result)
    });

    let mut completed = 0usize;
    while completed < 2 {
        let joined = match fetches.join_next().await {
            Some(joined) => joined,
            None => break,
        };

        match joined {
            Ok((_, Ok(_artifact))) => completed += 1,
            Ok((name, Err(_error))) => {
                fetches.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Err(_join_error) => {
                fetches.abort_all();
                return Err(PipelineError::Cancelled);
            }
        }
    }

    if completed < 2 {
        fetches.abort_all();
        return Err(PipelineError::Cancelled);
    }

    match stage.run(StageName::Combine).await {
        Ok(_artifact) => {}
        Err(_error) => return Err(PipelineError::Stage { name: StageName::Combine }),
    }

    match stage.run(StageName::Publish).await {
        Ok(artifact) => Ok(Published::from(artifact)),
        Err(_error) => Err(PipelineError::Stage { name: StageName::Publish }),
    }
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let mut fetches = JoinSet::new();

    let stage_a = stage.clone();
    let _ = fetches.spawn(async move { (StageName::FetchA, stage_a.run(StageName::FetchA).await) });

    let stage_b = stage.clone();
    let _ = fetches.spawn(async move { (StageName::FetchB, stage_b.run(StageName::FetchB).await) });

    while let Some(joined) = fetches.join_next().await {
        match joined {
            Ok((_, Ok(_))) => {}
            Ok((name, Err(_))) => {
                fetches.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Err(_) => {
                fetches.abort_all();
                return Err(PipelineError::Stage {
                    name: StageName::FetchA,
                });
            }
        }
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: Stage, name: StageName) -> Result<(), ()> {
    match stage.run(name).await {
        Ok(_artifact) => Ok(()),
        Err(_) => Err(()),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let fetched = join_all_bounded(
            2,
            vec![
                run_stage(stage.clone(), StageName::FetchA),
                run_stage(stage.clone(), StageName::FetchB),
            ],
        )
        .await;

        if fetched[0].is_err() {
            return Err(PipelineError::Stage {
                name: StageName::FetchA,
            });
        }
        if fetched[1].is_err() {
            return Err(PipelineError::Stage {
                name: StageName::FetchB,
            });
        }

        let _ = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok(Published::from(artifact))
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn fetch(stage: Stage, name: StageName) -> Result<Artifact, StageError> {
    stage.run(name).await
}

async fn drive(stage: Stage) -> Result<Published, PipelineError> {
    let fetches = vec![
        fetch(stage.clone(), StageName::FetchA),
        fetch(stage.clone(), StageName::FetchB),
    ];

    let results = join_all_bounded(2, fetches).await;

    let mut results = results.into_iter();
    let first = results.next();
    let second = results.next();

    if !matches!(first, Some(Ok(_))) {
        return Err(PipelineError::Stage {
            name: StageName::FetchA,
        });
    }
    if !matches!(second, Some(Ok(_))) {
        return Err(PipelineError::Stage {
            name: StageName::FetchB,
        });
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, drive(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout_at, Instant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let deadline_at = Instant::now() + deadline;
    timeout_at(deadline_at, run_pipeline(stage, deadline_at))
        .await
        .unwrap_or(Err(PipelineError::Deadline))
}

async fn run_pipeline(stage: Stage, deadline_at: Instant) -> Result<Published, PipelineError> {
    run_fetches(stage.clone()).await?;

    if reached(&deadline_at) {
        return Err(PipelineError::Deadline);
    }
    run_stage(stage.clone(), StageName::Combine).await?;

    if reached(&deadline_at) {
        return Err(PipelineError::Deadline);
    }
    let artifact = run_stage(stage, StageName::Publish).await?;

    Ok(Published::from(artifact))
}

fn reached(deadline_at: &Instant) -> bool {
    Instant::now() >= *deadline_at
}

type StageOutcome = (StageName, Result<Artifact, StageError>);

async fn run_fetches(stage: Stage) -> Result<(), PipelineError> {
    let mut set: JoinSet<StageOutcome> = JoinSet::new();

    let first = stage.clone();
    set.spawn(async move {
        let outcome = first.run(StageName::FetchA).await;
        (StageName::FetchA, outcome)
    });

    set.spawn(async move {
        let outcome = stage.run(StageName::FetchB).await;
        (StageName::FetchB, outcome)
    });

    let mut a_ok = false;
    let mut b_ok = false;

    while let Some(joined) = set.join_next().await {
        match joined {
            Ok((StageName::FetchA, Ok(_))) => a_ok = true,
            Ok((StageName::FetchB, Ok(_))) => b_ok = true,
            Ok((name, Err(_))) => {
                set.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Ok((_, Ok(_))) => {}
            Err(_) => {
                set.abort_all();
                return Err(PipelineError::Cancelled);
            }
        }
    }

    if a_ok && b_ok {
        Ok(())
    } else {
        Err(PipelineError::Cancelled)
    }
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, PipelineError> {
    let mut set: JoinSet<StageOutcome> = JoinSet::new();

    set.spawn(async move {
        let outcome = stage.run(name).await;
        (name, outcome)
    });

    match set.join_next().await {
        Some(Ok((_, Ok(artifact)))) => Ok(artifact),
        Some(Ok((name, Err(_)))) => Err(PipelineError::Stage { name }),
        Some(Err(_)) => Err(PipelineError::Cancelled),
        None => Err(PipelineError::Cancelled),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match time::timeout(deadline, drive(&stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn drive(stage: &Stage) -> Result<Published, PipelineError> {
    let mut fetches: JoinSet<(StageName, Result<Artifact, StageName>)> = JoinSet::new();

    let a_stage = stage.clone();
    fetches.spawn(async move {
        let outcome = a_stage
            .run(StageName::FetchA)
            .await
            .map_err(|_| StageName::FetchA);
        (StageName::FetchA, outcome)
    });

    let b_stage = stage.clone();
    fetches.spawn(async move {
        let outcome = b_stage
            .run(StageName::FetchB)
            .await
            .map_err(|_| StageName::FetchB);
        (StageName::FetchB, outcome)
    });

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while let Some(joined) = fetches.join_next().await {
        match joined {
            Ok((name, Ok(artifact))) => match name {
                StageName::FetchA => a = Some(artifact),
                StageName::FetchB => b = Some(artifact),
                _ => {}
            },
            Ok((name, Err(_))) => return Err(PipelineError::Stage { name }),
            Err(_) => return Err(PipelineError::Cancelled),
        }
    }

    let _ = (a, b);

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let artifact = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(artifact))
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout_at, Instant};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let deadline_at = Instant::now() + deadline;

    let mut fetches: JoinSet<(StageName, Result<Artifact, StageError>)> = JoinSet::new();
    {
        let stage = stage.clone();
        let _ = fetches.spawn(async move {
            (StageName::FetchA, stage.run(StageName::FetchA).await)
        });
    }
    {
        let stage = stage.clone();
        let _ = fetches.spawn(async move {
            (StageName::FetchB, stage.run(StageName::FetchB).await)
        });
    }

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;

    while a.is_none() || b.is_none() {
        match timeout_at(deadline_at, fetches.join_next()).await {
            Ok(Some(Ok((name, Ok(artifact))))) => match name {
                StageName::FetchA => a = Some(artifact),
                StageName::FetchB => b = Some(artifact),
                _ => {}
            },
            Ok(Some(Ok((name, Err(_))))) => {
                fetches.abort_all();
                return Err(PipelineError::Stage { name });
            }
            Ok(Some(Err(_))) => {
                fetches.abort_all();
                return Err(PipelineError::Cancelled);
            }
            Ok(None) => break,
            Err(_) => {
                fetches.abort_all();
                return Err(PipelineError::Deadline);
            }
        }
    }

    if a.is_none() || b.is_none() {
        fetches.abort_all();
        return Err(PipelineError::Deadline);
    }

    if Instant::now() >= deadline_at {
        return Err(PipelineError::Deadline);
    }
    match timeout_at(deadline_at, stage.run(StageName::Combine)).await {
        Ok(Ok(_)) => {}
        Ok(Err(_)) => return Err(PipelineError::Stage { name: StageName::Combine }),
        Err(_) => return Err(PipelineError::Deadline),
    }

    if Instant::now() >= deadline_at {
        return Err(PipelineError::Deadline);
    }
    match timeout_at(deadline_at, stage.run(StageName::Publish)).await {
        Ok(Ok(artifact)) => Ok(Published::from(artifact)),
        Ok(Err(_)) => Err(PipelineError::Stage { name: StageName::Publish }),
        Err(_) => Err(PipelineError::Deadline),
    }
}

//! Bounded, fail-fast, owning aggregation of `Fetcher::fetch` calls.
//!
//! The whole fan-out is driven inside the `solve` future itself: every in-flight
//! fetch future is owned by `Solve` and stored boxed, so dropping the returned
//! future drops every running fetch with it.

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::{Duration, Instant};

/// Hard cap on concurrent `fetch` calls.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchResult = Result<u64, ai_task_support::FetchError>;
type FetchFuture<'a> = Pin<Box<dyn Future<Output = FetchResult> + Send + 'a>>;

struct InFlight<'a> {
    id: u32,
    fut: FetchFuture<'a>,
}

/// One-shot wakeup at the deadline.
///
/// A detached helper thread parks until the deadline elapses and then wakes
/// the task, so a deadline is observed even when every in-flight fetch is
/// still pending. Dropping the `Timer` (which happens when `Solve` is dropped
/// or completes) stops and unparks the thread immediately.
struct Timer {
    stop: Arc<AtomicBool>,
    thread: Option<thread::Thread>,
}

impl Timer {
    fn start(after: Duration, waker: Waker) -> Timer {
        let stop = Arc::new(AtomicBool::new(false));
        let flag = Arc::clone(&stop);
        let handle = thread::spawn(move || {
            let start = Instant::now();
            loop {
                if flag.load(Ordering::SeqCst) {
                    return;
                }
                let elapsed = start.elapsed();
                if elapsed >= after {
                    waker.wake();
                    return;
                }
                thread::park_timeout(after - elapsed);
            }
        });
        Timer {
            stop,
            thread: Some(handle.thread().clone()),
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        if let Some(t) = self.thread.take() {
            t.unpark();
        }
    }
}

struct Solve<'a> {
    fetch: &'a ai_task_support::Fetcher,
    ids: std::vec::IntoIter<u32>,
    in_flight: Vec<InFlight<'a>>,
    sum: u64,
    start: Instant,
    deadline: Duration,
    timer: Option<Timer>,
}

impl<'a> Future for Solve<'a> {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let me = self.get_mut();

        if me.timer.is_none() {
            let remaining = me.deadline.saturating_sub(me.start.elapsed());
            me.timer = Some(Timer::start(remaining, cx.waker().clone()));
        }

        let waker = cx.waker().clone();

        loop {
            let mut ctx = Context::from_waker(&waker);
            let mut kept: Vec<InFlight<'a>> = Vec::with_capacity(me.in_flight.len());
            let mut failed: Option<u32> = None;

            for mut slot in me.in_flight.drain(..) {
                match slot.fut.as_mut().poll(&mut ctx) {
                    Poll::Ready(Ok(value)) => {
                        me.sum = me.sum.saturating_add(value);
                    }
                    Poll::Ready(Err(_)) => {
                        failed = Some(slot.id);
                        break;
                    }
                    Poll::Pending => kept.push(slot),
                }
            }

            me.in_flight = kept;

            if let Some(id) = failed {
                me.ids = Vec::new().into_iter();
                return Poll::Ready(Err(SolveError::Fetch { id }));
            }

            if me.in_flight.is_empty() && me.ids.len() == 0 {
                return Poll::Ready(Ok(me.sum));
            }

            if me.start.elapsed() >= me.deadline {
                me.in_flight = Vec::new();
                me.ids = Vec::new().into_iter();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            let fetcher = me.fetch;
            let mut started = false;
            while me.in_flight.len() < MAX_IN_FLIGHT {
                match me.ids.next() {
                    Some(id) => {
                        let fut: FetchFuture<'a> = Box::pin(fetcher.fetch(id));
                        me.in_flight.push(InFlight { id, fut });
                        started = true;
                    }
                    None => break,
                }
            }

            if !started {
                return Poll::Pending;
            }
        }
    }
}

/// Aggregate `fetch` over `ids` with at most four calls in flight.
///
/// Resolves with the sum of every value, or with the first observed failure,
/// the deadline, or a cancellation. Dropping the returned future drops every
/// fetch it owns.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let state = Solve {
        fetch: &fetch,
        ids: ids.into_iter(),
        in_flight: Vec::with_capacity(MAX_IN_FLIGHT),
        sum: 0,
        start: Instant::now(),
        deadline,
        timer: None,
    };

    Box::pin(state).await
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::time::{Duration, Instant};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

fn lock<'a, T>(m: &'a Mutex<T>) -> MutexGuard<'a, T> {
    m.lock().unwrap_or_else(|e| e.into_inner())
}

type FetchOutput = (u32, Result<u64, ai_task_support::FetchError>);
type FetchFuture = Pin<Box<dyn Future<Output = FetchOutput>>>;

/// Waker handed to every in-flight `fetch` future: waking it re-polls `solve`.
struct ChildWake {
    inner: Mutex<Option<Waker>>,
}

impl ChildWake {
    fn new() -> Arc<ChildWake> {
        Arc::new(ChildWake {
            inner: Mutex::new(None),
        })
    }

    fn waker(self: &Arc<ChildWake>) -> Waker {
        Waker::from(Arc::clone(self))
    }

    fn set(&self, w: &Waker) {
        *lock(&self.inner) = Some(w.clone());
    }

    fn clear(&self) {
        *lock(&self.inner) = None;
    }
}

impl Wake for ChildWake {
    fn wake(self: Arc<Self>) {
        let w = lock(&self.inner).take();
        if let Some(w) = w {
            w.wake();
        }
    }

    fn wake_by_ref(self: &Arc<ChildWake>) {
        // Never hold the lock while waking: a waker may re-enter the task.
        let w = lock(&self.inner).as_ref().cloned();
        if let Some(w) = w {
            w.wake_by_ref();
        }
    }
}

struct TimerInner {
    waker: Option<Waker>,
    stopped: bool,
    fired: bool,
}

struct TimerState {
    inner: Mutex<TimerInner>,
    cv: Condvar,
}

/// A single wakeup source for the overall deadline. It runs on its own thread so
/// the deadline is honoured even when no fetch future ever completes.
struct Timer {
    state: Arc<TimerState>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl Timer {
    fn start(dur: Duration) -> Timer {
        let state = Arc::new(TimerState {
            inner: Mutex::new(TimerInner {
                waker: None,
                stopped: false,
                fired: false,
            }),
            cv: Condvar::new(),
        });
        let thread_state = Arc::clone(&state);
        let handle = std::thread::Builder::new()
            .name("solve-deadline".to_string())
            .spawn(move || {
                let now = Instant::now();
                let at = now.checked_add(dur).unwrap_or(now);
                loop {
                    let mut guard = lock(&thread_state.inner);
                    if guard.stopped {
                        return;
                    }
                    let now = Instant::now();
                    if now >= at {
                        guard.fired = true;
                        let w = guard.waker.take();
                        drop(guard);
                        if let Some(w) = w {
                            w.wake();
                        }
                        return;
                    }
                    let remaining = at - now;
                    let (guard, _timeout) = thread_state
                        .cv
                        .wait_timeout(guard, remaining)
                        .unwrap_or_else(|e| e.into_inner());
                    drop(guard);
                }
            })
            .expect("failed to spawn deadline timer");
        Timer {
            state,
            handle: Some(handle),
        }
    }

    fn set_waker(&self, w: &Waker) {
        // If the thread already fired, wake straight away: the waker it would
        // have used is gone, and a missed wakeup would hang the solve.
        let fire = {
            let mut guard = lock(&self.state.inner);
            if guard.stopped {
                false
            } else if guard.fired {
                true
            } else {
                guard.waker = Some(w.clone());
                false
            }
        };
        if fire {
            w.wake_by_ref();
        }
    }

    fn stop(&mut self) {
        {
            let mut guard = lock(&self.state.inner);
            guard.stopped = true;
            guard.fired = true;
            guard.waker = None;
        }
        self.state.cv.notify_all();
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        self.stop();
    }
}

struct Solve {
    ids: Vec<u32>,
    next: usize,
    fetch: Arc<ai_task_support::Fetcher>,
    running: Vec<FetchFuture>,
    sum: u64,
    deadline_at: Instant,
    timer: Option<Timer>,
    child_wake: Arc<ChildWake>,
}

impl Solve {
    fn new(ids: Vec<u32>, fetch: ai_task_support::Fetcher, deadline: Duration) -> Solve {
        let start = Instant::now();
        let deadline_at = start
            .checked_add(deadline)
            .unwrap_or(start + Duration::from_secs(86_400));
        Solve {
            ids,
            next: 0,
            fetch: Arc::new(fetch),
            running: Vec::new(),
            sum: 0,
            deadline_at,
            timer: None,
            child_wake: ChildWake::new(),
        }
    }

    fn start_timer(&mut self, cx: &Context<'_>) {
        if self.timer.is_none() {
            let remaining = self.deadline_at.saturating_duration_since(Instant::now());
            let timer = Timer::start(remaining);
            timer.set_waker(cx.waker());
            self.timer = Some(timer);
        } else if let Some(timer) = self.timer.as_ref() {
            timer.set_waker(cx.waker());
        }
    }

    fn finish(&mut self, out: Result<u64, SolveError>) -> Poll<Result<u64, SolveError>> {
        self.running.clear();
        self.child_wake.clear();
        self.timer = None;
        Poll::Ready(out)
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        this.child_wake.set(cx.waker());
        let child_waker = this.child_wake.waker();
        let mut child_ctx = Context::from_waker(&child_waker);

        loop {
            if this.running.is_empty() && this.next >= this.ids.len() {
                let sum = this.sum;
                return this.finish(Ok(sum));
            }
            if Instant::now() >= this.deadline_at {
                return this.finish(Err(SolveError::Deadline));
            }
            this.start_timer(cx);

            // Drain what is already in flight before considering new work, so
            // no fetch is started once a failure could be visible.
            let mut progress = false;
            let mut i = 0;
            while i < this.running.len() {
                let polled = this.running[i].as_mut().poll(&mut child_ctx);
                match polled {
                    Poll::Pending => i += 1,
                    Poll::Ready((_, Ok(value))) => {
                        this.running.swap_remove(i);
                        this.sum = this.sum.wrapping_add(value);
                        progress = true;
                    }
                    Poll::Ready((id, Err(_))) => {
                        return this.finish(Err(SolveError::Fetch { id }));
                    }
                }
            }

            if progress {
                continue;
            }

            if this.running.len() < MAX_IN_FLIGHT && this.next < this.ids.len() {
                if Instant::now() >= this.deadline_at {
                    return this.finish(Err(SolveError::Deadline));
                }
                let id = this.ids[this.next];
                this.next += 1;
                let fetch = Arc::clone(&this.fetch);
                let fut: FetchFuture = Box::pin(async move {
                    let out = fetch.fetch(id).await;
                    (id, out)
                });
                this.running.push(fut);
                continue;
            }

            return Poll::Pending;
        }
    }
}

/// Fetch every `id` with at most four requests in flight, summing the results.
/// Fails fast on the first error, honours `deadline`, and drops every running
/// fetch when the returned future is dropped.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solve::new(ids, fetch, deadline).await
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;
use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

/// Hard ceiling on how many `fetch` calls may be in flight at once.
const CONCURRENCY: usize = 4;
const TENANT_NAME: &str = "aggregate";
const STEP: &str = "fetch";

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    // Nothing to do: resolve immediately without touching the fetcher.
    if ids.is_empty() {
        return Ok(0);
    }

    // A deadline that is already spent must not start any fetch at all.
    if Instant::now().elapsed() >= deadline {
        return Err(SolveError::Deadline);
    }

    // Reported only if the fan-out reports a failure without naming an id itself.
    let fallback_id = ids[0];

    let tenant = match Tenant::new(TENANT_NAME) {
        Ok(tenant) => tenant,
        Err(_) => return Err(SolveError::Cancelled),
    };
    let scope = Scope::root(tenant);

    let limit = match NonZeroUsize::new(CONCURRENCY) {
        Some(limit) => limit,
        None => return Err(SolveError::Cancelled),
    };

    // Records the first id observed to fail, so the caller learns which one.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failure_slot = Arc::clone(&failed);

    let fan_out = each(
        &scope,
        STEP,
        Some(limit),
        ids,
        move |_step: Scope, id: u32| {
            let fetch = fetch.clone();
            let failure_slot = Arc::clone(&failure_slot);
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        {
                            let mut slot =
                                failure_slot.lock().unwrap_or_else(|e| e.into_inner());
                            if slot.is_none() {
                                *slot = Some(id);
                            }
                        }
                        // Fail-fast: `each` observes this error, drops every
                        // body still running, and starts no further item.
                        Err(FlowError::failed(format!("fetch failed for {id}")))
                    }
                }
            }
        },
    );

    // `within` races the fan-out against the deadline and against
    // cancellation, dropping the fan-out (and with it every live fetch) when
    // either one wins. Dropping this future drops it too, so a caller that
    // walks away mid-run leaves no fetch running.
    //
    // Its error type is the body's own: the body already returns
    // `Result<Vec<u64>, FlowError>`, so a fetch failure arrives here as the
    // same `FlowError` the fan-out produced, and a lost race as
    // `TimedOut` / `Cancelled`.
    let outcome: Result<Vec<u64>, FlowError> = within(&scope, STEP, deadline, fan_out).await;

    match outcome {
        Ok(values) => Ok(values
            .into_iter()
            .fold(0u64, |acc, value| acc.wrapping_add(value))),
        Err(flow) => {
            // A recorded id means a fetch failed; that beats a deadline or a
            // cancellation observed around the same time.
            let recorded = failed.lock().unwrap_or_else(|e| e.into_inner());
            if let Some(id) = *recorded {
                return Err(SolveError::Fetch { id });
            }
            drop(recorded);

            if flow.is_cancelled() {
                Err(SolveError::Cancelled)
            } else {
                Err(SolveError::Deadline)
            }
        }
    }
    .map_err(|err| match err {
        SolveError::Fetch { .. } => {
            failed
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .map_or(SolveError::Fetch { id: fallback_id }, |id| SolveError::Fetch { id })
        }
        other => other,
    })
}

use std::collections::VecDeque;
use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

/// Upper bound on simultaneously live `fetch` calls owned by [`solve`].
const MAX_INFLIGHT: usize = 4;

/// Granularity of the deadline watchdog thread's sleep loop.
const TIMER_TICK: Duration = Duration::from_millis(10);

/// Every failure mode [`solve`] can report.
#[derive(Debug)]
pub enum SolveError {
    /// The `fetch` for this id returned an error.
    Fetch { id: u32 },
    /// The overall deadline elapsed before all fetches completed.
    Deadline,
    /// The aggregation was cancelled.
    Cancelled,
}

impl std::fmt::Display for SolveError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SolveError::Fetch { id } => write!(f, "fetch failed for id {id}"),
            SolveError::Deadline => f.write_str("deadline exceeded"),
            SolveError::Cancelled => f.write_str("cancelled"),
        }
    }
}

impl std::error::Error for SolveError {}

/// One `fetch` call that this future owns. Dropping it drops the underlying
/// future, so nothing outlives the aggregation.
struct Running {
    id: u32,
    call: Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send>>,
}

/// Drops set the stop flag so the deadline watchdog thread ends promptly
/// instead of lingering until the original deadline.
struct Watchdog {
    stop: Arc<AtomicBool>,
}

impl Drop for Watchdog {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Relaxed);
    }
}

/// Fetch every id with at most [`MAX_INFLIGHT`] calls in flight and sum the
/// values. Fails fast on the first error, honours the deadline, and owns every
/// `fetch` future so that dropping this future stops all work.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let started = Instant::now();
    let fetcher = Arc::new(fetch);
    let waker_slot: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
    let stop = Arc::new(AtomicBool::new(false));
    let _watchdog = Watchdog {
        stop: Arc::clone(&stop),
    };

    let mut queue: VecDeque<u32> = VecDeque::from(ids);
    let mut running: VecDeque<Running> = VecDeque::new();
    let mut watchdog_armed = false;
    let mut total: u64 = 0;

    poll_fn(move |cx| {
        loop {
            if started.elapsed() >= deadline {
                running.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            while running.len() < MAX_INFLIGHT {
                let Some(id) = queue.pop_front() else { break };
                let handle = Arc::clone(&fetcher);
                running.push_back(Running {
                    id,
                    call: Box::pin(async move { handle.fetch(id).await }),
                });
            }

            if running.is_empty() {
                return Poll::Ready(Ok(total));
            }

            let mut progressed = false;
            for _ in 0..running.len() {
                let Some(entry) = running.pop_front() else { break };
                let Running { id, mut call } = entry;
                match call.as_mut().poll(cx) {
                    Poll::Ready(Ok(value)) => {
                        total = total.wrapping_add(value);
                        progressed = true;
                    }
                    Poll::Ready(Err(_)) => {
                        // Stop everything, including fetches still in flight.
                        running.clear();
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                    Poll::Pending => running.push_back(Running { id, call }),
                }
            }

            if progressed {
                continue;
            }

            if let Ok(mut guard) = waker_slot.lock() {
                *guard = Some(cx.waker().clone());
            }

            if !watchdog_armed {
                watchdog_armed = true;
                let slot = Arc::clone(&waker_slot);
                let stop_flag = Arc::clone(&stop);
                let _ = std::thread::Builder::new()
                    .name(String::from("aggregate-deadline"))
                    .spawn(move || loop {
                        if stop_flag.load(Ordering::Relaxed) {
                            return;
                        }
                        let elapsed = started.elapsed();
                        if elapsed >= deadline {
                            if let Ok(mut guard) = slot.lock() {
                                if let Some(waker) = guard.take() {
                                    waker.wake();
                                }
                            }
                            return;
                        }
                        std::thread::sleep((deadline - elapsed).min(TIMER_TICK));
                    });
            }

            // Re-check after arming so a wake-up that raced with the poll
            // above cannot be missed.
            if started.elapsed() >= deadline {
                running.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            return Poll::Pending;
        }
    })
    .await
}

//! Bounded-concurrency, fail-fast, drop-safe fan-out over `Fetcher::fetch`.

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};
use std::time::{Duration, Instant};

use ai_task_support::Fetcher;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX: usize = 4;

type FetchResult = Result<u64, ai_task_support::FetchError>;

struct SignalState {
    waker: Option<Waker>,
    done: bool,
}

struct Signal {
    state: Mutex<SignalState>,
    cv: Condvar,
}

impl Signal {
    fn wake(&self) {
        let w = self.state.lock().unwrap().waker.clone();
        if let Some(w) = w {
            w.wake();
        }
    }

    fn finish(&self) {
        let mut g = self.state.lock().unwrap();
        g.done = true;
        g.waker = None;
        drop(g);
        self.cv.notify_all();
    }
}

unsafe fn waker_clone(ptr: *const ()) -> RawWaker {
    let arc = unsafe { Arc::from_raw(ptr as *const Signal) };
    let cloned = arc.clone();
    std::mem::forget(arc);
    RawWaker::new(Arc::into_raw(cloned) as *const (), &VTABLE)
}

unsafe fn waker_wake(ptr: *const ()) {
    let arc = unsafe { Arc::from_raw(ptr as *const Signal) };
    arc.wake();
}

unsafe fn waker_wake_by_ref(ptr: *const ()) {
    let arc = unsafe { Arc::from_raw(ptr as *const Signal) };
    arc.wake();
    std::mem::forget(arc);
}

unsafe fn waker_drop(ptr: *const ()) {
    drop(unsafe { Arc::from_raw(ptr as *const Signal) });
}

static VTABLE: RawWakerVTable =
    RawWakerVTable::new(waker_clone, waker_wake, waker_wake_by_ref, waker_drop);

fn arm(signal: Arc<Signal>, deadline: Instant) {
    std::thread::spawn(move || {
        let mut g = signal.state.lock().unwrap();
        if g.done {
            return;
        }
        let now = Instant::now();
        if deadline > now {
            let (ng, _) = signal.cv.wait_timeout(g, deadline - now).unwrap();
            g = ng;
        }
        if g.done {
            return;
        }
        let w = g.waker.clone();
        drop(g);
        if let Some(w) = w {
            w.wake();
        }
    });
}

struct Slot {
    id: u32,
    fut: Pin<Box<dyn Future<Output = FetchResult>>>,
    value: Option<u64>,
}

struct Solve {
    fetch: Fetcher,
    ids: std::vec::IntoIter<u32>,
    slots: [Option<Slot>; MAX],
    sum: u64,
    deadline: Instant,
    signal: Arc<Signal>,
    finished: bool,
}

impl Solve {
    fn new(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Self {
        let now = Instant::now();
        let at = now
            .checked_add(deadline)
            .unwrap_or_else(|| now + Duration::from_secs(31_536_000));
        let signal = Arc::new(Signal {
            state: Mutex::new(SignalState {
                waker: None,
                done: false,
            }),
            cv: Condvar::new(),
        });
        arm(Arc::clone(&signal), at);
        Solve {
            fetch,
            ids: ids.into_iter(),
            slots: [None, None, None, None],
            sum: 0,
            deadline: at,
            signal,
            finished: false,
        }
    }

    fn idle(&self) -> bool {
        self.slots.iter().all(|s| s.is_none())
    }

    fn done_ids(&self) -> bool {
        self.ids.as_slice().is_empty()
    }
}

impl Drop for Solve {
    fn drop(&mut self) {
        self.signal.finish();
    }
}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if this.finished {
            return Poll::Ready(Err(SolveError::Cancelled));
        }
        {
            let mut g = this.signal.state.lock().unwrap();
            g.waker = Some(cx.waker().clone());
        }

        let mut failure: Option<SolveError> = None;
        for slot in this.slots.iter_mut() {
            let Some(s) = slot.as_mut() else { continue };
            if s.value.is_some() {
                continue;
            }
            match s.fut.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => s.value = Some(v),
                Poll::Ready(Err(_)) => {
                    failure = Some(SolveError::Fetch { id: s.id });
                    break;
                }
                Poll::Pending => {}
            }
        }

        for slot in this.slots.iter_mut() {
            let taken = match slot.as_mut() {
                Some(s) => s.value.take(),
                None => None,
            };
            if let Some(v) = taken {
                this.sum = this.sum.wrapping_add(v);
                *slot = None;
            }
        }

        if let Some(err) = failure {
            this.finished = true;
            this.slots = [None, None, None, None];
            this.signal.finish();
            return Poll::Ready(Err(err));
        }

        if this.done_ids() && this.idle() {
            this.finished = true;
            this.signal.finish();
            return Poll::Ready(Ok(this.sum));
        }

        if Instant::now() >= this.deadline {
            this.finished = true;
            this.slots = [None, None, None, None];
            this.signal.finish();
            return Poll::Ready(Err(SolveError::Deadline));
        }

        for i in 0..MAX {
            if this.slots[i].is_some() {
                continue;
            }
            let Some(id) = this.ids.next() else { break };
            let f = this.fetch.clone();
            let fut: Pin<Box<dyn Future<Output = FetchResult>>> =
                Box::pin(async move { f.fetch(id).await });
            this.slots[i] = Some(Slot {
                id,
                fut,
                value: None,
            });
        }

        if this.done_ids() && this.idle() {
            this.finished = true;
            this.signal.finish();
            return Poll::Ready(Ok(this.sum));
        }

        Poll::Pending
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solve::new(ids, fetch, deadline).await
}

//! Bounded, deadline-aware aggregation over `ai_task_support::Fetcher`.
//!
//! `solve` owns every `fetch` future it starts: at most four are alive at any
//! moment, no new one is started once a failure is observed, and dropping the
//! returned future drops every in-flight `fetch` with it.

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering as AtomicOrdering};
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

/// Maximum number of `fetch` calls allowed to be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

/// Every way `solve` can fail.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` for `id` returned an error.
    Fetch { id: u32 },
    /// The overall deadline passed.
    Deadline,
    /// The caller cancelled the work.
    Cancelled,
}

/// Aggregate the values fetched for every id, at most [`MAX_IN_FLIGHT`] at a
/// time, giving up as soon as a fetch fails or the deadline passes.
pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    let mut run = Run::new(ids, fetch, deadline);
    std::future::poll_fn(move |cx| run.step(cx)).await
}

fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

// ---------------------------------------------------------------------------
// deadline
// ---------------------------------------------------------------------------

/// A one-shot signal raised by a detached sleeper once the budget is spent.
///
/// The sleeper holds nothing but a clone of the shared state, so it can never
/// keep a `fetch` alive past the drop of the `solve` future.
struct Timer {
    fired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

impl Timer {
    fn arm(span: Duration) -> Arc<Timer> {
        let timer = Arc::new(Timer {
            fired: AtomicBool::new(false),
            waker: Mutex::new(None),
        });
        let signal = Arc::clone(&timer);
        let spawned = std::thread::Builder::new()
            .name("solve-deadline".to_string())
            .spawn(move || {
                std::thread::sleep(span);
                signal.fired.store(true, AtomicOrdering::Release);
                if let Some(waker) = lock(&signal.waker).take() {
                    waker.wake();
                }
            });
        if spawned.is_err() {
            // No sleeper: fall back to the wall-clock check in `Run::step`.
            timer.fired.store(true, AtomicOrdering::Release);
        }
        timer
    }

    fn park(&self, cx: &Context<'_>) {
        let mut slot = lock(&self.waker);
        let stale = match slot.as_ref() {
            Some(waker) => !waker.will_wake(cx.waker()),
            None => true,
        };
        if stale {
            *slot = Some(cx.waker().clone());
        }
    }

    fn expired(&self) -> bool {
        self.fired.load(AtomicOrdering::Acquire)
    }
}

// ---------------------------------------------------------------------------
// the aggregation itself
// ---------------------------------------------------------------------------

type FetchFuture = Pin<Box<dyn Future<Output = Result<u64, FetchError>> + Send>>;

struct Slot {
    id: u32,
    work: Option<FetchFuture>,
}

struct Run {
    fetcher: Fetcher,
    ids: Vec<u32>,
    next: usize,
    slots: Vec<Slot>,
    sum: u64,
    start: Instant,
    budget: Duration,
    timer: Arc<Timer>,
}

impl Run {
    fn new(ids: Vec<u32>, fetcher: Fetcher, budget: Duration) -> Run {
        Run {
            fetcher,
            ids,
            next: 0,
            slots: Vec::new(),
            sum: 0,
            start: Instant::now(),
            budget,
            timer: Timer::arm(budget),
        }
    }

    fn step(&mut self, cx: &mut Context<'_>) -> Poll<Result<u64, SolveError>> {
        loop {
            self.timer.park(cx);

            if self.timer.expired() || self.start.elapsed() >= self.budget {
                // Dropping the slots drops every live `fetch` with them.
                self.slots.clear();
                return Poll::Ready(Err(SolveError::Deadline));
            }

            // Refill the pool, never past the concurrency bound.
            while self.next < self.ids.len() && self.slots.len() < MAX_IN_FLIGHT {
                let id = self.ids[self.next];
                self.next += 1;
                let fetcher = self.fetcher.clone();
                let work: FetchFuture = Box::pin(async move { fetcher.fetch(id).await });
                self.slots.push(Slot {
                    id,
                    work: Some(work),
                });
            }

            // Poll each live fetch once so that every one of them has stored a
            // waker before this step may return `Pending`.
            for index in 0..self.slots.len() {
                let id = self.slots[index].id;
                let polled = match self.slots[index].work.as_mut() {
                    Some(work) => work.as_mut().poll(cx),
                    None => continue,
                };
                match polled {
                    Poll::Pending => {}
                    Poll::Ready(Ok(value)) => {
                        self.slots[index].work = None;
                        self.sum = self.sum.wrapping_add(value);
                    }
                    Poll::Ready(Err(_)) => {
                        self.slots.clear();
                        return Poll::Ready(Err(SolveError::Fetch { id }));
                    }
                }
            }

            if self.next >= self.ids.len() && self.slots.is_empty() {
                return Poll::Ready(Ok(self.sum));
            }
            if !self.slots.is_empty() {
                return Poll::Pending;
            }
            // The pool drained with ids still to come: fill it again.
        }
    }
}

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use lgwks_bot::script::{each, within, FlowError, Scope, Tenant};

/// The maximum number of `fetch` calls allowed to be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let scope = Scope::root(Tenant::new("aggregate").map_err(|_| SolveError::Cancelled)?);
    let limit = NonZeroUsize::new(MAX_IN_FLIGHT).ok_or(SolveError::Cancelled)?;

    // The first failing id, recorded by whichever body observes it first.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    // `within` owns the whole fan-out: on the deadline or on cancellation it
    // drops `body`, which drops the `each` future, which drops every fetch
    // still in flight. Nothing outlives the call.
    //
    // The body is a non-`move` block: it borrows `scope` for the same shared
    // borrow that `within(&scope, ..)` takes, and it borrows the locals that
    // outlive it instead of moving them.
    let outcome = within(&scope, "solve", deadline, async {
        // `each` is bounded and ordered, and fail-fast: the first error cancels
        // the fan-out, drops running bodies and starts no further item.
        let values = each(&scope, "fetch", Some(limit), ids.iter().copied(), |_step, id| {
            let fetch = &fetch;
            let failed = &failed;
            async move {
                match fetch.fetch(id).await {
                    Ok(value) => Ok(value),
                    Err(_) => {
                        {
                            let mut slot = failed.lock().unwrap_or_else(|e| e.into_inner());
                            if slot.is_none() {
                                *slot = Some(id);
                            }
                        }
                        Err(FlowError::failed("fetch"))
                    }
                }
            }
        })
        .await?;

        Ok::<u64, FlowError>(values.into_iter().sum())
    })
    .await;

    let observed = *failed.lock().unwrap_or_else(|e| e.into_inner());

    match outcome {
        Ok(sum) => match observed {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Ok(sum),
        },
        Err(err) => match observed {
            Some(id) => Err(SolveError::Fetch { id }),
            None if err.is_cancelled() || scope.is_cancelled() => Err(SolveError::Cancelled),
            None => Err(SolveError::Deadline),
        },
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

/// How many `fetch` calls may be in flight at the same time.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type Fetched = Result<u64, ai_task_support::FetchError>;

/// Every `fetch` this call owns lives inside the future that is polled, so
/// dropping `solve` drops all of them at once: nothing is still running once the
/// caller walks away. The only thread is the deadline watcher, and it is woken
/// and joined in `Drop`, so it cannot outlive the call either.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solver::new(ids, fetch, deadline).await
}

struct InFlight {
    id: u32,
    fut: Pin<Box<dyn Future<Output = Fetched> + Send>>,
}

struct Solver {
    // Boxed so the whole solver stays `Unpin` and can be polled through a
    // `Pin<&mut _>` without any unsafe.
    fetch: Box<ai_task_support::Fetcher>,
    ids: Vec<u32>,
    next: usize,
    running: Vec<InFlight>,
    sum: u64,
    failed: Option<u32>,
    deadline_at: Option<Instant>,
    signal: Arc<Signal>,
    gate: Option<Arc<Gate>>,
    timer: Option<JoinHandle<()>>,
}

impl Solver {
    fn new(ids: Vec<u32>, fetch: ai_task_support::Fetcher, deadline: Duration) -> Solver {
        let deadline_at = Instant::now().checked_add(deadline);
        let mut solver = Solver {
            fetch: Box::new(fetch),
            ids,
            next: 0,
            running: Vec::new(),
            sum: 0,
            failed: None,
            deadline_at,
            signal: Arc::new(Signal {
                waker: Mutex::new(None),
            }),
            gate: None,
            timer: None,
        };
        if !solver.ids.is_empty() {
            solver.arm_timer();
        }
        solver
    }

    /// One watcher thread exists only to wake the task at the deadline, and it is
    /// joined in `Drop`, so it cannot outlive the call either.
    fn arm_timer(&mut self) {
        let at = match self.deadline_at {
            Some(at) => at,
            None => return,
        };
        let signal = Arc::clone(&self.signal);
        let gate = Arc::new(Gate {
            flag: Mutex::new(false),
            cv: Condvar::new(),
        });
        let owned = Arc::clone(&gate);
        self.timer = Some(thread::spawn(move || {
            let mut flag = owned.flag.lock().unwrap_or_else(|e| e.into_inner());
            loop {
                let now = Instant::now();
                if now >= at {
                    break;
                }
                let (guard, _wait) = owned
                    .cv
                    .wait_timeout(flag, at - now)
                    .unwrap_or_else(|e| e.into_inner());
                flag = guard;
                if *flag {
                    return;
                }
            }
            drop(flag);
            signal.fire();
        }));
        self.gate = Some(gate);
    }

    fn expired(&self) -> bool {
        match self.deadline_at {
            Some(at) => Instant::now() >= at,
            None => false,
        }
    }
}

impl Future for Solver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.ids.is_empty() {
            return Poll::Ready(Ok(0));
        }
        if let Some(id) = this.failed {
            return Poll::Ready(Err(SolveError::Fetch { id }));
        }
        if this.expired() {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        // Fill the window. A failure can only ever be *seen* by polling, and
        // once one is seen this poll returns without starting anything else, so
        // no fetch is ever launched after a failure has been observed.
        while this.running.len() < MAX_IN_FLIGHT && this.next < this.ids.len() {
            if this.expired() {
                return Poll::Ready(Err(SolveError::Deadline));
            }
            let id = this.ids[this.next];
            this.next += 1;
            // The fetcher is moved into the fetch itself, so the in-flight
            // future borrows nothing from `solve`'s own state and is `'static`.
            let fetcher = (*this.fetch).clone();
            let fut = async move { fetcher.fetch(id).await };
            this.running.push(InFlight {
                id,
                fut: Box::pin(fut),
            });
        }

        this.signal.register(cx.waker());

        let mut index = 0;
        while index < this.running.len() {
            let polled = {
                let slot = &mut this.running[index];
                slot.fut.as_mut().poll(cx)
            };
            match polled {
                Poll::Ready(Ok(value)) => {
                    let slot = this.running.swap_remove(index);
                    this.sum = this.sum.wrapping_add(value);
                }
                Poll::Ready(Err(_)) => {
                    let slot = this.running.swap_remove(index);
                    this.failed = Some(slot.id);
                    // Every still-running fetch is dropped with this future.
                    return Poll::Ready(Err(SolveError::Fetch { id: slot.id }));
                }
                Poll::Pending => index += 1,
            }
        }

        if let Some(id) = this.failed {
            return Poll::Ready(Err(SolveError::Fetch { id }));
        }
        if this.expired() {
            return Poll::Ready(Err(SolveError::Deadline));
        }
        if this.running.is_empty() && this.next >= this.ids.len() {
            return Poll::Ready(Ok(this.sum));
        }
        Poll::Pending
    }
}

impl Drop for Solver {
    fn drop(&mut self) {
        if let Some(gate) = self.gate.take() {
            {
                let mut flag = gate.flag.lock().unwrap_or_else(|e| e.into_inner());
                *flag = true;
            }
            gate.cv.notify_all();
        }
        if let Some(timer) = self.timer.take() {
            let _joined = timer.join();
        }
    }
}

struct Signal {
    waker: Mutex<Option<Waker>>,
}

impl Signal {
    /// Arm the current waker; it is never cleared, so a wake can never be lost
    /// across a poll boundary.
    fn register(&self, waker: &Waker) {
        let mut held = self.waker.lock().unwrap_or_else(|e| e.into_inner());
        *held = Some(waker.clone());
    }

    fn fire(&self) {
        let waker = {
            let held = self.waker.lock().unwrap_or_else(|e| e.into_inner());
            held.clone()
        };
        if let Some(waker) = waker {
            waker.wake();
        }
    }
}

struct Gate {
    flag: Mutex<bool>,
    cv: Condvar,
}

//! Bounded, deadline-aware, fail-fast fan-out over `ai_task_support::Fetcher`.
//!
//! The driver is a hand-written future: every in-flight `fetch` lives in a
//! boxed future that *owns* its own clone of the `Fetcher` (see [`one`]), so the
//! driver never has to borrow itself. Dropping the driver therefore drops every
//! fetch it started, with no background thread left holding work.

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{FetchError, Fetcher};

/// Never more than this many `fetch` calls in flight at once.
const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// One fetch, self-contained: the returned future owns its clone of the fetcher
/// and so borrows nothing. Every call of this function has the same opaque
/// type, which is what lets the driver keep a homogeneous list of them.
fn one(fetch: Fetcher, id: u32) -> impl Future<Output = Result<u64, FetchError>> {
    async move { fetch.fetch(id).await }
}

struct Slot {
    id: u32,
    fut: Pin<Box<dyn Future<Output = Result<u64, FetchError>>>>,
}

/// Sleeps out the remaining deadline on a helper thread and wakes the task if it
/// expires. A helper thread is needed because a `fetch` future may sit pending
/// forever without ever waking anybody; polling alone would never notice the
/// deadline. Dropping the watch tells the thread to go away immediately.
struct DeadlineWatch {
    fired: Arc<AtomicBool>,
    stop: Arc<(Mutex<bool>, Condvar)>,
}

impl DeadlineWatch {
    fn start(remaining: Duration, waker: &Waker) -> Option<DeadlineWatch> {
        let fired = Arc::new(AtomicBool::new(false));
        let stop = Arc::new((Mutex::new(false), Condvar::new()));

        let thread_fired = Arc::clone(&fired);
        let thread_stop = Arc::clone(&stop);
        let thread_waker = waker.clone();

        std::thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || {
                let (lock, cv) = &*thread_stop;
                let guard = match lock.lock() {
                    Ok(guard) => guard,
                    Err(_) => return,
                };
                let (guard, _) = match cv.wait_timeout_while(guard, remaining, |done| !*done) {
                    Ok(waited) => waited,
                    Err(_) => return,
                };
                if *guard {
                    return;
                }
                drop(guard);
                thread_fired.store(true, Ordering::SeqCst);
                thread_waker.wake();
            })
            .ok()?;

        Some(DeadlineWatch { fired, stop })
    }

    fn fired(&self) -> bool {
        self.fired.load(Ordering::SeqCst)
    }
}

impl Drop for DeadlineWatch {
    fn drop(&mut self) {
        let (lock, cv) = &*self.stop;
        if let Ok(mut done) = lock.lock() {
            *done = true;
            cv.notify_all();
        }
    }
}

struct Driver {
    fetch: Fetcher,
    ids: std::vec::IntoIter<u32>,
    live: Vec<Slot>,
    sum: u64,
    deadline: Instant,
    watch: Option<DeadlineWatch>,
}

impl Driver {
    fn new(fetch: Fetcher, ids: Vec<u32>, deadline: Duration) -> Driver {
        Driver {
            fetch,
            ids: ids.into_iter(),
            live: Vec::new(),
            sum: 0,
            deadline: Instant::now() + deadline,
            watch: None,
        }
    }

    fn expired(&self) -> bool {
        match &self.watch {
            Some(watch) => watch.fired(),
            None => false,
        }
    }

    fn start_more(&mut self) {
        while self.live.len() < MAX_IN_FLIGHT {
            let id = match self.ids.next() {
                Some(id) => id,
                None => break,
            };
            self.live.push(Slot {
                id,
                fut: Box::pin(one(self.fetch.clone(), id)),
            });
        }
    }
}

impl Future for Driver {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<u64, SolveError>> {
        let me = self.get_mut();

        if me.watch.is_none() {
            let remaining = me.deadline.saturating_duration_since(Instant::now());
            me.watch = DeadlineWatch::start(remaining, cx.waker());
        }

        if me.expired() || Instant::now() >= me.deadline {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        loop {
            me.start_more();

            if me.live.is_empty() {
                return Poll::Ready(Ok(me.sum));
            }

            let mut ready: Option<(usize, Result<u64, FetchError>)> = None;
            for (index, slot) in me.live.iter_mut().enumerate() {
                if let Poll::Ready(outcome) = slot.fut.as_mut().poll(cx) {
                    ready = Some((index, outcome));
                    break;
                }
            }

            match ready {
                // Every fetch is still pending; the wakers they registered with
                // (and the deadline watch) will bring us back.
                None => return Poll::Pending,
                // Fail fast: resolving here drops the remaining in-flight
                // fetches, and no further id is ever started.
                Some((index, Err(_))) => {
                    let id = me.live[index].id;
                    return Poll::Ready(Err(SolveError::Fetch { id }));
                }
                Some((index, Ok(value))) => {
                    me.sum = me.sum.wrapping_add(value);
                    me.live.remove(index);
                }
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    Driver::new(fetch, ids, deadline).await
}

//! `fetch_a` and `fetch_b` race each other, `combine` waits for both, and
//! `publish` waits for `combine`.
//!
//! The runner owns every stage future it starts and polls them only from the
//! task that awaits `solve`, so a caller that drops the future mid-flight stops
//! exactly the stages it owns: nothing outlives the call.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

/// Why the pipeline stopped before publishing.
#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageResult = Result<Artifact, StageError>;

/// One in-flight stage future, owned by the runner and tied to the `Stage` it
/// borrows from. Created inside `poll`, so the borrow comes from the caller's
/// own frame rather than from a detached worker.
struct StageFuture<'s>(Pin<Box<dyn Future<Output = StageResult> + 's>>);

// SAFETY: a `StageFuture` is polled and dropped by the single task that created
// it and is never moved between threads; the marker only keeps `solve`'s future
// `Send` for callers that require it.
unsafe impl<'s> Send for StageFuture<'s> {}

struct TimerState {
    waker: Option<Waker>,
    elapsed: bool,
    stopped: bool,
}

/// The overall deadline: a timer thread that only ever *wakes* the pipeline,
/// so the stages themselves stay owned by the caller's task.
struct Deadline {
    state: Mutex<TimerState>,
    signal: Condvar,
}

impl Deadline {
    fn start(after: Duration) -> Arc<Self> {
        let deadline = Arc::new(Deadline {
            state: Mutex::new(TimerState {
                waker: None,
                elapsed: false,
                stopped: false,
            }),
            signal: Condvar::new(),
        });
        let worker = Arc::clone(&deadline);
        thread::spawn(move || worker.watch(after));
        deadline
    }

    fn watch(&self, after: Duration) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        loop {
            if state.stopped {
                return;
            }
            let (next, waited) = self
                .signal
                .wait_timeout(state, after)
                .unwrap_or_else(|e| e.into_inner());
            state = next;
            if state.stopped {
                return;
            }
            if waited.timed_out() {
                state.elapsed = true;
                let waker = state.waker.take();
                drop(state);
                if let Some(waker) = waker {
                    waker.wake();
                }
                return;
            }
        }
    }

    /// Publish the caller's waker so a deadline that fires later can wake it.
    fn arm(&self, waker: &Waker) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        state.waker = Some(waker.clone());
    }

    fn stop(&self) {
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        state.stopped = true;
        state.waker = None;
        self.signal.notify_all();
    }
}

enum Phase {
    Fetch,
    Combine,
    Publish,
    Done,
}

struct Runner<'s> {
    stage: &'s Stage,
    after: Duration,
    start: Instant,
    timer: Arc<Deadline>,
    phase: Phase,
    fetch_a: Option<StageFuture<'s>>,
    fetch_b: Option<StageFuture<'s>>,
    tail: Option<StageFuture<'s>>,
    a_done: bool,
    b_done: bool,
}

/// Poll one owned slot: `Ok(Some(_))` finished, `Ok(None)` still pending,
/// `Err(name)` failed.
fn poll_slot<'s>(
    stage: &'s Stage,
    cx: &mut Context<'_>,
    slot: &mut Option<StageFuture<'s>>,
    name: StageName,
) -> Result<Option<Artifact>, StageName> {
    if slot.is_none() {
        *slot = Some(StageFuture(Box::pin(stage.run(name))));
    }
    let mut future = match slot.take() {
        Some(future) => future,
        None => unreachable!("slot is filled just above"),
    };
    match future.0.as_mut().poll(cx) {
        Poll::Ready(Ok(artifact)) => Ok(Some(artifact)),
        Poll::Ready(Err(_)) => Err(name),
        Poll::Pending => {
            *slot = Some(future);
            Ok(None)
        }
    }
}

impl<'s> Runner<'s> {
    fn new(stage: &'s Stage, after: Duration) -> Self {
        Runner {
            stage,
            after,
            start: Instant::now(),
            timer: Deadline::start(after),
            phase: Phase::Fetch,
            fetch_a: None,
            fetch_b: None,
            tail: None,
            a_done: false,
            b_done: false,
        }
    }

    fn expired(&self) -> bool {
        if self.start.elapsed() >= self.after {
            return true;
        }
        self.timer
            .state
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .elapsed
    }

    /// Drop every stage still owned here, then answer the caller.
    fn finish(
        &mut self,
        outcome: Result<Published, PipelineError>,
    ) -> Poll<Result<Published, PipelineError>> {
        self.fetch_a = None;
        self.fetch_b = None;
        self.tail = None;
        self.phase = Phase::Done;
        self.timer.stop();
        Poll::Ready(outcome)
    }

    fn fail(&mut self, name: StageName) -> Poll<Result<Published, PipelineError>> {
        self.finish(Err(PipelineError::Stage { name }))
    }
}

impl<'s> Future for Runner<'s> {
    type Output = Result<Published, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if matches!(this.phase, Phase::Done) {
            return Poll::Ready(Err(PipelineError::Cancelled));
        }

        // Arm the timer first: a deadline that fires from here on always finds
        // a waker, and one that fired before this poll is already `elapsed`.
        this.timer.arm(cx.waker());

        loop {
            if this.expired() {
                return this.finish(Err(PipelineError::Deadline));
            }

            match this.phase {
                Phase::Fetch => {
                    if !this.a_done {
                        match poll_slot(
                            this.stage,
                            cx,
                            &mut this.fetch_a,
                            StageName::FetchA,
                        ) {
                            Ok(Some(_)) => this.a_done = true,
                            Ok(None) => {}
                            Err(name) => return this.fail(name),
                        }
                    }
                    if !this.b_done {
                        match poll_slot(
                            this.stage,
                            cx,
                            &mut this.fetch_b,
                            StageName::FetchB,
                        ) {
                            Ok(Some(_)) => this.b_done = true,
                            Ok(None) => {}
                            Err(name) => return this.fail(name),
                        }
                    }
                    if this.a_done && this.b_done {
                        this.phase = Phase::Combine;
                        continue;
                    }
                    return Poll::Pending;
                }
                Phase::Combine => {
                    match poll_slot(this.stage, cx, &mut this.tail, StageName::Combine) {
                        Ok(Some(_)) => {
                            this.phase = Phase::Publish;
                            continue;
                        }
                        Ok(None) => return Poll::Pending,
                        Err(name) => return this.fail(name),
                    }
                }
                Phase::Publish => {
                    match poll_slot(this.stage, cx, &mut this.tail, StageName::Publish) {
                        Ok(Some(artifact)) => {
                            return this.finish(Ok(Published::from(artifact)))
                        }
                        Ok(None) => return Poll::Pending,
                        Err(name) => return this.fail(name),
                    }
                }
                Phase::Done => return Poll::Ready(Err(PipelineError::Cancelled)),
            }
        }
    }
}

impl<'s> Drop for Runner<'s> {
    fn drop(&mut self) {
        self.timer.stop();
    }
}

/// Run the pipeline: fetch both sides concurrently, combine, publish.
pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: std::time::Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let mut runner = Runner::new(&stage, deadline);
    poll_fn(move |cx| Pin::new(&mut runner).poll(cx)).await
}

//! Bounded, owning pipeline over `ai_task_support::Stage`.
//!
//! The pipeline owns every future it starts: nothing runs on a detached task,
//! and dropping the future returned by [`solve`] drops the stage futures that
//! are still in flight (and shuts their deadline timers down) before it
//! returns. Every fallible call is handled explicitly; no stage is started
//! until the stage it depends on has succeeded.

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// What a stage hands back once it has run to completion.
type StageResult = Result<Artifact, StageError>;

/// Marker for "the deadline passed before the body finished".
struct Elapsed;

/// Lock the shared timer state, tolerating a poisoned mutex: the state is a
/// plain `Option<Waker>`/`bool` pair, so a poison cannot make it inconsistent.
fn lock(state: &Mutex<TimerState>) -> MutexGuard<'_, TimerState> {
    match state.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

// ---------------------------------------------------------------------------
// The two independent fetches
// ---------------------------------------------------------------------------

/// Drives `fetch_a` and `fetch_b` from a single poll.
///
/// Both are live at once and neither outlives this value: the first failure
/// drops the sibling fetch before the error is reported, and dropping `Join`
/// drops whatever is still in flight.
struct Join<A, B> {
    a: Option<Pin<Box<A>>>,
    b: Option<Pin<Box<B>>>,
    a_out: Option<Artifact>,
    b_out: Option<Artifact>,
    failed: Option<StageName>,
}

fn join<A, B>(a: A, b: B) -> Join<A, B>
where
    A: Future<Output = StageResult>,
    B: Future<Output = StageResult>,
{
    Join {
        a: Some(Box::pin(a)),
        b: Some(Box::pin(b)),
        a_out: None,
        b_out: None,
        failed: None,
    }
}

impl<A, B> Future for Join<A, B>
where
    A: Future<Output = StageResult>,
    B: Future<Output = StageResult>,
{
    type Output = Result<(Artifact, Artifact), StageName>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // `Join` holds only `Pin<Box<_>>`, so it is `Unpin` whatever A and B are.
        let this = self.get_mut();

        if let Some(fut) = this.a.as_mut() {
            match fut.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => {
                    this.a = None;
                    this.a_out = Some(artifact);
                }
                Poll::Ready(Err(_)) => {
                    this.a = None;
                    // Stop the sibling now: nothing may still be running once
                    // we have reported the failure.
                    this.b = None;
                    this.failed = Some(StageName::FetchA);
                }
                Poll::Pending => {}
            }
        }

        if let Some(fut) = this.b.as_mut() {
            match fut.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => {
                    this.b = None;
                    this.b_out = Some(artifact);
                }
                Poll::Ready(Err(_)) => {
                    this.b = None;
                    this.a = None;
                    this.failed = Some(StageName::FetchB);
                }
                Poll::Pending => {}
            }
        }

        if let Some(name) = this.failed {
            return Poll::Ready(Err(name));
        }

        if this.a.is_none() && this.b.is_none() {
            if let (Some(a), Some(b)) = (this.a_out.take(), this.b_out.take()) {
                return Poll::Ready(Ok((a, b)));
            }
        }

        Poll::Pending
    }
}

// ---------------------------------------------------------------------------
// Deadline timer
// ---------------------------------------------------------------------------

struct TimerState {
    waker: Option<Waker>,
    stopped: bool,
}

struct TimerShared {
    state: Mutex<TimerState>,
    signal: Condvar,
}

/// A one-shot deadline. A dedicated thread sleeps until the instant and wakes
/// the caller's waker; it is always stopped and joined before the `Timer`
/// itself is gone, so no thread outlives the future that armed it.
struct Timer {
    shared: Arc<TimerShared>,
    worker: Option<JoinHandle<()>>,
}

impl Timer {
    /// Start the timer, or `None` if the helper thread could not be spawned.
    fn start(at: Instant) -> Option<Timer> {
        let shared = Arc::new(TimerShared {
            state: Mutex::new(TimerState {
                waker: None,
                stopped: false,
            }),
            signal: Condvar::new(),
        });
        let worker_shared = Arc::clone(&shared);
        let worker = thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || run_timer(worker_shared, at))
            .ok()?;
        Some(Timer {
            shared,
            worker: Some(worker),
        })
    }

    /// Record the waker that must be woken when the deadline arrives.
    fn arm(&self, waker: &Waker) {
        let mut state = lock(&self.shared.state);
        state.waker = Some(waker.clone());
    }

    /// Fire the stop flag, drop the waker, wake the worker and join it.
    fn stop(&mut self) {
        {
            let mut state = lock(&self.shared.state);
            state.stopped = true;
            state.waker = None;
        }
        self.shared.signal.notify_all();
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

impl Drop for Timer {
    fn drop(&mut self) {
        self.stop();
    }
}

fn run_timer(shared: Arc<TimerShared>, at: Instant) {
    let mut state = lock(&shared.state);
    loop {
        if state.stopped {
            return;
        }
        let now = Instant::now();
        if now >= at {
            if let Some(waker) = state.waker.take() {
                drop(state);
                waker.wake();
            }
            return;
        }
        state = match shared.signal.wait_timeout(state, at - now) {
            Ok((guard, _)) => guard,
            Err(poisoned) => poisoned.into_inner().0,
        };
    }
}

// ---------------------------------------------------------------------------
// Racing a body against the deadline
// ---------------------------------------------------------------------------

/// Races `inner` against an absolute instant.
///
/// `Ok(output)` means the body finished in time; `Err(Elapsed)` means the
/// deadline arrived first, in which case the body is dropped here rather than
/// being left running.
struct Within<F> {
    inner: Pin<Box<F>>,
    at: Instant,
    timer: Option<Timer>,
    settled: bool,
}

fn within<F: Future>(inner: F, at: Instant) -> Within<F> {
    Within {
        inner: Box::pin(inner),
        at,
        timer: None,
        settled: false,
    }
}

impl<F: Future> Future for Within<F> {
    type Output = Result<F::Output, Elapsed>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        if this.settled {
            // A future must not be polled after it has resolved.
            return Poll::Ready(Err(Elapsed));
        }

        if Instant::now() >= this.at {
            this.settled = true;
            return Poll::Ready(Err(Elapsed));
        }

        match this.timer.as_ref() {
            Some(timer) => timer.arm(cx.waker()),
            None => match Timer::start(this.at) {
                Some(timer) => {
                    timer.arm(cx.waker());
                    this.timer = Some(timer);
                }
                None => {
                    // Without the timer we cannot wake up again, so we refuse
                    // to wait at all rather than run past the deadline.
                    this.settled = true;
                    return Poll::Ready(Err(Elapsed));
                }
            },
        }

        match this.inner.as_mut().poll(cx) {
            Poll::Ready(output) => {
                this.settled = true;
                Poll::Ready(Ok(output))
            }
            Poll::Pending => Poll::Pending,
        }
    }
}

// ---------------------------------------------------------------------------
// The pipeline
// ---------------------------------------------------------------------------

/// Run `fetch_a` and `fetch_b` concurrently, then `combine`, then `publish`.
///
/// - a failed fetch is reported by name and stops the sibling fetch, so
///   neither `combine` nor `publish` is ever started;
/// - the overall deadline is absolute and spans the whole pipeline: a stage
///   that runs past it is dropped and reported as [`PipelineError::Deadline`],
///   and no later stage is started;
/// - dropping this future drops whatever stage is in flight and stops its
///   timer thread before the drop returns.
pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let at = match Instant::now().checked_add(deadline) {
        Some(at) => at,
        // A deadline no clock can express is a deadline we cannot honour.
        None => return Err(PipelineError::Deadline),
    };

    // fetch_a and fetch_b are independent: run them together.
    match within(
        join(stage.run(StageName::FetchA), stage.run(StageName::FetchB)),
        at,
    )
    .await
    {
        Ok(Ok((_a, _b))) => {}
        Ok(Err(name)) => return Err(PipelineError::Stage { name }),
        Err(Elapsed) => return Err(PipelineError::Deadline),
    }

    // combine may only run once both fetches succeeded.
    match within(stage.run(StageName::Combine), at).await {
        Ok(Ok(_artifact)) => {}
        Ok(Err(_)) => {
            return Err(PipelineError::Stage {
                name: StageName::Combine,
            })
        }
        Err(Elapsed) => return Err(PipelineError::Deadline),
    }

    // publish may only run once combine succeeded.
    match within(stage.run(StageName::Publish), at).await {
        Ok(Ok(artifact)) => Ok(Published::from(artifact)),
        Ok(Err(_)) => Err(PipelineError::Stage {
            name: StageName::Publish,
        }),
        Err(Elapsed) => Err(PipelineError::Deadline),
    }
}

//! A four-stage pipeline over a harness-provided `Stage`.
//!
//! `fetch_a` and `fetch_b` are polled as concurrent, independently owned
//! futures; `combine` starts only after both have succeeded; `publish` starts
//! only after `combine` has succeeded. The whole pipeline is driven by a single
//! future that owns every in-flight stage future, so dropping the future that
//! `solve` returned drops them all synchronously — no stage outlives the call.
//!
//! The deadline is enforced twice over: an `Instant` check refuses to *start*
//! a stage after the deadline, and a one-shot timer thread (joined on drop)
//! wakes the driver so a stage that is still running at the deadline is
//! abandoned promptly rather than waited out.

use std::future::Future;
use std::pin::Pin;
use std::sync::mpsc;
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};

/// The longest wait the driver will actually arm a timer for. Callers may hand
/// us a duration too large for `Instant` arithmetic; clamping keeps a
/// "practically infinite" deadline meaning exactly that.
const MAX_WAIT: Duration = Duration::from_secs(100 * 365 * 24 * 60 * 60);

/// Everything that can go wrong in the pipeline.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error; `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline elapsed, so no further stage was started.
    Deadline,
    /// The pipeline was abandoned.
    Cancelled,
}

impl PartialEq for PipelineError {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (PipelineError::Stage { .. }, PipelineError::Stage { .. }) => true,
            (PipelineError::Deadline, PipelineError::Deadline) => true,
            (PipelineError::Cancelled, PipelineError::Cancelled) => true,
            _ => false,
        }
    }
}

impl Eq for PipelineError {}

/// Run the four-stage pipeline under `deadline`.
pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    Pipeline::start(stage, deadline).await
}

// ---------------------------------------------------------------------------
// one-shot "wake me" signal
// ---------------------------------------------------------------------------

struct Signal {
    state: Mutex<SignalState>,
}

struct SignalState {
    fired: bool,
    waker: Option<Waker>,
}

impl Signal {
    fn new() -> Arc<Signal> {
        Arc::new(Signal {
            state: Mutex::new(SignalState { fired: false, waker: None }),
        })
    }

    fn lock(&self) -> MutexGuard<'_, SignalState> {
        self.state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    /// Fire the signal. The waker is taken out from under the lock so that
    /// waking can never re-enter this future while we hold it.
    fn fire(&self) {
        let waker = {
            let mut state = self.lock();
            state.fired = true;
            state.waker.take()
        };
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    /// Returns `true` if already fired, otherwise parks `cx`'s waker.
    fn subscribe(&self, cx: &Context<'_>) -> bool {
        let mut state = self.lock();
        if state.fired {
            return true;
        }
        state.waker = Some(cx.waker().clone());
        false
    }
}

/// The timer thread plus the handle that stops it. Dropping this always stops
/// the thread and joins it, so no helper thread outlives the pipeline.
struct DeadlineTimer {
    stop: Option<mpsc::Sender<()>>,
    handle: Option<JoinHandle<()>>,
}

impl DeadlineTimer {
    fn arm(signal: &Arc<Signal>, limit: Duration) -> Self {
        let (stop, recv) = mpsc::channel::<()>();
        let armed = Arc::clone(signal);
        let handle = thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn(move || {
                // `Ok` means we were stopped before the deadline; `Err` (timeout
                // or disconnect) means the wait is over and the driver must be
                // told to abandon whatever it is running.
                if recv.recv_timeout(limit).is_err() {
                    armed.fire();
                }
            })
            .ok();
        DeadlineTimer {
            stop: Some(stop),
            handle,
        }
    }

    /// Stop the timer early and wait for its thread to finish. Idempotent.
    fn disarm(&mut self) {
        if let Some(stop) = self.stop.take() {
            let _ = stop.send(());
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

impl Drop for DeadlineTimer {
    fn drop(&mut self) {
        self.disarm();
    }
}

// ---------------------------------------------------------------------------
// stage driving
// ---------------------------------------------------------------------------

type StageOutcome = Result<Artifact, StageError>;
type StageFuture = Pin<Box<dyn Future<Output = StageOutcome> + Send>>;

enum Drive<T> {
    /// The stage finished.
    Done(T),
    /// The stage is abandoned: the deadline elapsed while it was in flight.
    Expired,
}

/// Start one stage. The `Stage` is cloned into the future so the future can be
/// `'static` and independently owned by the driver.
fn launch(stage: Stage, name: StageName) -> StageFuture {
    Box::pin(async move { stage.run(name).await })
}

/// Poll `fut` once. If it is still pending, park the waker on both the stage
/// and the deadline signal, so we are woken either by the stage making progress
/// or by the deadline expiring.
fn drive(
    fut: &mut StageFuture,
    signal: &Signal,
    at: Instant,
    cx: &mut Context<'_>,
) -> Poll<Drive<StageOutcome>> {
    if let Poll::Ready(outcome) = fut.as_mut().poll(cx) {
        return Poll::Ready(Drive::Done(outcome));
    }
    if Instant::now() >= at || signal.subscribe(cx) {
        return Poll::Ready(Drive::Expired);
    }
    Poll::Pending
}

// ---------------------------------------------------------------------------
// the pipeline driver
// ---------------------------------------------------------------------------

#[derive(PartialEq, Eq, Clone, Copy)]
enum Phase {
    Fetch,
    Combine,
    Publish,
    Finished,
}

struct Pipeline {
    stage: Option<Stage>,
    at: Instant,
    signal: Arc<Signal>,
    timer: DeadlineTimer,

    phase: Phase,
    fetch_a: Option<StageFuture>,
    fetch_b: Option<StageFuture>,
    value_a: Option<Artifact>,
    value_b: Option<Artifact>,
    combine: Option<StageFuture>,
    publish: Option<StageFuture>,
}

impl Pipeline {
    fn start(stage: Stage, deadline: Duration) -> Self {
        let limit = deadline.min(MAX_WAIT);
        let now = Instant::now();
        let at = now.checked_add(limit).unwrap_or_else(|| now + MAX_WAIT);
        let signal = Signal::new();
        let timer = DeadlineTimer::arm(&signal, limit);
        Pipeline {
            stage: Some(stage),
            at,
            signal,
            timer,
            phase: Phase::Fetch,
            fetch_a: None,
            fetch_b: None,
            value_a: None,
            value_b: None,
            combine: None,
            publish: None,
        }
    }

    fn deadline_passed(&self) -> bool {
        Instant::now() >= self.at
    }

    /// Drop every stage future and every artifact we own, and stop the timer.
    /// Nothing that this pipeline started survives this call.
    fn stop_all(&mut self) {
        self.fetch_a = None;
        self.fetch_b = None;
        self.combine = None;
        self.publish = None;
        self.value_a = None;
        self.value_b = None;
        self.stage = None;
        self.timer.disarm();
    }

    fn fail(&mut self, name: StageName) -> Poll<Result<Published, PipelineError>> {
        self.stop_all();
        self.phase = Phase::Finished;
        Poll::Ready(Err(PipelineError::Stage { name }))
    }

    fn expire(&mut self) -> Poll<Result<Published, PipelineError>> {
        self.stop_all();
        self.phase = Phase::Finished;
        Poll::Ready(Err(PipelineError::Deadline))
    }

    fn clone_stage(&self) -> Stage {
        self.stage
            .as_ref()
            .expect("stage dropped before pipeline finished")
            .clone()
    }
}

impl Future for Pipeline {
    type Output = Result<Published, PipelineError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        loop {
            match this.phase {
                Phase::Finished => return Poll::Ready(Err(PipelineError::Cancelled)),

                Phase::Fetch => {
                    if this.fetch_a.is_none() && this.fetch_b.is_none() {
                        if this.deadline_passed() {
                            return this.expire();
                        }
                        let stage = this.clone_stage();
                        this.fetch_a = Some(launch(stage.clone(), StageName::FetchA));
                        this.fetch_b = Some(launch(stage, StageName::FetchB));
                    }

                    if this.fetch_a.is_some() {
                        let polled = drive(
                            this.fetch_a.as_mut().expect("fetch_a present"),
                            &this.signal,
                            this.at,
                            cx,
                        );
                        match polled {
                            Poll::Ready(Drive::Done(Ok(value))) => {
                                this.fetch_a = None;
                                this.value_a = Some(value);
                            }
                            Poll::Ready(Drive::Done(Err(_error))) => {
                                return this.fail(StageName::FetchA);
                            }
                            Poll::Ready(Drive::Expired) => return this.expire(),
                            Poll::Pending => {}
                        }
                    }

                    if this.fetch_b.is_some() {
                        let polled = drive(
                            this.fetch_b.as_mut().expect("fetch_b present"),
                            &this.signal,
                            this.at,
                            cx,
                        );
                        match polled {
                            Poll::Ready(Drive::Done(Ok(value))) => {
                                this.fetch_b = None;
                                this.value_b = Some(value);
                            }
                            Poll::Ready(Drive::Done(Err(_error))) => {
                                return this.fail(StageName::FetchB);
                            }
                            Poll::Ready(Drive::Expired) => return this.expire(),
                            Poll::Pending => {}
                        }
                    }

                    if this.value_a.is_some() && this.value_b.is_some() {
                        this.phase = Phase::Combine;
                        continue;
                    }
                    return Poll::Pending;
                }

                Phase::Combine => {
                    if this.combine.is_none() {
                        if this.deadline_passed() {
                            return this.expire();
                        }
                        this.combine = Some(launch(this.clone_stage(), StageName::Combine));
                    }

                    let polled = drive(
                        this.combine.as_mut().expect("combine present"),
                        &this.signal,
                        this.at,
                        cx,
                    );
                    match polled {
                        Poll::Ready(Drive::Done(Ok(value))) => {
                            this.combine = None;
                            this.value_a = None;
                            this.value_b = None;
                            this.phase = Phase::Publish;
                            continue;
                        }
                        Poll::Ready(Drive::Done(Err(_error))) => {
                            return this.fail(StageName::Combine);
                        }
                        Poll::Ready(Drive::Expired) => return this.expire(),
                        Poll::Pending => return Poll::Pending,
                    }
                }

                Phase::Publish => {
                    if this.publish.is_none() {
                        if this.deadline_passed() {
                            return this.expire();
                        }
                        this.publish = Some(launch(this.clone_stage(), StageName::Publish));
                    }

                    let polled = drive(
                        this.publish.as_mut().expect("publish present"),
                        &this.signal,
                        this.at,
                        cx,
                    );
                    match polled {
                        Poll::Ready(Drive::Done(Ok(value))) => {
                            this.publish = None;
                            let published = Published::from(value);
                            this.phase = Phase::Finished;
                            this.stop_all();
                            return Poll::Ready(Ok(published));
                        }
                        Poll::Ready(Drive::Done(Err(_error))) => {
                            return this.fail(StageName::Publish);
                        }
                        Poll::Ready(Drive::Expired) => return this.expire(),
                        Poll::Pending => return Poll::Pending,
                    }
                }
            }
        }
    }
}

use std::future::{poll_fn, Future};
use std::pin::pin;
use std::task::Poll;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(
    stage: &Stage,
    name: StageName,
    started: Instant,
    deadline: Duration,
) -> Result<Artifact, PipelineError> {
    let fut = stage.run(name);
    let mut fut = pin!(fut);
    poll_fn(|cx| match fut.as_mut().poll(cx) {
        Poll::Ready(Ok(artifact)) => Poll::Ready(Ok(artifact)),
        Poll::Ready(Err(_)) => Poll::Ready(Err(PipelineError::Stage { name })),
        Poll::Pending => {
            if started.elapsed() >= deadline {
                Poll::Ready(Err(PipelineError::Deadline))
            } else {
                Poll::Pending
            }
        }
    })
    .await
}

async fn run_fetches(
    stage: &Stage,
    started: Instant,
    deadline: Duration,
) -> Result<(Artifact, Artifact), PipelineError> {
    let mut fa = pin!(stage.run(StageName::FetchA));
    let mut fb = pin!(stage.run(StageName::FetchB));
    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    poll_fn(|cx| {
        if a.is_none() {
            match fa.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => a = Some(v),
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage { name: StageName::FetchA }))
                }
                Poll::Pending => {}
            }
        }
        if b.is_none() {
            match fb.as_mut().poll(cx) {
                Poll::Ready(Ok(v)) => b = Some(v),
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage { name: StageName::FetchB }))
                }
                Poll::Pending => {}
            }
        }
        if a.is_some() && b.is_some() {
            Poll::Ready(Ok((a.take().unwrap(), b.take().unwrap())))
        } else if started.elapsed() >= deadline {
            Poll::Ready(Err(PipelineError::Deadline))
        } else {
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let started = Instant::now();
    let (_a, _b) = run_fetches(&stage, started, deadline).await?;
    let _c = run_stage(&stage, StageName::Combine, started, deadline).await?;
    let published = run_stage(&stage, StageName::Publish, started, deadline).await?;
    Ok(Published::from(published))
}

//! Bounded four-stage pipeline: `fetch_a` / `fetch_b` run concurrently,
//! then `combine`, then `publish`, all under one overall deadline.

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Run the whole pipeline under `deadline`.
///
/// Dropping the returned future drops everything it owns, so no stage outlives
/// the call.
pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    match within(pipeline(stage), deadline).await {
        Ok(result) => result,
        Err(()) => Err(PipelineError::Deadline),
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let (a, b) = join(stage.run(StageName::FetchA), stage.run(StageName::FetchB)).await;
    let _a = a.map_err(|_| PipelineError::Stage { name: StageName::FetchA })?;
    let _b = b.map_err(|_| PipelineError::Stage { name: StageName::FetchB })?;

    let combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    let _ = combined;
    Ok(Published::from(published))
}

/// Run both futures to completion, polling each in turn on the caller's task.
/// Owning: dropping the returned future drops both bodies.
async fn join<A, B>(a: A, b: B) -> (A::Output, B::Output)
where
    A: Future,
    B: Future,
{
    let mut a = Box::pin(a);
    let mut b = Box::pin(b);
    std::future::poll_fn(move |cx| {
        let pa = a.as_mut().poll(cx);
        let pb = b.as_mut().poll(cx);
        match (pa, pb) {
            (Poll::Ready(x), Poll::Ready(y)) => Poll::Ready((x, y)),
            _ => Poll::Pending,
        }
    })
    .await
}

/// Race `body` against `limit`. On expiry the body is dropped.
async fn within<F: Future>(body: F, limit: Duration) -> Result<F::Output, ()> {
    let mut body = Box::pin(body);
    let mut timer = Timer::new(limit);
    std::future::poll_fn(move |cx| {
        if let Poll::Ready(value) = body.as_mut().poll(cx) {
            return Poll::Ready(Ok(value));
        }
        match timer.poll_expired(cx) {
            Poll::Ready(()) => Poll::Ready(Err(())),
            Poll::Pending => Poll::Pending,
        }
    })
    .await
}

struct TimerState {
    fired: bool,
    waker: Option<Waker>,
}

/// A one-shot deadline backed by a sleeping thread that wakes the task.
struct Timer {
    state: Arc<Mutex<TimerState>>,
}

impl Timer {
    fn new(limit: Duration) -> Timer {
        let state = Arc::new(Mutex::new(TimerState {
            fired: false,
            waker: None,
        }));
        let shared = Arc::clone(&state);
        std::thread::spawn(move || {
            std::thread::sleep(limit);
            let waker = {
                let mut guard = match shared.lock() {
                    Ok(guard) => guard,
                    Err(poisoned) => poisoned.into_inner(),
                };
                guard.fired = true;
                guard.waker.take()
            };
            if let Some(waker) = waker {
                waker.wake();
            }
        });
        Timer { state }
    }

    fn poll_expired(&mut self, cx: &mut Context<'_>) -> Poll<()> {
        let mut guard = match self.state.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        if guard.fired {
            return Poll::Ready(());
        }
        let replace = match &guard.waker {
            Some(waker) => !waker.will_wake(cx.waker()),
            None => true,
        };
        if replace {
            guard.waker = Some(cx.waker().clone());
        }
        Poll::Pending
    }
}

// Keep the pin helper referenced so the import is meaningful for the boxed bodies.
#[allow(dead_code)]
fn _assert_pinned<T>(value: Pin<Box<T>>) -> Pin<Box<T>> {
    value
}

//! A small, dependency-free pipeline runner: `fetch_a` and `fetch_b` run
//! concurrently, `combine` and `publish` follow in order, all under one overall
//! deadline, and everything is owned by the returned future so that dropping it
//! stops the work it owns.

use std::future::Future;
use std::pin::Pin;
use std::sync::mpsc;
use std::sync::{Arc, Mutex, MutexGuard};
use std::task::{Context, Poll, Waker};
use std::thread::{self, JoinHandle};
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// A latch that the deadline thread fires once; the pipeline future observes it
/// through [`SignalFut`].
struct Signal {
    state: Mutex<SignalState>,
}

struct SignalState {
    fired: bool,
    waker: Option<Waker>,
}

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    match m.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

impl Signal {
    fn new() -> Arc<Signal> {
        Arc::new(Signal {
            state: Mutex::new(SignalState {
                fired: false,
                waker: None,
            }),
        })
    }

    fn fire(&self) {
        let waker = {
            let mut state = lock(&self.state);
            state.fired = true;
            state.waker.take()
        };
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn is_fired(&self) -> bool {
        lock(&self.state).fired
    }

    /// Park the caller's waker until the signal fires; wakes immediately if it
    /// already has.
    fn register(&self, waker: &Waker) {
        let fire_now = {
            let mut state = lock(&self.state);
            if state.fired {
                true
            } else {
                state.waker = Some(waker.clone());
                false
            }
        };
        if fire_now {
            waker.wake();
        }
    }
}

/// Resolves once the signal has fired.
struct SignalFut {
    signal: Arc<Signal>,
}

impl Future for SignalFut {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        self.signal.register(cx.waker());
        if self.signal.is_fired() {
            Poll::Ready(())
        } else {
            Poll::Pending
        }
    }
}

/// A one-shot timer thread. Dropping it cancels the timer and joins the thread,
/// so no thread outlives the future that owns it.
struct Timer {
    cancel: Option<mpsc::Sender<()>>,
    worker: Option<JoinHandle<()>>,
}

impl Drop for Timer {
    fn drop(&mut self) {
        if let Some(cancel) = self.cancel.take() {
            let _ = cancel.send(());
        }
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

fn start_timer(after: Duration, signal: Arc<Signal>) -> Timer {
    let (cancel, recv) = mpsc::channel::<()>();
    let worker = thread::Builder::new()
        .name("pipeline-deadline".to_string())
        .spawn(move || {
            if matches!(recv.recv_timeout(after), Err(mpsc::RecvTimeoutError::Timeout)) {
                signal.fire();
            }
        })
        .expect("spawn deadline timer thread");
    Timer {
        cancel: Some(cancel),
        worker: Some(worker),
    }
}

enum Either<A, B> {
    First(A),
    Second(B),
}

/// Polls `first`, then `second`, returning whichever finishes first. The loser
/// is dropped with the combinator.
struct Race<A: Future, B: Future> {
    first: Option<Pin<Box<A>>>,
    second: Option<Pin<Box<B>>>,
}

impl<A: Future, B: Future> Race<A, B> {
    fn new(first: A, second: B) -> Self {
        Race {
            first: Some(Box::pin(first)),
            second: Some(Box::pin(second)),
        }
    }
}

impl<A: Future, B: Future> Future for Race<A, B> {
    type Output = Either<A::Output, B::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if let Some(first) = this.first.as_mut() {
            if let Poll::Ready(value) = first.as_mut().poll(cx) {
                return Poll::Ready(Either::First(value));
            }
        }
        if let Some(second) = this.second.as_mut() {
            if let Poll::Ready(value) = second.as_mut().poll(cx) {
                return Poll::Ready(Either::Second(value));
            }
        }
        Poll::Pending
    }
}

/// Drops a stage error: the stage identity is tracked by the combinator.
fn ignore_error<E>(_error: E) {}

enum Both<A, B> {
    Values(A, B),
    FirstFailed,
    SecondFailed,
}

/// Runs both futures concurrently and yields both outputs, or the identity of
/// the first one that failed. Each input future must resolve to
/// `Result<V, ()>`.
struct Pair<A, B, VA, VB> {
    first: Option<Pin<Box<A>>>,
    second: Option<Pin<Box<B>>>,
    first_value: Option<VA>,
    second_value: Option<VB>,
}

impl<A, B, VA, VB> Pair<A, B, VA, VB>
where
    A: Future<Output = Result<VA, ()>>,
    B: Future<Output = Result<VB, ()>>,
{
    fn new(first: A, second: B) -> Self {
        Pair {
            first: Some(Box::pin(first)),
            second: Some(Box::pin(second)),
            first_value: None,
            second_value: None,
        }
    }
}

impl<A, B, VA, VB> Future for Pair<A, B, VA, VB>
where
    A: Future<Output = Result<VA, ()>>,
    B: Future<Output = Result<VB, ()>>,
{
    type Output = Both<VA, VB>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();

        let first_poll = match this.first.as_mut() {
            Some(first) => Some(first.as_mut().poll(cx)),
            None => None,
        };
        match first_poll {
            Some(Poll::Ready(Ok(value))) => {
                this.first = None;
                this.first_value = Some(value);
            }
            Some(Poll::Ready(Err(()))) => return Poll::Ready(Both::FirstFailed),
            _ => {}
        }

        let second_poll = match this.second.as_mut() {
            Some(second) => Some(second.as_mut().poll(cx)),
            None => None,
        };
        match second_poll {
            Some(Poll::Ready(Ok(value))) => {
                this.second = None;
                this.second_value = Some(value);
            }
            Some(Poll::Ready(Err(()))) => return Poll::Ready(Both::SecondFailed),
            _ => {}
        }

        match (this.first_value.take(), this.second_value.take()) {
            (Some(a), Some(b)) => Poll::Ready(Both::Values(a, b)),
            _ => Poll::Pending,
        }
    }
}

/// Runs one named stage under the overall deadline.
async fn run_stage(
    stage: &Stage,
    name: StageName,
    signal: Arc<Signal>,
) -> Result<Artifact, PipelineError> {
    let run = stage.run(name).map_err(ignore_error);
    match Race::new(SignalFut { signal }, run).await {
        Either::First(()) => Err(PipelineError::Deadline),
        Either::Second(Ok(artifact)) => Ok(artifact),
        Either::Second(Err(())) => Err(PipelineError::Stage { name }),
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let signal = Signal::new();
    let _timer = start_timer(deadline, signal.clone());

    let fetches = Race::new(
        SignalFut {
            signal: signal.clone(),
        },
        Pair::new(
            stage.run(StageName::FetchA).map_err(ignore_error),
            stage.run(StageName::FetchB).map_err(ignore_error),
        ),
    );

    let (_a, _b) = match fetches.await {
        Either::First(()) => return Err(PipelineError::Deadline),
        Either::Second(Both::Values(a, b)) => (a, b),
        Either::Second(Both::FirstFailed) => {
            return Err(PipelineError::Stage {
                name: StageName::FetchA,
            })
        }
        Either::Second(Both::SecondFailed) => {
            return Err(PipelineError::Stage {
                name: StageName::FetchB,
            })
        }
    };

    let _combined = run_stage(&stage, StageName::Combine, signal.clone()).await?;
    let published = run_stage(&stage, StageName::Publish, signal).await?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};
use std::time::{Duration, Instant};

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

struct Parker {
    thread: Thread,
    awake: AtomicBool,
}

impl Wake for Parker {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.awake.store(true, Ordering::SeqCst);
        self.thread.unpark();
    }
}

fn block_on<F: Future>(future: F) -> F::Output {
    let mut future = Box::pin(future);
    let parker = Arc::new(Parker {
        thread: thread::current(),
        awake: AtomicBool::new(false),
    });
    let waker = Waker::from(Arc::clone(&parker));
    let mut cx = Context::from_waker(&waker);
    loop {
        parker.awake.store(false, Ordering::SeqCst);
        if let Poll::Ready(value) = future.as_mut().poll(&mut cx) {
            return value;
        }
        while !parker.awake.swap(false, Ordering::SeqCst) {
            thread::park();
        }
    }
}

struct TimerState {
    fired: Mutex<bool>,
    signal: Condvar,
    waker: Mutex<Option<Waker>>,
}

struct Sleep {
    shared: Arc<TimerState>,
}

impl Sleep {
    fn new(duration: Duration) -> Self {
        let shared = Arc::new(TimerState {
            fired: Mutex::new(false),
            signal: Condvar::new(),
            waker: Mutex::new(None),
        });
        let worker = Arc::clone(&shared);
        thread::spawn(move || {
            let expires = Instant::now() + duration;
            let mut fired = worker.fired.lock().unwrap_or_else(|e| e.into_inner());
            loop {
                if *fired {
                    return;
                }
                let now = Instant::now();
                if now >= expires {
                    *fired = true;
                    drop(fired);
                    worker.signal.notify_all();
                    let waker = worker
                        .waker
                        .lock()
                        .unwrap_or_else(|e| e.into_inner())
                        .take();
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }
                let (guard, _) = worker
                    .signal
                    .wait_timeout(fired, expires - now)
                    .unwrap_or_else(|e| e.into_inner());
                fired = guard;
            }
        });
        Sleep { shared }
    }
}

impl Future for Sleep {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if *self.shared.fired.lock().unwrap_or_else(|e| e.into_inner()) {
            return Poll::Ready(());
        }
        let mut slot = self.shared.waker.lock().unwrap_or_else(|e| e.into_inner());
        match slot.as_ref() {
            Some(existing) if existing.will_wake(cx.waker()) => {}
            _ => *slot = Some(cx.waker().clone()),
        }
        if *self.shared.fired.lock().unwrap_or_else(|e| e.into_inner()) {
            slot.take();
            return Poll::Ready(());
        }
        Poll::Pending
    }
}

impl Drop for Sleep {
    fn drop(&mut self) {
        *self.shared.fired.lock().unwrap_or_else(|e| e.into_inner()) = true;
        self.shared.signal.notify_all();
    }
}

struct Join2Inner<A: Future, B: Future> {
    left: Pin<Box<A>>,
    right: Pin<Box<B>>,
    left_out: Option<A::Output>,
    right_out: Option<B::Output>,
}

struct Join2<A: Future, B: Future> {
    inner: Box<Join2Inner<A, B>>,
}

impl<A: Future, B: Future> Join2<A, B> {
    fn new(left: A, right: B) -> Self {
        Self {
            inner: Box::new(Join2Inner {
                left: Box::pin(left),
                right: Box::pin(right),
                left_out: None,
                right_out: None,
            }),
        }
    }
}

impl<A: Future, B: Future> Future for Join2<A, B> {
    type Output = (A::Output, B::Output);

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut().inner.as_mut();
        if this.left_out.is_none() {
            if let Poll::Ready(value) = this.left.as_mut().poll(cx) {
                this.left_out = Some(value);
            }
        }
        if this.right_out.is_none() {
            if let Poll::Ready(value) = this.right.as_mut().poll(cx) {
                this.right_out = Some(value);
            }
        }
        match (this.left_out.take(), this.right_out.take()) {
            (Some(left), Some(right)) => Poll::Ready((left, right)),
            (Some(left), None) => {
                this.left_out = Some(left);
                Poll::Pending
            }
            (None, Some(right)) => {
                this.right_out = Some(right);
                Poll::Pending
            }
            (None, None) => Poll::Pending,
        }
    }
}

enum Selected<A, B> {
    Left(A),
    Right(B),
}

struct Select2Inner<A: Future, B: Future> {
    left: Option<Pin<Box<A>>>,
    right: Option<Pin<Box<B>>>,
    left_out: Option<A::Output>,
}

struct Select2<A: Future, B: Future> {
    inner: Box<Select2Inner<A, B>>,
}

impl<A: Future, B: Future> Select2<A, B> {
    fn new(left: A, right: B) -> Self {
        Self {
            inner: Box::new(Select2Inner {
                left: Some(Box::pin(left)),
                right: Some(Box::pin(right)),
                left_out: None,
            }),
        }
    }
}

impl<A: Future, B: Future> Future for Select2<A, B> {
    type Output = Selected<A::Output, B::Output>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut().inner.as_mut();
        if this.left_out.is_none() {
            if let Some(left) = this.left.as_mut() {
                if let Poll::Ready(value) = left.as_mut().poll(cx) {
                    this.left_out = Some(value);
                }
            }
        }
        if let Some(value) = this.left_out.take() {
            this.left = None;
            this.right = None;
            return Poll::Ready(Selected::Left(value));
        }
        if let Some(right) = this.right.as_mut() {
            if let Poll::Ready(value) = right.as_mut().poll(cx) {
                this.left = None;
                this.right = None;
                return Poll::Ready(Selected::Right(value));
            }
        }
        Poll::Pending
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let (a, b) = Join2::new(
            stage.run(StageName::FetchA),
            stage.run(StageName::FetchB),
        )
        .await;
        a.map_err(|_| PipelineError::Stage {
            name: StageName::FetchA,
        })?;
        b.map_err(|_| PipelineError::Stage {
            name: StageName::FetchB,
        })?;
        stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;
        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;
        Ok::<Published, PipelineError>(Published::from(published))
    };
    let timer = async move {
        Sleep::new(deadline).await;
    };
    match block_on(Select2::new(work, timer)) {
        Selected::Left(result) => result,
        Selected::Right(()) => Err(PipelineError::Deadline),
    }
}

//! Bounded, deadline-aware, cancellation-safe pipeline over `ai_task_support`.
//!
//! `fetch_a` and `fetch_b` are driven concurrently inside a single hand-written
//! poll loop (no executor, no threads for the stages themselves, no detached
//! tasks), so every stage future is owned by `solve` itself: dropping the
//! returned future drops the stages that are still in flight, and nothing
//! outlives the call.
//!
//! The deadline is enforced twice over: cooperatively (checked before every poll
//! of every stage) and independently by a small watchdog thread that wakes the
//! task when the budget expires, so a stage that never wakes cannot pin us past
//! the deadline. The watchdog is stopped and joined when `solve` returns or is
//! dropped.

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

#[derive(Debug)]
pub enum PipelineError {
    Stage {
        name: ai_task_support::StageName,
    },
    Deadline,
    Cancelled,
}

/// Deadline bookkeeping: an instant check plus a watchdog that wakes us.
struct Gate {
    fired: Arc<AtomicBool>,
    waker: Arc<Mutex<Option<Waker>>>,
    at: Instant,
    stop: Arc<(Mutex<bool>, Condvar)>,
    worker: Option<JoinHandle<()>>,
}

const FAR_FUTURE: Duration = Duration::from_secs(86_400);

impl Gate {
    fn start(limit: Duration) -> Gate {
        let now = Instant::now();
        let at = now.checked_add(limit).unwrap_or(now + FAR_FUTURE);
        let fired = Arc::new(AtomicBool::new(false));
        let waker: Arc<Mutex<Option<Waker>>> = Arc::new(Mutex::new(None));
        let stop = Arc::new((Mutex::new(false), Condvar::new()));

        let worker = std::thread::Builder::new()
            .name("pipeline-deadline".to_string())
            .spawn({
                let fired = Arc::clone(&fired);
                let waker = Arc::clone(&waker);
                let stop = Arc::clone(&stop);
                let until = at;
                move || {
                    let (lock, cv) = &*stop;
                    let mut flag = lock.lock().unwrap_or_else(|e| e.into_inner());
                    let mut stopped = *flag;
                    while !stopped {
                        let now = Instant::now();
                        if now >= until {
                            break;
                        }
                        let (guard, _) = cv
                            .wait_timeout(flag, until - now)
                            .unwrap_or_else(|e| e.into_inner());
                        flag = guard;
                        stopped = *flag;
                    }
                    let hit = !stopped;
                    drop(flag);
                    if hit {
                        fired.store(true, Ordering::Release);
                        let slot = waker.lock().unwrap_or_else(|e| e.into_inner());
                        if let Some(w) = slot.as_ref() {
                            w.wake_by_ref();
                        }
                    }
                }
            })
            .ok();

        Gate {
            fired,
            waker,
            at,
            stop,
            worker,
        }
    }

    fn expired(&self) -> bool {
        self.fired.load(Ordering::Acquire) || Instant::now() >= self.at
    }

    fn arm(&self, cx: &Context<'_>) {
        let mut slot = self.waker.lock().unwrap_or_else(|e| e.into_inner());
        *slot = Some(cx.waker().clone());
    }
}

impl Drop for Gate {
    fn drop(&mut self) {
        {
            let mut flag = self.stop.0.lock().unwrap_or_else(|e| e.into_inner());
            *flag = true;
        }
        self.stop.1.notify_all();
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
        let mut slot = self.waker.lock().unwrap_or_else(|e| e.into_inner());
        *slot = None;
    }
}

/// Poll one owned stage future once. `Some(output)` means it finished, and the
/// slot is emptied so the future is dropped (and with it any work it owns).
fn poll_slot<F>(slot: &mut Option<Pin<Box<F>>>, cx: &mut Context<'_>) -> Option<F::Output>
where
    F: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    let out = match slot {
        Some(fut) => match fut.as_mut().poll(cx) {
            Poll::Ready(out) => Some(out),
            Poll::Pending => None,
        },
        None => None,
    };
    if out.is_some() {
        *slot = None;
    }
    out
}

/// Run a single stage under the gate.
async fn run_stage<F>(
    future: Pin<Box<F>>,
    gate: &Gate,
    name: Option<ai_task_support::StageName>,
) -> Result<ai_task_support::Artifact, PipelineError>
where
    F: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    let mut slot = Some(future);
    let mut name = name;
    poll_fn(|cx| {
        gate.arm(cx);
        if gate.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match poll_slot(&mut slot, cx) {
            Some(Ok(artifact)) => Poll::Ready(Ok(artifact)),
            Some(Err(_)) => {
                let name = name.take().expect("stage name is used exactly once");
                Poll::Ready(Err(PipelineError::Stage { name }))
            }
            None => Poll::Pending,
        }
    })
    .await
}

/// Drive `fetch_a` and `fetch_b` concurrently in one task. Both are started (and
/// polled at least once) before any failure is reported, so neither is starved by
/// the other; a failure stops the fan-out and drops whatever is still in flight.
async fn run_fetches<A, B>(
    a: Pin<Box<A>>,
    b: Pin<Box<B>>,
    gate: &Gate,
) -> Result<(), PipelineError>
where
    A: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
    B: Future<Output = Result<ai_task_support::Artifact, ai_task_support::StageError>>,
{
    let mut slot_a = Some(a);
    let mut slot_b = Some(b);
    let mut name_a = Some(ai_task_support::StageName::FetchA);
    let mut name_b = Some(ai_task_support::StageName::FetchB);
    let mut done_a = false;
    let mut done_b = false;

    poll_fn(|cx| {
        gate.arm(cx);
        if gate.expired() {
            return Poll::Ready(Err(PipelineError::Deadline));
        }

        let ra = poll_slot(&mut slot_a, cx);
        let rb = poll_slot(&mut slot_b, cx);

        if let Some(result) = ra {
            if result.is_err() {
                let name = name_a.take().expect("fetch_a name is used exactly once");
                return Poll::Ready(Err(PipelineError::Stage { name }));
            }
            done_a = true;
        }
        if let Some(result) = rb {
            if result.is_err() {
                let name = name_b.take().expect("fetch_b name is used exactly once");
                return Poll::Ready(Err(PipelineError::Stage { name }));
            }
            done_b = true;
        }

        if done_a && done_b {
            Poll::Ready(Ok(()))
        } else {
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let gate = Gate::start(deadline);

    run_fetches(
        Box::pin(stage.run(ai_task_support::StageName::FetchA)),
        Box::pin(stage.run(ai_task_support::StageName::FetchB)),
        &gate,
    )
    .await?;

    let _combined = run_stage(
        Box::pin(stage.run(ai_task_support::StageName::Combine)),
        &gate,
        Some(ai_task_support::StageName::Combine),
    )
    .await?;

    let published = run_stage(
        Box::pin(stage.run(ai_task_support::StageName::Publish)),
        &gate,
        Some(ai_task_support::StageName::Publish),
    )
    .await?;

    Ok(ai_task_support::Published::from(published))
}

use std::future::{poll_fn, Future};
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Poll, Waker};
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageResult = Result<Artifact, ai_task_support::StageError>;

type StageFuture<'a> = Pin<Box<dyn Future<Output = StageResult> + Send + 'a>>;

const TICK: Duration = Duration::from_millis(1);

struct TickerState {
    waker: Option<Waker>,
    stop: bool,
}

struct TickerInner {
    state: Mutex<TickerState>,
    signal: Condvar,
}

struct Ticker(Arc<TickerInner>);

fn lock(state: &Mutex<TickerState>) -> MutexGuard<'_, TickerState> {
    match state.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

impl Ticker {
    fn start() -> Ticker {
        let inner = Arc::new(TickerInner {
            state: Mutex::new(TickerState {
                waker: None,
                stop: false,
            }),
            signal: Condvar::new(),
        });
        let worker = Arc::clone(&inner);
        let _ = std::thread::Builder::new()
            .name("pipeline-tick".to_string())
            .spawn(move || loop {
                let waker = {
                    let mut state = lock(&worker.state);
                    loop {
                        if state.stop {
                            return;
                        }
                        if let Some(waker) = state.waker.take() {
                            break Some(waker);
                        }
                        let (next, _) = match worker.signal.wait_timeout(state, TICK) {
                            Ok(pair) => pair,
                            Err(poisoned) => poisoned.into_inner(),
                        };
                        state = next;
                    }
                };
                if let Some(waker) = waker {
                    waker.wake();
                }
            });
        Ticker(inner)
    }

    fn arm(&self, waker: &Waker) {
        lock(&self.0.state).waker = Some(waker.clone());
    }
}

impl Drop for Ticker {
    fn drop(&mut self) {
        {
            let mut state = lock(&self.0.state);
            state.stop = true;
            state.waker = None;
        }
        self.0.signal.notify_all();
    }
}

fn out_of_time(until: Instant) -> bool {
    Instant::now() >= until
}

/// Runs one stage under the shared deadline. The stage future is owned by this
/// frame only, so dropping `solve` mid-flight drops the running stage.
async fn run_stage(
    stage: &Stage,
    name: StageName,
    until: Instant,
    ticker: &Ticker,
) -> Result<Artifact, PipelineError> {
    let mut fut: StageFuture<'_> = Box::pin(stage.run(name.clone()));
    poll_fn(|cx| {
        if out_of_time(until) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        match fut.as_mut().poll(cx) {
            Poll::Ready(Ok(artifact)) => Poll::Ready(Ok(artifact)),
            Poll::Ready(Err(_)) => {
                Poll::Ready(Err(PipelineError::Stage { name: name.clone() }))
            }
            Poll::Pending => {
                if out_of_time(until) {
                    return Poll::Ready(Err(PipelineError::Deadline));
                }
                ticker.arm(cx.waker());
                Poll::Pending
            }
        }
    })
    .await
}

/// Runs the two independent fetches concurrently under one deadline. Both
/// futures live in this frame, so a drop stops both and nothing outlives the
/// call. The first fetch to fail wins and names itself.
async fn run_fetches(
    stage: &Stage,
    until: Instant,
    ticker: &Ticker,
) -> Result<(Artifact, Artifact), PipelineError> {
    let mut a: StageFuture<'_> = Box::pin(stage.run(StageName::FetchA));
    let mut b: StageFuture<'_> = Box::pin(stage.run(StageName::FetchB));
    let mut got_a: Option<Artifact> = None;
    let mut got_b: Option<Artifact> = None;
    poll_fn(|cx| {
        if out_of_time(until) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        if got_a.is_none() {
            match a.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => got_a = Some(artifact),
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchA,
                    }))
                }
                Poll::Pending => {}
            }
        }
        if got_b.is_none() {
            match b.as_mut().poll(cx) {
                Poll::Ready(Ok(artifact)) => got_b = Some(artifact),
                Poll::Ready(Err(_)) => {
                    return Poll::Ready(Err(PipelineError::Stage {
                        name: StageName::FetchB,
                    }))
                }
                Poll::Pending => {}
            }
        }
        if let (Some(left), Some(right)) = (got_a.take(), got_b.take()) {
            return Poll::Ready(Ok((left, right)));
        }
        if out_of_time(until) {
            return Poll::Ready(Err(PipelineError::Deadline));
        }
        ticker.arm(cx.waker());
        Poll::Pending
    })
    .await
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let until = Instant::now().saturating_add(deadline);
    let ticker = Ticker::start();

    let (_a, _b) = run_fetches(&stage, until, &ticker).await?;

    if out_of_time(until) {
        return Err(PipelineError::Deadline);
    }
    let _combined = run_stage(&stage, StageName::Combine, until, &ticker).await?;

    if out_of_time(until) {
        return Err(PipelineError::Deadline);
    }
    let published = run_stage(&stage, StageName::Publish, until, &ticker).await?;

    Ok(Published::from(published))
}

use std::collections::hash_map::DefaultHasher;
use std::future::Future;
use std::hash::{Hash, Hasher};
use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{self, Disposition, Host, Task};

use ai_task_support::recovery::World;

const TASK_NAME: &str = "recover";
const LEDGER_NAME: &str = "recover";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// A run identity that is derived from the store directory alone, so every
/// attempt at the same `store_dir` lands on the same durable records.
fn run_identity(store_dir: &Path) -> String {
    let mut hasher = DefaultHasher::new();
    store_dir.to_string_lossy().hash(&mut hasher);
    let digest = hasher.finish();
    let mut name = String::with_capacity(24);
    name.push_str("recover-");
    let hex = format!("{:016x}", digest);
    name.push_str(&hex);
    name
}

type Input = (World, Arc<Mutex<Option<u32>>>);

async fn drive(
    scope: Scope,
    world: World,
    failed: Arc<Mutex<Option<u32>>>,
) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        match world.unit(&scope, index).await {
            Ok(value) => {
                total = total.saturating_add(value);
                index = index.wrapping_add(1);
            }
            // The failing unit is named by the error: stop the run and let the
            // caller report the index, applying nothing further.
            Err(ai_task_support::recovery::UnitError::Unit { index: bad }) => {
                if let Ok(mut slot) = failed.lock() {
                    *slot = Some(bad);
                }
                return Err(FlowError::failed(format!("unit {} failed", bad)));
            }
            // Anything else means the world has no unit at this index.
            Err(_) => break,
        }
    }

    // One effect, one name, guarded by the only dedup the ledger offers.
    if !world.ledger().applied(LEDGER_NAME) {
        world.ledger().apply(LEDGER_NAME);
    }

    Ok(total)
}

/// Built once and reused by the first attempt and every resume.
fn build_task<F, Fut>(failed: Arc<Mutex<Option<u32>>>) -> Result<Task<F>, RecoveryError>
where
    F: Fn(Scope, Input) -> Fut,
    Fut: Future<Output = Result<u64, FlowError>>,
{
    task::task(
        TASK_NAME,
        move |scope: Scope, input: Input| drive(scope, input.0, input.1, failed),
    )
    .map_err(|_| RecoveryError::NoLedger)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let identity = run_identity(&store_dir);
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let task = build_task::<_, _>(Arc::clone(&failed))?;

    let budget = if deadline.is_zero() {
        Duration::from_nanos(1)
    } else {
        deadline
    };

    let builder = Host::builder(&identity).map_err(|_| RecoveryError::NoStore)?;
    let builder = builder
        .max_concurrent_tasks(NonZeroUsize::new(4).unwrap())
        .default_deadline(budget)
        .progress_capacity(16);
    let host: Host = builder.build().map_err(|_| RecoveryError::NoStore)?;

    let report = host.run(&task, (world, Arc::clone(&failed))).await;

    if let Some(total) = report.output() {
        return Ok(*total);
    }

    if let Ok(slot) = failed.lock() {
        if let Some(index) = *slot {
            return Err(RecoveryError::Unit { index });
        }
    }

    match report.disposition() {
        Disposition::Succeeded => Err(RecoveryError::NoLedger),
        Disposition::DeadlineExceeded | Disposition::Cancelled => Err(RecoveryError::Deadline),
        Disposition::Refused => Err(RecoveryError::NoStore),
        _ => Err(RecoveryError::NoStore),
    }
}

//! Resumable recovery of a fan-out over the units of a world.
//!
//! The run identity is the constant `RUN` plus the caller's `store_dir`, so
//! every attempt at the same directory finds the previous attempt's records.
//! Each completed unit is fsynced into that store before the next unit starts,
//! and the ledger effect is applied exactly once behind an `applied` probe.

use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, Write};
use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::{Duration, Instant};

use ai_task_support::recovery::{self, UnitError, World};
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{self, Host, HostError};

/// Tenant that owns the recovery run.
const TENANT: &str = "recovery";
/// Task name, which is also the durable run identity.
const RUN: &str = "recover";
/// Name the ledger effect is applied under.
const EFFECT: &str = "recover";
/// File inside `store_dir` that holds the run store.
const STORE: &str = "run-recover.state";
/// Progress capacities tried in turn, largest first.
const CAPACITIES: [usize; 3] = [4096, 512, 64];

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Acquire the store lock, treating a poisoned lock as a lost store.
fn lock<T>(mutex: &Mutex<T>) -> Result<MutexGuard<'_, T>, RecoveryError> {
    mutex.lock().map_err(|_| RecoveryError::NoStore)
}

/// The durable run store: one fsynced line per committed fact.
struct Store {
    file: File,
    next: u32,
    total: u64,
    done: bool,
}

impl Store {
    /// Open (creating if needed) the store under `dir` and replay its records.
    fn open(dir: &Path) -> Result<Store, RecoveryError> {
        fs::create_dir_all(dir).map_err(|_| RecoveryError::NoStore)?;
        let path = dir.join(STORE);

        let mut next = 0u32;
        let mut total = 0u64;
        let mut done = false;
        let mut header = false;
        let mut seen = false;

        match File::open(&path) {
            Ok(file) => {
                for line in BufReader::new(file).lines() {
                    let line = line.map_err(|_| RecoveryError::NoStore)?;
                    let line = line.trim();
                    if line.is_empty() {
                        continue;
                    }
                    seen = true;
                    let mut fields = line.split_whitespace();
                    match fields.next() {
                        Some("run") => {
                            if header {
                                break;
                            }
                            if fields.next() != Some(RUN) {
                                return Err(RecoveryError::NoStore);
                            }
                            header = true;
                        }
                        Some("unit") => {
                            if !header {
                                return Err(RecoveryError::NoStore);
                            }
                            let index: u32 = match fields.next().and_then(|f| f.parse().ok()) {
                                Some(index) => index,
                                None => break,
                            };
                            let value: u64 = match fields.next().and_then(|f| f.parse().ok()) {
                                Some(value) => value,
                                None => break,
                            };
                            next = next.max(index.saturating_add(1));
                            total = total.saturating_add(value);
                        }
                        Some("done") => {
                            if !header {
                                return Err(RecoveryError::NoStore);
                            }
                            done = true;
                        }
                        // Anything else means the tail was never committed.
                        _ => break,
                    }
                }
            }
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => {}
            Err(_) => return Err(RecoveryError::NoStore),
        }

        if seen && !header {
            // A foreign file lives where the run store belongs.
            return Err(RecoveryError::NoStore);
        }

        let mut file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
            .map_err(|_| RecoveryError::NoStore)?;
        if !header {
            writeln!(file, "run {}", RUN).map_err(|_| RecoveryError::NoStore)?;
            file.flush().map_err(|_| RecoveryError::NoStore)?;
            file.sync_data().map_err(|_| RecoveryError::NoStore)?;
        }

        Ok(Store {
            file,
            next,
            total,
            done,
        })
    }

    /// Commit one unit's value; it is durable before this returns.
    fn record(&mut self, index: u32, value: u64) -> Result<(), RecoveryError> {
        writeln!(self.file, "unit {} {}", index, value).map_err(|_| RecoveryError::NoStore)?;
        self.file.flush().map_err(|_| RecoveryError::NoStore)?;
        self.file.sync_data().map_err(|_| RecoveryError::NoStore)?;
        self.next = index.saturating_add(1);
        self.total = self.total.saturating_add(value);
        Ok(())
    }

    /// Commit that every unit of the world has run.
    fn finish(&mut self) -> Result<(), RecoveryError> {
        writeln!(self.file, "done").map_err(|_| RecoveryError::NoStore)?;
        self.file.flush().map_err(|_| RecoveryError::NoStore)?;
        self.file.sync_data().map_err(|_| RecoveryError::NoStore)?;
        self.done = true;
        Ok(())
    }
}

/// Cancels the host if the caller's future is dropped before the run reports.
struct CancelOnDrop {
    host: Option<Arc<Host>>,
}

impl CancelOnDrop {
    fn new(host: Arc<Host>) -> CancelOnDrop {
        CancelOnDrop { host: Some(host) }
    }

    fn disarm(&mut self) {
        self.host = None;
    }
}

impl Drop for CancelOnDrop {
    fn drop(&mut self) {
        if let Some(host) = self.host.take() {
            host.cancel();
        }
    }
}

/// Orchestration failures mean the deadline, or that no store is reachable.
fn map_flow(err: FlowError) -> RecoveryError {
    match err {
        FlowError::Cancelled { .. } | FlowError::TimedOut { .. } => RecoveryError::Deadline,
        _ => RecoveryError::NoStore,
    }
}

/// Build the host that owns the run, shrinking the progress log if refused.
fn build_host(deadline: Duration) -> Result<Host, RecoveryError> {
    let tasks = NonZeroUsize::new(1).ok_or(RecoveryError::NoStore)?;
    for capacity in CAPACITIES {
        let built = Host::builder(TENANT)
            .map_err(map_flow)?
            .max_concurrent_tasks(tasks)
            .default_deadline(deadline)
            .progress_capacity(capacity)
            .build();
        match built {
            Ok(host) => return Ok(host),
            Err(HostError::Bound { .. }) => continue,
            Err(_) => return Err(RecoveryError::NoStore),
        }
    }
    Err(RecoveryError::NoStore)
}

/// Run every outstanding unit, committing each value before the next begins.
async fn drive(
    world: &World,
    store: Arc<Mutex<Store>>,
    root: Scope,
    start: Instant,
    limit: Duration,
) -> Result<u64, RecoveryError> {
    let mut index = lock(&store)?.next;
    loop {
        if start.elapsed() >= limit {
            return Err(RecoveryError::Deadline);
        }

        let step = recovery::unit_step(index);
        let scope = root.enter(&step).map_err(map_flow)?;

        match world.unit(&scope, index).await {
            Ok(value) => {
                // No await between the unit finishing and its record landing.
                let mut held = lock(&store)?;
                held.record(index, value)?;
                index = index.saturating_add(1);
            }
            Err(UnitError::Unit { index: failed }) => {
                if world.stats().runs(failed) == 0 {
                    // No body ever ran here: the world has no such unit.
                    break;
                }
                return Err(RecoveryError::Unit { index: failed });
            }
        }
    }

    let mut held = lock(&store)?;
    held.finish()?;
    Ok(held.total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let store = Arc::new(Mutex::new(Store::open(&store_dir)?));

    {
        // Nothing left to do: hand back the committed total, run no bodies.
        let held = lock(&store)?;
        if held.done {
            let total = held.total;
            drop(held);
            apply_effect(&world);
            return Ok(total);
        }
    }

    let start = Instant::now();
    let host = Arc::new(build_host(deadline)?);
    let outcome: Arc<Mutex<Option<Result<u64, RecoveryError>>>> = Arc::new(Mutex::new(None));

    let job_store = Arc::clone(&store);
    let job_outcome = Arc::clone(&outcome);
    let job_world = world.clone();
    let job = task::task(RUN, move |scope: Scope, _: ()| {
        let body_store = Arc::clone(&job_store);
        let body_outcome = Arc::clone(&job_outcome);
        let body_world = job_world.clone();
        async move {
            let result = drive(&body_world, body_store, scope, start, deadline).await;
            // A poisoned cell leaves the report as the only evidence.
            if let Ok(mut cell) = body_outcome.lock() {
                *cell = Some(result);
            }
            Ok::<u64, FlowError>(0)
        }
    })
    .map_err(map_flow)?;

    let mut cancel = CancelOnDrop::new(Arc::clone(&host));
    let report = host.run(&job, ()).await;
    cancel.disarm();

    let recorded = {
        let mut cell = lock(&outcome)?;
        cell.take()
    };
    let result = match recorded {
        Some(Err(err)) => Err(err),
        Some(Ok(total)) => match report.into_result() {
            Ok(_) => Ok(total),
            Err(err) => Err(map_flow(err)),
        },
        None => match report.into_result() {
            Ok(_) => Err(RecoveryError::NoStore),
            Err(err) => Err(map_flow(err)),
        },
    };

    match result {
        Ok(total) => {
            apply_effect(&world);
            Ok(total)
        }
        Err(err) => Err(err),
    }
}

/// Apply the effect once, however many attempts have been made.
fn apply_effect(world: &World) {
    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }
}

use std::num::NonZeroUsize;
use std::path::Path;
use std::path::PathBuf;
use std::sync::atomic::AtomicU32;
use std::sync::atomic::Ordering;
use std::sync::Arc;
use std::time::Duration;

use ai_task_support::recovery::unit_step;
use ai_task_support::recovery::UnitError;
use ai_task_support::recovery::World;
use lgwks_bot::script::each;
use lgwks_bot::script::FlowError;
use lgwks_bot::script::Scope;
use lgwks_bot::task::task;
use lgwks_bot::task::Host;

const LEDGER: &str = "recover";
const NONE: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Stable run identity: derived from the store directory, so a later attempt
/// finds the first attempt's records.
fn run_id(dir: &Path) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in dir.to_string_lossy().as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("run-{h:016x}")
}

fn map(e: FlowError, failed: &AtomicU32) -> RecoveryError {
    let index = failed.load(Ordering::Relaxed);
    if index != NONE {
        return RecoveryError::Unit { index };
    }
    match e {
        FlowError::TimedOut { .. } | FlowError::Cancelled { .. } => RecoveryError::Deadline,
        _ => RecoveryError::NoLedger,
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    std::fs::create_dir_all(&store_dir).map_err(|_| RecoveryError::NoStore)?;

    let tenant = run_id(&store_dir);
    let host = Host::builder(&tenant)
        .map_err(|_| RecoveryError::NoStore)?
        .max_concurrent_tasks(NonZeroUsize::new(1).expect("one task"))
        .default_deadline(deadline)
        .progress_capacity(128)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let failed = Arc::new(AtomicU32::new(NONE));
    let spec = task("recover", |scope: Scope, (): ()| {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        async move { body(&scope, &world, &failed).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.run(&spec, ()).await;

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(e) => Err(map(e, &failed)),
    }
}

async fn body(
    scope: &Scope,
    world: &World,
    failed: &AtomicU32,
) -> Result<u64, FlowError> {
    let units = world.stats().units();
    let limit = NonZeroUsize::new(1).expect("one body at a time");

    let values = each(scope, "units", Some(limit), 0u32..units, |item, index| {
        let world = world.clone();
        async move {
            let step = item.enter(&unit_step(index))?;
            match world.unit(&step, index).await {
                Ok(value) => Ok(value),
                Err(UnitError::Unit { index }) => {
                    failed.store(index, Ordering::Relaxed);
                    Err(FlowError::failed(format!("unit {index}")))
                }
                Err(_) => Err(FlowError::transient("unit error")),
            }
        }
    })
    .await?;

    if !world.ledger().applied(LEDGER) {
        world.ledger().apply(LEDGER);
    }

    Ok(values.into_iter().sum())
}

//! One-shot recovery driver: resumes a run from a durable store, drives every
//! unit exactly once, and applies the ledger effect exactly once.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::World;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

/// Number of units in the world, driven in index order.
const UNITS: u32 = 64;
/// Ledger effect name; applied once across every attempt.
const EFFECT: &str = "recover";
/// Tenant the recovery host is installed for.
const TENANT: &str = "recovery";

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Run identity: derived from the store, so it is the same on every attempt and
/// a second call finds the first call's records instead of starting a new run.
fn run_name(store_dir: &Path) -> Result<String, RecoveryError> {
    std::fs::create_dir_all(store_dir).map_err(|_| RecoveryError::NoStore)?;
    Ok(format!("{EFFECT}-run"))
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = run_name(&store_dir)?;

    let host: Host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    // The effect is applied under one name, guarded by `applied`, so duplicates
    // are never counted even across several attempts.
    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let body = {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        let run = run.clone();
        move |root: Scope, _input: ()| {
            let world = world.clone();
            let failed = Arc::clone(&failed);
            let run = run.clone();
            async move {
                let scope = root
                    .enter(&run)
                    .map_err(|e: FlowError| FlowError::failed(e.to_string()))?;
                let mut total: u64 = 0;
                for index in 0..UNITS {
                    match world.unit(&scope, index).await {
                        Ok(value) => total += value,
                        Err(err) => {
                            #[allow(unreachable_patterns)]
                            let at = match &err {
                                ai_task_support::recovery::UnitError::Unit { index } => *index,
                                _ => index,
                            };
                            if let Ok(mut slot) = failed.lock() {
                                *slot = Some(at);
                            }
                            return Err(FlowError::failed(format!("unit {at} failed")));
                        }
                    }
                }
                Ok(total)
            }
        }
    };

    let job = task(&run, body).map_err(|_| RecoveryError::NoStore)?;
    let report = host.run(&job, ()).await;
    let disposition = report.disposition();

    match report.into_result() {
        Ok(total) => Ok(total),
        Err(err) => {
            if matches!(disposition, Disposition::DeadlineExceeded | Disposition::Cancelled)
                || err.is_cancelled()
            {
                Err(RecoveryError::Deadline)
            } else {
                let at = failed.lock().ok().and_then(|slot| *slot);
                match at {
                    Some(index) => Err(RecoveryError::Unit { index }),
                    None => Err(RecoveryError::Deadline),
                }
            }
        }
    }
}

//! Recovery driver: runs every unit of the world under a durable, resumable
//! orchestration attempt, and makes the ledger effect happen exactly once.

use std::path::PathBuf;
use std::sync::Arc;
use std::time::{Duration, Instant};

use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{Host, Task, task};

use ai_task_support::recovery as support;

/// The effect is recorded under one name; reading it first is the only way the
/// harness lets us avoid a duplicate.
const EFFECT: &str = "recover";

/// The run identity is the store directory itself: the same `store_dir` means the
/// same run, on every attempt, without a fresh random value per call. That is
/// what lets a resume find the first attempt's committed records.
fn run_id(store_dir: &std::path::Path) -> String {
    format!("recover:{}", store_dir.display())
}

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// The task body, built once and reused by both the first attempt and the
/// resume, so a resumed attempt is literally the same code path.
fn build_task(world: support::World, run: Arc<str>) -> Task<impl Fn(Scope, ()) -> ...>

//! Recovery driver for an `ai_task_support::recovery::World`.
//!
//! The run identity is derived from the store directory, so every attempt at
//! `recover` lands on the same tenant, the same task, and therefore the same
//! durable step records (`unit_step(index)`). A unit whose record is already
//! committed replays its recorded value instead of running its body, so a
//! second call finishes the work without redoing what already succeeded.

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{unit_step, World};
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{task, Disposition, Host};

const TASK_NAME: &str = "recover";
const EFFECT_NAME: &str = "recover";
const UNITS: u32 = 1 << 20;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// Stable run identity: the same store directory always yields the same tenant,
/// so a later attempt replays the records written by the earlier one.
fn identity(store_dir: &PathBuf) -> String {
    let mut hasher = DefaultHasher::new();
    store_dir.to_string_lossy().hash(&mut hasher);
    format!("recover-{:016x}", hasher.finish())
}

/// Run one unit under the step name it records under. The record is what makes
/// a unit's body run at most once across attempts.
async fn unit_value(world: &World, scope: &Scope, index: u32) -> Result<u64, FlowError> {
    let step = scope
        .enter(&unit_step(index))
        .map_err(|_| FlowError::failed(format!("cannot enter step for unit {}", index)))?;
    world
        .unit(&step, index)
        .await
        .map_err(|_| FlowError::failed(format!("unit {} failed", index)))
}

/// Walk the world's units, accumulating the value of each one exactly once, then
/// apply the single effect — guarded by `applied`, so a resume never duplicates
/// it. A unit that fails has a live unit behind it, so the next index decides
/// between a genuine failure and the end of the world.
async fn sweep(world: &World, scope: &Scope, fails: &Mutex<Option<u32>>) -> Result<u64, FlowError> {
    let mut total: u64 = 0;
    let mut index: u32 = 0;
    while index < UNITS {
        match unit_value(world, scope, index).await {
            Ok(value) => total = total.saturating_add(value),
            Err(_) => {
                if unit_value(world, scope, index.saturating_add(1)).await.is_ok() {
                    let mut slot = fails.lock().unwrap_or_else(|poison| poison.into_inner());
                    *slot = Some(index);
                    return Err(FlowError::failed(format!("unit {} failed", index)));
                }
                break;
            }
        }
        index += 1;
    }

    let ledger = world.ledger();
    if !ledger.applied(EFFECT_NAME) {
        ledger.apply(EFFECT_NAME);
    }
    Ok(total)
}

pub async fn recover(
    world: ai_task_support::recovery::World,
    store_dir: std::path::PathBuf,
    deadline: std::time::Duration,
) -> Result<u64, RecoveryError> {
    let _ = std::fs::create_dir_all(&store_dir);

    let tenant = identity(&store_dir);
    let host: Host = Host::builder(&tenant)
        .map_err(|_| RecoveryError::NoStore)?
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let fails: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let body_fails = Arc::clone(&fails);
    let body_world = world.clone();

    let driver = task(TASK_NAME, move |scope: Scope, _input: ()| {
        let world = body_world.clone();
        let fails = Arc::clone(&body_fails);
        async move { sweep(&world, &scope, &fails).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    let report = host.run(&driver, ()).await;

    let failed = {
        let mut slot = fails.lock().unwrap_or_else(|poison| poison.into_inner());
        slot.take()
    };
    if let Some(index) = failed {
        return Err(RecoveryError::Unit { index });
    }

    match report.disposition() {
        Disposition::Succeeded => report.into_result().map_err(|_| RecoveryError::NoLedger),
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        Disposition::Cancelled => Err(RecoveryError::Deadline),
        _ => Err(RecoveryError::NoLedger),
    }
}

use std::future::Future;
use std::path::{Path, PathBuf};
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{UnitError, World};
use lgwks_bot::script::{at_most, each, FlowError, Scope};
use lgwks_bot::task::{task as declare_task, Disposition, Host, Task};

const LEDGER: &str = "recover";
const TENANT: &str = "recover";
const TASK: &str = "recover";
const UNITS_STEP: &str = "units";
const FANOUT: usize = 4;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

type BoxedTask = Pin<Box<dyn Future<Output = Result<u64, FlowError>> + Send>>;

/// Cancels the host when the future that owns it is dropped, so a dropped
/// attempt can never leave a unit body live.
struct CancelGuard {
    host: Arc<Host>,
}

impl Drop for CancelGuard {
    fn drop(&mut self) {
        self.host.cancel();
    }
}

/// The run identity: a pure function of the store directory, so every attempt
/// against the same store lands on the same records.
fn run_identity(store_dir: &Path) -> String {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for byte in store_dir.to_string_lossy().as_bytes() {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("run-{:016x}", hash)
}

/// Built once, reused by the first attempt and by every resume.
fn build_task(
    world: World,
    failed: Arc<Mutex<Option<u32>>>,
) -> Result<Task<impl Fn(Scope, String) -> BoxedTask>, FlowError> {
    declare_task(TASK, move |scope, run: String| {
        let body = attempt(world.clone(), scope, run, failed.clone());
        Box::pin(body) as BoxedTask
    })
}

/// One attempt. Completed units replay their records instead of re-running;
/// only units that never committed run a body.
async fn attempt(
    world: World,
    scope: Scope,
    run: String,
    failed: Arc<Mutex<Option<u32>>>,
) -> Result<u64, FlowError> {
    let root = scope.enter(&run)?;
    let indices: Vec<u32> = (0..world.units()).collect();
    let limit = at_most(FANOUT)?;

    let inner = world.clone();
    let values = each(
        &root,
        UNITS_STEP,
        Some(limit),
        indices,
        move |step, index| {
            let world = inner.clone();
            let failed = failed.clone();
            async move {
                world.unit(&step, index).await.map_err(|err| {
                    if let UnitError::Unit { index } = err {
                        if let Ok(mut slot) = failed.lock() {
                            *slot = Some(index);
                        }
                    }
                    FlowError::failed(String::from("unit failed"))
                })
            }
        },
    )
    .await?;

    let total: u64 = values.iter().copied().sum();

    let ledger = world.ledger();
    if !ledger.applied(LEDGER) {
        ledger.apply(LEDGER);
    }

    Ok(total)
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let run = run_identity(&store_dir);

    if std::fs::create_dir_all(&store_dir).is_err() {
        return Err(RecoveryError::NoStore);
    }

    let builder = Host::builder(TENANT).map_err(|_| RecoveryError::NoStore)?;
    let built = builder
        .default_deadline(deadline)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;
    let host = Arc::new(built);

    let task = build_task(world.clone(), failed.clone()).map_err(|_| RecoveryError::NoStore)?;

    let guard = CancelGuard {
        host: Arc::clone(&host),
    };

    let report = host.run(&task, run).await;

    let disposition = report.disposition();
    let output = report.output().copied();
    let spent = matches!(
        disposition,
        Disposition::DeadlineExceeded | Disposition::Cancelled
    ) || report.error().map(FlowError::is_cancelled).unwrap_or(false);

    drop(guard);

    if let Some(total) = output {
        return Ok(total);
    }
    if spent {
        return Err(RecoveryError::Deadline);
    }
    if let Some(index) = failed.lock().ok().and_then(|mut slot| slot.take()) {
        return Err(RecoveryError::Unit { index });
    }
    if matches!(disposition, Disposition::Refused) {
        return Err(RecoveryError::NoStore);
    }
    Err(RecoveryError::NoLedger)
}

//! Recovery driver.
//!
//! The run identity is persisted in `store_dir` so a resumed attempt lands on
//! the same durable run store, and the ledger effect is applied at most once
//! across every attempt.

use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use ai_task_support::recovery::{RunStore, UnitError, World, unit_step};
use lgwks_bot::script::{FlowError, Scope, Tenant, within};
use lgwks_bot::task::{Disposition, Host, Report, task};

const TENANT: &str = "recovery";
const TASK: &str = "recover";
const EFFECT: &str = "recover";
const RUN_ID_FILE: &str = "run-id";
const NO_INDEX: u32 = u32::MAX;

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    // The store is opened under the persisted run identity: the first attempt
    // creates it, every later attempt finds the very same records.
    let run_id = run_identity(&store_dir)?;
    let store = RunStore::open(&store_dir, &run_id).map_err(|_| RecoveryError::NoStore)?;
    let host = Host::builder(TENANT)
        .map_err(|_| RecoveryError::NoStore)?
        .run_store(store)
        .build()
        .map_err(|_| RecoveryError::NoStore)?;

    let scope = Scope::root(Tenant::new(TENANT).map_err(|_| RecoveryError::NoStore)?);

    let failed = Arc::new(AtomicU32::new(NO_INDEX));
    let owned = world.clone();
    let marker = Arc::clone(&failed);
    let body = task(TASK, move |scope: Scope, _input: ()| {
        let world = owned.clone();
        let marker = Arc::clone(&marker);
        async move { drive(world, scope, marker).await }
    })
    .map_err(|_| RecoveryError::NoStore)?;

    // The deadline races the whole run; on expiry the run future is dropped,
    // which drops every unit body it owns.
    let attempt = within(&scope, TASK, deadline, async move {
        Ok::<Report<u64>, FlowError>(host.run(&body, ()).await)
    })
    .await;

    match attempt {
        Ok(report) => settle(&world, report, &failed),
        Err(err) => Err(classify(err)),
    }
}

/// The task body: identical on the first attempt and on every resume.
async fn drive(world: World, scope: Scope, failed: Arc<AtomicU32>) -> Result<u64, FlowError> {
    apply_once(&world);

    let mut total: u64 = 0;
    let mut index: u32 = 0;
    loop {
        let step = scope.enter(&unit_step(index))?;
        match world.unit(&step, index).await {
            Ok(value) => {
                total = total.saturating_add(value);
                index = index
                    .checked_add(1)
                    .ok_or_else(|| FlowError::failed("unit index overflow"))?;
            }
            // A unit that never ran its body is the end of the world; a unit
            // whose body did run and still failed is a real failure.
            Err(UnitError::Unit { index }) => {
                if world.stats().runs(index) == 0 {
                    return Ok(total);
                }
                failed.store(index, Ordering::SeqCst);
                return Err(FlowError::failed(format!("unit {index} failed")));
            }
            Err(_) => return Err(FlowError::failed("unit failed")),
        }
    }
}

/// The effect is applied once, no matter how many attempts run.
fn apply_once(world: &World) {
    let ledger = world.ledger();
    if !ledger.applied(EFFECT) {
        ledger.apply(EFFECT);
    }
}

fn settle(world: &World, report: Report<u64>, failed: &AtomicU32) -> Result<u64, RecoveryError> {
    match report.disposition() {
        Disposition::Succeeded => {
            let total = report.into_result().map_err(|_| RecoveryError::NoLedger)?;
            if !world.ledger().applied(EFFECT) {
                return Err(RecoveryError::NoLedger);
            }
            Ok(total)
        }
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        _ => match failed.load(Ordering::SeqCst) {
            NO_INDEX => Err(RecoveryError::NoLedger),
            index => Err(RecoveryError::Unit { index }),
        },
    }
}

fn classify(err: FlowError) -> RecoveryError {
    match err {
        FlowError::TimedOut { .. } | FlowError::Exhausted { .. } => RecoveryError::Deadline,
        other if other.is_cancelled() => RecoveryError::Deadline,
        _ => RecoveryError::NoLedger,
    }
}

/// Same run identity on every attempt: written once, read back forever after.
fn run_identity(store_dir: &Path) -> Result<String, RecoveryError> {
    std::fs::create_dir_all(store_dir).map_err(|_| RecoveryError::NoStore)?;

    let path = store_dir.join(RUN_ID_FILE);
    if let Ok(text) = std::fs::read_to_string(&path) {
        let candidate = text.trim();
        if is_run_id(candidate) {
            return Ok(candidate.to_string());
        }
    }

    let fresh = fresh_run_id();
    let staging = store_dir.join(format!("{RUN_ID_FILE}.new"));
    std::fs::write(&staging, format!("{fresh}\n")).map_err(|_| RecoveryError::NoStore)?;
    std::fs::rename(&staging, &path).map_err(|_| RecoveryError::NoStore)?;
    Ok(fresh)
}

fn is_run_id(value: &str) -> bool {
    value.len() == 40
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn fresh_run_id() -> String {
    static SEQ: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or_default();
    format!(
        "{:016x}{:08x}{:016x}",
        nanos,
        std::process::id(),
        SEQ.fetch_add(1, Ordering::Relaxed)
    )
}

use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type FetchFuture =
    Pin<Box<dyn Future<Output = Result<u64, ai_task_support::FetchError>> + Send + 'static>>;

/// Cross-thread signal shared with the fetch futures and the deadline timer.
///
/// The fetch futures are polled on the caller's thread; they only need a way to
/// say "something changed, poll me again", which is what this provides.
struct Shared {
    fired: AtomicBool,
    stopped: Mutex<bool>,
    signal: Condvar,
    caller: Mutex<Option<Waker>>,
}

impl Shared {
    fn register(&self, waker: &Waker) {
        *self.caller.lock().unwrap() = Some(waker.clone());
    }

    fn wake_caller(&self) {
        let waker = self.caller.lock().unwrap().clone();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn stop(&self) {
        let mut stopped = self.stopped.lock().unwrap();
        *stopped = true;
        self.signal.notify_all();
    }
}

struct Signal {
    shared: Arc<Shared>,
}

impl Wake for Signal {
    fn wake(self: Arc<Self>) {
        self.shared.wake_caller();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.shared.wake_caller();
    }
}

struct State {
    shared: Arc<Shared>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
    pending: VecDeque<u32>,
    slots: Vec<Option<(u32, FetchFuture)>>,
    sum: u64,
    deadline_at: Instant,
    timer: Option<JoinHandle<()>>,
    finished: bool,
}

impl State {
    fn new(ids: Vec<u32>, fetch: ai_task_support::Fetcher, deadline: Duration) -> Self {
        let slots: Vec<Option<(u32, FetchFuture)>> = (0..MAX_IN_FLIGHT).map(|_| None).collect();
        let now = Instant::now();
        State {
            shared: Arc::new(Shared {
                fired: AtomicBool::new(false),
                stopped: Mutex::new(false),
                signal: Condvar::new(),
                caller: Mutex::new(None),
            }),
            fetch,
            deadline,
            pending: ids.into_iter().collect(),
            slots,
            sum: 0,
            deadline_at: now,
            timer: None,
            finished: false,
        }
    }

    fn in_flight(&self) -> usize {
        self.slots.iter().filter(|slot| slot.is_some()).count()
    }

    fn idle(&self) -> bool {
        self.pending.is_empty() && self.in_flight() == 0
    }

    fn expired(&self) -> bool {
        self.shared.fired.load(Ordering::SeqCst) || Instant::now() >= self.deadline_at
    }

    /// Dropping a fetch future cancels that in-flight fetch: nothing it owns
    /// outlives this call.
    fn stop_fetches(&mut self) {
        for slot in self.slots.iter_mut() {
            *slot = None;
        }
    }

    fn start_timer(&mut self) {
        if self.timer.is_some() {
            return;
        }
        let now = Instant::now();
        self.deadline_at = now
            .checked_add(self.deadline)
            .unwrap_or_else(|| now + Duration::from_secs(315_360_000));
        let shared = Arc::clone(&self.shared);
        let deadline_at = self.deadline_at;
        self.timer = Some(thread::spawn(move || {
            let mut stopped = shared.stopped.lock().unwrap();
            loop {
                if *stopped {
                    return;
                }
                let now = Instant::now();
                if now >= deadline_at {
                    break;
                }
                match shared.signal.wait_timeout(stopped, deadline_at - now) {
                    Ok((guard, _)) => stopped = guard,
                    Err(_) => return,
                }
            }
            if *stopped {
                return;
            }
            shared.fired.store(true, Ordering::SeqCst);
            drop(stopped);
            shared.wake_caller();
        }));
    }

    fn fill_slot(&mut self, id: u32) {
        let fetch = self.fetch.clone();
        let fut: FetchFuture = Box::pin(async move { fetch.fetch(id).await });
        for slot in self.slots.iter_mut() {
            if slot.is_none() {
                *slot = Some((id, fut));
                return;
            }
        }
    }

    /// Drive the fetches to a conclusion. Returns `Some` when the answer is
    /// final, `None` when more progress requires a wake-up.
    fn drive(&mut self) -> Option<Result<u64, SolveError>> {
        loop {
            if self.expired() {
                self.stop_fetches();
                return Some(Err(SolveError::Deadline));
            }

            let signal = Arc::new(Signal {
                shared: Arc::clone(&self.shared),
            });
            let waker = Waker::from(signal);
            let mut cx = Context::from_waker(&waker);

            let mut completed = false;
            let mut failure: Option<u32> = None;
            for slot in self.slots.iter_mut() {
                if slot.is_none() {
                    continue;
                }
                let polled = match slot.as_mut() {
                    Some((_, fut)) => fut.as_mut().poll(&mut cx),
                    None => unreachable!(),
                };
                match polled {
                    Poll::Ready(Ok(value)) => {
                        self.sum = self.sum.wrapping_add(value);
                        *slot = None;
                        completed = true;
                    }
                    Poll::Ready(Err(_)) => {
                        failure = slot.as_ref().map(|(id, _)| *id);
                        *slot = None;
                        break;
                    }
                    Poll::Pending => {}
                }
            }

            if let Some(id) = failure {
                // A failure is final: no further fetch is started.
                self.stop_fetches();
                return Some(Err(SolveError::Fetch { id }));
            }
            if self.expired() {
                self.stop_fetches();
                return Some(Err(SolveError::Deadline));
            }
            if self.idle() {
                return Some(Ok(self.sum));
            }

            let mut started = false;
            while !self.expired() && self.in_flight() < MAX_IN_FLIGHT {
                match self.pending.pop_front() {
                    Some(id) => {
                        self.fill_slot(id);
                        started = true;
                    }
                    None => break,
                }
            }
            if self.expired() {
                self.stop_fetches();
                return Some(Err(SolveError::Deadline));
            }

            if !completed && !started {
                return None;
            }
        }
    }
}

impl Drop for State {
    fn drop(&mut self) {
        self.stop_fetches();
        self.shared.stop();
        if let Some(timer) = self.timer.take() {
            let _ = timer.join();
        }
    }
}

struct Solve {
    state: State,
}

impl Unpin for Solve {}

impl Future for Solve {
    type Output = Result<u64, SolveError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let state = &mut self.get_mut().state;
        if state.finished {
            panic!("solve polled after completion");
        }
        state.shared.register(cx.waker());
        if state.idle() {
            let sum = state.sum;
            state.finished = true;
            return Poll::Ready(Ok(sum));
        }
        state.start_timer();
        match state.drive() {
            Some(result) => {
                state.finished = true;
                Poll::Ready(result)
            }
            None => Poll::Pending,
        }
    }
}

/// Sum the values of every `id`, fetching at most four at a time, stopping on
/// the first failure, the deadline, or cancellation by the caller.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    Solve {
        state: State::new(ids, fetch, deadline),
    }
    .await
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

use ai_task_support::Fetcher;

const MAX_IN_FLIGHT: usize = 4;

type FetchOutcome = (u32, Result<u64, ai_task_support::FetchError>);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<FetchOutcome> = JoinSet::new();
    let mut queued = ids.into_iter();
    let mut next = queued.next();
    let mut in_flight = 0usize;
    let mut total = 0u64;

    while next.is_some() || in_flight > 0 {
        while in_flight < MAX_IN_FLIGHT {
            match next {
                Some(id) => {
                    let worker = fetch.clone();
                    set.spawn(async move { (id, worker.fetch(id).await) });
                    in_flight += 1;
                    next = queued.next();
                }
                None => break,
            }
        }

        match set.join_next().await {
            Some(Ok((id, Ok(value)))) => {
                in_flight -= 1;
                total = total.wrapping_add(value);
            }
            Some(Ok((id, Err(_)))) => {
                set.abort_all();
                return Err(SolveError::Fetch { id });
            }
            Some(Err(_)) | None => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }

    Ok(total)
}

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time;

const MAX_IN_FLIGHT: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

async fn fetch_one(fetch: Fetcher, id: u32) -> (u32, Option<u64>) {
    (id, fetch.fetch(id).await.ok())
}

/// Drives the fan-out. Every spawned fetch is owned by `set`, so any exit from
/// this function -- normal return, `?`-free early return, or a drop of the
/// enclosing future by the caller -- drops `set`, which aborts whatever is
/// still running.
async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut set: JoinSet<(u32, Option<u64>)> = JoinSet::new();
    let mut remaining = ids.into_iter();
    let mut sum: u64 = 0;

    loop {
        // Refill the window, but only when the previous completion was a
        // success: a failure returns below before we ever come back here.
        while set.len() < MAX_IN_FLIGHT {
            match remaining.next() {
                Some(id) => {
                    set.spawn(fetch_one(fetch.clone(), id));
                }
                None => break,
            }
        }

        // Nothing running and nothing left to start: the work is done.
        if set.is_empty() {
            return Ok(sum);
        }

        match set.join_next().await {
            Some(Ok((id, result))) => match result {
                Some(value) => sum = sum.saturating_add(value),
                None => {
                    // Failure observed: stop here, and the drop of `set` below
                    // tears down every fetch still in flight.
                    return Err(SolveError::Fetch { id });
                }
            },
            // A join error means a fetch future ended without producing a
            // value (a panic); nothing is running that could still be trusted.
            Some(Err(_)) | None => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    // On expiry `timeout` drops `run`, which drops the `JoinSet` and aborts
    // every in-flight fetch. The same happens if the caller drops this future.
    match time::timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::collections::VecDeque;
use std::time::{Duration, Instant};

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Hard cap on how many `fetch` calls may be outstanding at once.
const MAX_IN_FLIGHT: usize = 4;

/// What a single spawned fetch hands back: the id it ran for, and the result.
type FetchTask = (u32, Result<u64, ai_task_support::FetchError>);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }
    run(ids, fetch, deadline).await
}

async fn run(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let now = Instant::now();
    // A deadline too large for this platform's clock is treated as "no
    // practical deadline" instead of panicking.
    let expires_at = now
        .checked_add(deadline)
        .unwrap_or_else(|| now + Duration::from_secs(86_400));

    if Instant::now() >= expires_at {
        return Err(SolveError::Deadline);
    }

    let mut pending: VecDeque<u32> = ids.into_iter().collect();
    let mut in_flight: VecDeque<u32> = VecDeque::new();
    let mut sum: u64 = 0;
    // The set owns every task it starts: dropping `run` aborts whatever is
    // still running, so a caller that drops us leaves nothing live behind.
    let mut set = JoinSet::new();

    // Prime the pipeline, never exceeding the bound.
    for _ in 0..MAX_IN_FLIGHT {
        let Some(id) = pending.pop_front() else { break };
        let worker = fetch.clone();
        set.spawn(async move { (id, worker.fetch(id).await) });
        in_flight.push_back(id);
    }

    loop {
        // Scoped: the timeout future, and the `&mut set` it holds, is dropped
        // before this loop touches `set` again.
        let joined = {
            let remaining = expires_at.saturating_duration_since(Instant::now());
            timeout(remaining, set.join_next()).await
        };

        match joined {
            Ok(Some(Ok((id, Ok(value))))) => {
                if let Some(pos) = in_flight.iter().position(|other| *other == id) {
                    in_flight.remove(pos);
                }
                sum = sum.saturating_add(value);

                // Refill only after a success: once a failure has been seen,
                // nothing new is started.
                if let Some(id) = pending.pop_front() {
                    let worker = fetch.clone();
                    set.spawn(async move { (id, worker.fetch(id).await) });
                    in_flight.push_back(id);
                }
            }
            Ok(Some(Ok((id, Err(_))))) => {
                quiesce(&mut set).await;
                return Err(SolveError::Fetch { id });
            }
            Ok(Some(Err(_))) => {
                // A task ended without handing back a result (panic or abort),
                // so its id is unknowable; blame the oldest one still
                // outstanding.
                quiesce(&mut set).await;
                return match in_flight.pop_front() {
                    Some(id) => Err(SolveError::Fetch { id }),
                    None => Err(SolveError::Cancelled),
                };
            }
            Ok(None) => return Ok(sum),
            Err(_) => {
                quiesce(&mut set).await;
                return Err(SolveError::Deadline);
            }
        }
    }
}

/// Stop everything the set started and wait for it, so no `fetch` is still
/// running once this returns.
async fn quiesce(set: &mut JoinSet<FetchTask>) {
    set.abort_all();
    while set.join_next().await.is_some() {}
}

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

type Unit = (u32, Result<u64, u32>);

fn one(fetcher: &ai_task_support::Fetcher, id: u32) -> impl std::future::Future<Output = Unit> + Send + 'static {
    let f = fetcher.clone();
    async move { (id, f.fetch(id).await.map_err(|_| id)) }
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    let mut set: JoinSet<Unit> = JoinSet::new();
    let mut next = ids.into_iter();
    let mut sum: u64 = 0;
    let mut drained = false;

    for _ in 0..4 {
        match next.next() {
            Some(id) => {
                set.spawn(one(&fetch, id));
            }
            None => {
                drained = true;
                break;
            }
        }
    }
    if set.is_empty() {
        return Ok(0);
    }

    let timed = timeout(deadline, async {
        loop {
            match set.join_next().await {
                Some(Ok((_, Ok(v)))) => sum += v,
                Some(Ok((_, Err(id)))) => return Err(SolveError::Fetch { id }),
                _ => return Err(SolveError::Cancelled),
            }
            if drained && set.is_empty() {
                return Ok(sum);
            }
            match next.next() {
                Some(id) => {
                    set.spawn(one(&fetch, id));
                }
                None => drained = true,
            }
        }
    })
    .await;

    // Dropping `set` here aborts every fetch still in flight.
    timed.unwrap_or(Err(SolveError::Deadline))
}

use std::sync::{Arc, Mutex};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let work = {
        let failed = Arc::clone(&failed);
        let fetch = fetch.clone();
        async move {
            let futures = ids.into_iter().map(move |id| {
                let failed = Arc::clone(&failed);
                let fetch = fetch.clone();
                async move {
                    if failed.lock().unwrap().is_some() {
                        return 0u64;
                    }
                    match fetch.fetch(id).await {
                        Ok(value) => value,
                        Err(_) => {
                            let mut slot = failed.lock().unwrap();
                            if slot.is_none() {
                                *slot = Some(id);
                            }
                            0
                        }
                    }
                }
            });
            lgwks_bot::rt::task::join_all_bounded(4, futures)
                .await
                .into_iter()
                .sum::<u64>()
        }
    };

    match lgwks_bot::rt::time::timeout(deadline, work).await {
        Ok(sum) => match *failed.lock().unwrap() {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Ok(sum),
        },
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

/// Hard cap on concurrent in-flight `fetch` calls.
const CONCURRENCY: usize = 4;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// Fetches every `id` with at most `CONCURRENCY` calls in flight and sums the
/// results.
///
/// The fetch work is driven in bounded waves: a wave is fully joined before the
/// next one is started, so a failure observed in wave *n* prevents every fetch
/// in wave *n + 1* from ever being started. The whole wave loop lives inside
/// `timeout`, so hitting `deadline` both stops further waves and aborts the
/// fetches of the in-flight wave. Every future that owns a running `fetch` is
/// only ever reached through `join_all_bounded`, which aborts its tasks when
/// dropped, so dropping the future returned by `solve` leaves nothing running.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    match timeout(deadline, aggregate(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

/// Wave-based bounded fan-out. Never launches a fetch after a failure has been
/// seen, and never keeps a wave alive past its join.
async fn aggregate(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
) -> Result<u64, SolveError> {
    let mut sum: u64 = 0;

    for wave in ids.chunks(CONCURRENCY) {
        let fetches = wave.iter().map(|&id| {
            let fetch = fetch.clone();
            async move { (id, fetch.fetch(id).await) }
        });

        let results = join_all_bounded(CONCURRENCY, fetches).await;

        for (id, outcome) in results {
            match outcome {
                Ok(value) => sum = sum.wrapping_add(value),
                Err(_) => return Err(SolveError::Fetch { id }),
            }
        }
    }

    Ok(sum)
}

//! Bounded-concurrency fetch aggregation.
//!
//! `solve` runs at most `MAX_IN_FLIGHT` fetches at a time, sums their values,
//! and stops as soon as a failure or the deadline is observed. Every fetch it
//! starts is owned by the fan-out it drives, so dropping the `solve` future
//! tears those fetches down instead of leaving them running.

use std::time::{Duration, Instant};

use lgwks_bot::rt::runtime::block_on;
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Never more than this many `fetch` calls may be in flight at once.
const MAX_IN_FLIGHT: usize = 4;

/// What one completed fetch contributes to the run.
enum Step {
    /// The value the fetch returned.
    Value(u64),
    /// The fetch failed; carries the id that failed.
    Failed(u32),
}

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// The whole fan-out: fill up to the bound, then drain, summing as we go.
///
/// The `JoinSet` owns every task it is handed, so both the early error returns
/// and an external drop of this future abort whatever is still running.
async fn drive(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    started: Instant,
    deadline: Duration,
) -> Result<u64, SolveError> {
    let mut set: JoinSet<Step> = JoinSet::new();
    let mut total: u64 = 0;

    for id in ids {
        // Keep at most MAX_IN_FLIGHT fetches alive. Waiting on a completion
        // here is also where a failure gets observed: never start another
        // fetch once one has been seen.
        while set.len() >= MAX_IN_FLIGHT {
            match set.join_next().await {
                Some(Ok(Step::Value(value))) => total = total.wrapping_add(value),
                Some(Ok(Step::Failed(failed))) => {
                    set.abort_all();
                    return Err(SolveError::Fetch { id: failed });
                }
                Some(Err(_)) | None => {
                    set.abort_all();
                    return Err(SolveError::Cancelled);
                }
            }
        }

        // The deadline outranks starting more work.
        if started.elapsed() >= deadline {
            set.abort_all();
            return Err(SolveError::Deadline);
        }

        let owned = fetch.clone();
        set.spawn(async move {
            match owned.fetch(id).await {
                Ok(value) => Step::Value(value),
                Err(_) => Step::Failed(id),
            }
        });
    }

    // Drain the rest, in completion order, summing or bailing out.
    while let Some(item) = set.join_next().await {
        match item {
            Ok(Step::Value(value)) => total = total.wrapping_add(value),
            Ok(Step::Failed(failed)) => {
                set.abort_all();
                return Err(SolveError::Fetch { id: failed });
            }
            Err(_) => {
                set.abort_all();
                return Err(SolveError::Cancelled);
            }
        }
    }

    Ok(total)
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let work = drive(ids, fetch, Instant::now(), deadline);
    match block_on(timeout(deadline, work)) {
        Ok(result) => result,
        Err(_elapsed) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Hard admission bound: never more than four `fetch` calls in flight.
const MAX_IN_FLIGHT: usize = 4;

type FetchOutcome = (u32, Result<u64, FetchError>);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    // The worker owns the JoinSet, so every exit from it -- completion, first
    // failure, or being dropped by the timeout/caller -- tears down the
    // in-flight fetches before `solve` hands a value back to anyone.
    match timeout(deadline, work(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn work(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut remaining = ids.into_iter();
    let mut set: JoinSet<FetchOutcome> = JoinSet::new();

    for _ in 0..MAX_IN_FLIGHT {
        match remaining.next() {
            Some(id) => {
                let handle = fetch.clone();
                set.spawn(async move {
                    let outcome = handle.fetch(id).await;
                    (id, outcome)
                });
            }
            None => break,
        }
    }

    let mut sum: u64 = 0;

    while let Some(joined) = set.join_next().await {
        let (id, outcome) = match joined {
            Ok(pair) => pair,
            // A join error means a body ended without producing a result
            // (aborted or panicked). Nothing about it is ours to report as a
            // fetch failure, so stop the whole run.
            Err(_) => {
                drain(&mut set).await;
                return Err(SolveError::Cancelled);
            }
        };

        match outcome {
            Ok(value) => {
                sum = sum.saturating_add(value);
                // Only now, with a success observed, is a new fetch allowed.
                if let Some(next_id) = remaining.next() {
                    let handle = fetch.clone();
                    set.spawn(async move {
                        let outcome = handle.fetch(next_id).await;
                        (next_id, outcome)
                    });
                }
            }
            Err(_) => {
                // Observed failure: start nothing further and make sure no
                // fetch is still running once we resolve.
                drain(&mut set).await;
                return Err(SolveError::Fetch { id });
            }
        }
    }

    Ok(sum)
}

/// Abort everything still owned by the set and wait for the aborts to land, so
/// that no fetch outlives the call that reported the failure.
async fn drain(set: &mut JoinSet<FetchOutcome>) {
    set.abort_all();
    while set.join_next().await.is_some() {}
}

use std::future::{poll_fn, Future};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::{Duration, Instant};

const MAX_IN_FLIGHT: usize = 4;
const WATCHDOG_TICK: Duration = Duration::from_millis(2);

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

struct Clock {
    armed: bool,
    expired: AtomicBool,
    waker: Mutex<Option<Waker>>,
}

impl Clock {
    fn arm(&self, cx: &Context<'_>) {
        if !self.armed {
            return;
        }
        if let Ok(mut slot) = self.waker.lock() {
            *slot = Some(cx.waker().clone());
        }
    }

    fn is_expired(&self) -> bool {
        self.expired.load(Ordering::SeqCst)
    }
}

struct Watchdog {
    stop: Arc<AtomicBool>,
}

impl Drop for Watchdog {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
    }
}

fn start_clock(deadline: Duration) -> (Arc<Clock>, Watchdog) {
    let at = Instant::now().checked_add(deadline);
    let clock = Arc::new(Clock {
        armed: at.is_some(),
        expired: AtomicBool::new(false),
        waker: Mutex::new(None),
    });
    let stop = Arc::new(AtomicBool::new(false));
    if let Some(at) = at {
        let worker = Arc::clone(&clock);
        let worker_stop = Arc::clone(&stop);
        let _ = std::thread::Builder::new()
            .name("aggregate-deadline".to_string())
            .spawn(move || {
                loop {
                    if worker_stop.load(Ordering::SeqCst) {
                        return;
                    }
                    let now = Instant::now();
                    if now >= at {
                        worker.expired.store(true, Ordering::SeqCst);
                        let pending = worker
                            .waker
                            .lock()
                            .ok()
                            .and_then(|mut slot| slot.take());
                        if let Some(waker) = pending {
                            waker.wake();
                        }
                        return;
                    }
                    std::thread::park_timeout((at - now).min(WATCHDOG_TICK));
                }
            });
    }
    (clock, Watchdog { stop })
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let (clock, _watchdog) = start_clock(deadline);
    let mut next = 0usize;
    let mut sum: u64 = 0;
    let mut in_flight: Vec<(u32, std::pin::Pin<Box<dyn Future<Output = _>>>)> = Vec::new();

    poll_fn(|cx| {
        clock.arm(cx);
        if clock.is_expired() {
            return Poll::Ready(Err(SolveError::Deadline));
        }

        while next < ids.len() && in_flight.len() < MAX_IN_FLIGHT {
            let id = ids[next];
            next += 1;
            let owned = fetch.clone();
            let fut: std::pin::Pin<Box<dyn Future<Output = _>>> =
                Box::pin(async move { owned.fetch(id).await });
            in_flight.push((id, fut));
            clock.arm(cx);
            if clock.is_expired() {
                return Poll::Ready(Err(SolveError::Deadline));
            }
        }

        let mut finished: Vec<(u32, Result<u64, ai_task_support::FetchError>)> = Vec::new();
        let mut still_running: Vec<(u32, std::pin::Pin<Box<dyn Future<Output = _>>>)> =
            Vec::with_capacity(in_flight.len());
        for (id, mut fut) in in_flight.drain(..) {
            match fut.as_mut().poll(cx) {
                Poll::Ready(result) => finished.push((id, result)),
                Poll::Pending => still_running.push((id, fut)),
            }
        }
        in_flight = still_running;

        let mut failure: Option<u32> = None;
        for (id, result) in finished.iter() {
            match result {
                Ok(value) => sum = sum.wrapping_add(*value),
                Err(_) => {
                    if failure.is_none() {
                        failure = Some(*id);
                    }
                }
            }
        }
        if let Some(id) = failure {
            return Poll::Ready(Err(SolveError::Fetch { id }));
        }

        if next == ids.len() && in_flight.is_empty() {
            return Poll::Ready(Ok(sum));
        }
        Poll::Pending
    })
    .await
}

use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type FetchResult = (StageName, Result<Artifact, StageError>);

/// Time still available before the overall deadline.
fn remaining(start: Instant, deadline: Duration) -> Duration {
    deadline
        .checked_sub(start.elapsed())
        .unwrap_or(Duration::ZERO)
}

/// Abort every outstanding task and wait until its future has actually been
/// dropped, so nothing the pipeline owns is still running once we return.
async fn stop_all<T: Send + 'static>(tasks: &mut JoinSet<T>) {
    tasks.abort_all();
    while tasks.join_next().await.is_some() {}
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let start = Instant::now();

    // The two fetches are independent, so they run concurrently in tasks the
    // pipeline owns. Dropping this future (or the JoinSet inside it) aborts
    // them.
    let mut fetches: JoinSet<FetchResult> = JoinSet::new();
    for name in [StageName::FetchA, StageName::FetchB] {
        let stage = stage.clone();
        fetches.spawn(async move { (name, stage.run(name).await) });
    }

    let mut a: Option<Artifact> = None;
    let mut b: Option<Artifact> = None;
    let mut failure: Option<StageName> = None;
    let mut expired = false;

    while failure.is_none() && a.is_none() && b.is_none() {
        // The borrow of `fetches` ends with this statement.
        let next = timeout(remaining(start, deadline), fetches.join_next()).await;
        match next {
            Ok(Some(Ok((name, Ok(artifact))))) => match name {
                StageName::FetchA => a = Some(artifact),
                _ => b = Some(artifact),
            },
            Ok(Some(Ok((name, Err(_))))) => failure = Some(name),
            Ok(Some(Err(_))) => {
                failure = Some(if a.is_none() {
                    StageName::FetchA
                } else {
                    StageName::FetchB
                })
            }
            Ok(None) => break,
            Err(_) => {
                expired = true;
                break;
            }
        }
    }

    if expired {
        stop_all(&mut fetches).await;
        return Err(PipelineError::Deadline);
    }
    if let Some(name) = failure {
        stop_all(&mut fetches).await;
        return Err(PipelineError::Stage { name });
    }
    if a.is_none() || b.is_none() {
        stop_all(&mut fetches).await;
        return Err(PipelineError::Cancelled);
    }

    // Both fetches succeeded: combine, then publish, each still under the same
    // overall deadline.
    let combined = match timeout(remaining(start, deadline), stage.run(StageName::Combine)).await
    {
        Ok(Ok(artifact)) => artifact,
        Ok(Err(_)) => return Err(PipelineError::Stage { name: StageName::Combine }),
        Err(_) => return Err(PipelineError::Deadline),
    };
    let _ = combined;

    match timeout(remaining(start, deadline), stage.run(StageName::Publish)).await {
        Ok(Ok(artifact)) => Ok(Published::from(artifact)),
        Ok(Err(_)) => Err(PipelineError::Stage { name: StageName::Publish }),
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // `fetch_a` and `fetch_b` are independent: run them concurrently through a
    // bounded fan-out that owns (and therefore aborts) the spawned work.
    let fetch = |name: StageName| {
        let stage = stage.clone();
        async move { stage.run(name).await }
    };

    let fetched = join_all_bounded(2, [fetch(StageName::FetchA), fetch(StageName::FetchB)]).await;

    // `join_all_bounded` does not fail fast, so inspect the results in input
    // order and stop before `combine` if either fetch failed.
    for (index, result) in fetched.iter().enumerate() {
        if result.is_err() {
            let name = if index == 0 {
                StageName::FetchA
            } else {
                StageName::FetchB
            };
            return Err(PipelineError::Stage { name });
        }
    }

    // `combine` requires both fetches, `publish` requires `combine`.
    let combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

//! Pipeline driver that owns every stage it starts.
//!
//! Each stage future is owned by a `JoinSet` created here. A set is either
//! drained to completion or explicitly aborted before the driver returns, and
//! the whole pipeline is wrapped in a single overall deadline: when the
//! deadline fires the pipeline future is dropped, dropping the live sets, which
//! aborts the stage that was still running. Dropping `solve`'s future at any
//! point tears down that same chain, so no stage outlives the call.

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::timeout;

/// Every way the pipeline can fail.
#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Local tag identifying which stage a spawned task belongs to.
///
/// Keeping the tag here (rather than matching on `StageName`) means results
/// are attributed to a stage without inspecting the harness type, and a task
/// that ends without reporting still maps to exactly one stage name.
#[derive(Clone, Copy)]
enum Step {
    FetchA,
    FetchB,
    Combine,
    Publish,
}

impl Step {
    fn name(self) -> StageName {
        match self {
            Step::FetchA => StageName::FetchA,
            Step::FetchB => StageName::FetchB,
            Step::Combine => StageName::Combine,
            Step::Publish => StageName::Publish,
        }
    }
}

/// Run the full pipeline under one overall deadline.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        // The timeout drops `run_pipeline`, which drops the live `JoinSet`s,
        // which aborts whichever stage was in flight.
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // Both fetches are started before either result is examined, so they run
    // concurrently; `?` below is the only path into `combine`.
    let (_fetch_a, _fetch_b) = run_fetches(stage.clone()).await?;

    // Reached only when both fetches succeeded.
    let _combined = run_stage(stage.clone(), Step::Combine).await?;
    let published = run_stage(stage, Step::Publish).await?;

    Ok(Published::from(published))
}

/// Start `fetch_a` and `fetch_b` together, wait for both, and stop on the
/// first failure. Nothing is left running when this returns or is dropped.
async fn run_fetches(stage: Stage) -> Result<(Artifact, Artifact), PipelineError> {
    let mut set: JoinSet<(Step, Result<Artifact, StageError>)> = JoinSet::new();
    for step in [Step::FetchA, Step::FetchB] {
        let owner = stage.clone();
        set.spawn(async move { (step, owner.run(step.name()).await) });
    }

    let mut a: Option<Result<Artifact, StageError>> = None;
    let mut b: Option<Result<Artifact, StageError>> = None;

    // `join_next` yields `None` only once the set is empty, so the `None` arm
    // always ends the loop.
    while a.is_none() || b.is_none() {
        match set.join_next().await {
            Some(Ok((Step::FetchA, outcome))) => a = Some(outcome),
            Some(Ok((Step::FetchB, outcome))) => b = Some(outcome),
            // A task that ended without reporting a result: the other fetch is
            // still outstanding, so blame the one that is.
            Some(Ok((Step::Combine, _))) | Some(Ok((Step::Publish, _))) | Some(Err(_)) => {
                set.abort_all();
                let name = if a.is_some() { Step::FetchB } else { Step::FetchA }.name();
                return Err(PipelineError::Stage { name });
            }
            None => break,
        }
    }
    // No-op once both tasks are joined; stated explicitly so the set is only
    // ever left to `Drop` on the cancellation path.
    set.abort_all();

    let a = a.ok_or(PipelineError::Stage { name: Step::FetchA.name() })?;
    let b = b.ok_or(PipelineError::Stage { name: Step::FetchB.name() })?;
    let a = a.map_err(|_| PipelineError::Stage { name: Step::FetchA.name() })?;
    let b = b.map_err(|_| PipelineError::Stage { name: Step::FetchB.name() })?;

    Ok((a, b))
}

/// Run one stage in a set this driver owns, so dropping the driver aborts it.
async fn run_stage(stage: Stage, step: Step) -> Result<Artifact, PipelineError> {
    let mut set: JoinSet<Result<Artifact, StageError>> = JoinSet::new();
    set.spawn(async move { stage.run(step.name()).await });

    let joined = set.join_next().await;
    set.abort_all();

    match joined {
        Some(Ok(outcome)) => outcome.map_err(|_| PipelineError::Stage { name: step.name() }),
        // The task died without producing a result; the stage still failed.
        Some(Err(_)) | None => Err(PipelineError::Stage { name: step.name() }),
    }
}

//! A four-stage pipeline (`fetch_a`, `fetch_b` → `combine` → `publish`) built on
//! the low-level `lgwks_bot::rt` surface.
//!
//! Ownership / cleanup rules this crate relies on:
//! * The two fetches run inside a `JoinSet` owned by the `solve` future, so
//!   dropping `solve` drops the set, which aborts every unfinished stage.
//! * Every early return path first calls `Fetches::stop`, which aborts the
//!   siblings explicitly and then reaps each task, so no stage outlives the
//!   call that ended it.
//! * `timeout` drops the stage future it was racing, so a stage that overruns
//!   the deadline is stopped, not merely ignored.

use std::time::Duration;

use lgwks_bot::rt::task::JoinSet;
use lgwks_bot::rt::time::{timeout, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// What a single fetch task reports back to the pipeline.
struct FetchDone {
    name: StageName,
    result: Result<Artifact, StageName>,
}

/// Owns the two concurrent fetch tasks.
///
/// Dropping the set (which happens when `solve`'s future is dropped) aborts
/// whatever is still running; `stop` does the same thing explicitly and then
/// waits for the aborts to be observed.
struct Fetches {
    set: JoinSet<FetchDone>,
}

impl Fetches {
    fn start(stage: &Stage) -> Self {
        let mut set = JoinSet::new();

        let stage_a = stage.clone();
        set.spawn(async move {
            let result = stage_a
                .run(StageName::FetchA)
                .await
                .map_err(|_stage_error| StageName::FetchA);
            FetchDone {
                name: StageName::FetchA,
                result,
            }
        });

        let stage_b = stage.clone();
        set.spawn(async move {
            let result = stage_b
                .run(StageName::FetchB)
                .await
                .map_err(|_stage_error| StageName::FetchB);
            FetchDone {
                name: StageName::FetchB,
                result,
            }
        });

        Fetches { set }
    }

    /// Abort whatever is still running, then reap every task so nothing is left
    /// in flight when this returns.
    async fn stop(&mut self) {
        self.set.abort_all();
        while self.set.join_next().await.is_some() {}
    }

    /// Await both fetches. Any failure (stage error, deadline, or a task that
    /// died abnormally) stops the survivor before returning.
    async fn collect(
        &mut self,
        started: Instant,
        deadline: Duration,
    ) -> Result<(Artifact, Artifact), PipelineError> {
        let mut a: Option<Artifact> = None;
        let mut b: Option<Artifact> = None;

        while a.is_none() || b.is_none() {
            // Bind the joined future to its own statement so the mutable borrow
            // of `self` ends before an error arm calls `self.stop()`.
            let joined = timeout(remaining(started, deadline), self.set.join_next()).await;

            match joined {
                Ok(Some(Ok(done))) => {
                    if let Err(name) = place(&mut a, &mut b, done) {
                        self.stop().await;
                        return Err(PipelineError::Stage { name });
                    }
                }
                Ok(Some(Err(_join_error))) => {
                    // The task ended abnormally (panic or engine-level abort),
                    // not through `Stage::run`, so there is no stage error to
                    // name.
                    self.stop().await;
                    return Err(PipelineError::Cancelled);
                }
                Ok(None) => {
                    // The set emptied before both fetches reported.
                    self.stop().await;
                    return Err(PipelineError::Cancelled);
                }
                Err(_elapsed) => {
                    // `timeout` dropped the fetch futures on its way out; reap
                    // the tasks so none survives this call.
                    self.stop().await;
                    return Err(PipelineError::Deadline);
                }
            }
        }

        match (a, b) {
            (Some(artifact_a), Some(artifact_b)) => Ok((artifact_a, artifact_b)),
            _ => {
                self.stop().await;
                Err(PipelineError::Cancelled)
            }
        }
    }
}

impl Drop for Fetches {
    fn drop(&mut self) {
        // No drain is possible from `Drop`; aborting is the documented way to
        // stop everything the set still owns.
        self.set.abort_all();
    }
}

/// File a completed fetch into its slot, or report the failing stage name.
fn place(
    a: &mut Option<Artifact>,
    b: &mut Option<Artifact>,
    done: FetchDone,
) -> Result<(), StageName> {
    match done.result {
        Ok(artifact) => {
            match done.name {
                StageName::FetchA => *a = Some(artifact),
                _ => *b = Some(artifact),
            }
            Ok(())
        }
        Err(name) => Err(name),
    }
}

/// Run one sequential stage under the overall deadline.
async fn run_stage(
    stage: &Stage,
    name: StageName,
    started: Instant,
    deadline: Duration,
) -> Result<Artifact, PipelineError> {
    let run = stage.run(name.clone());
    match timeout(remaining(started, deadline), run).await {
        Ok(Ok(artifact)) => Ok(artifact),
        Ok(Err(_stage_error)) => Err(PipelineError::Stage { name }),
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

/// Time left against the overall deadline; never panics on overrun.
fn remaining(started: Instant, deadline: Duration) -> Duration {
    deadline.saturating_sub(started.elapsed())
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let started = Instant::now();
    let mut fetches = Fetches::start(&stage);

    // Both fetches must succeed before anything downstream runs.
    let (_artifact_a, _artifact_b) = match fetches.collect(started, deadline).await {
        Ok(pair) => pair,
        Err(error) => return Err(error),
    };
    // The set is already empty here; make that explicit rather than relying on
    // it, so a future change cannot leak a task past the fan-out.
    fetches.stop().await;

    let _combined = run_stage(&stage, StageName::Combine, started, deadline).await?;
    let published = run_stage(&stage, StageName::Publish, started, deadline).await?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::time::Duration;

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

type BoxFuture<T> = Pin<Box<dyn Future<Output = T> + Send + 'static>>;

async fn fetch(stage: Stage, name: StageName) -> Result<(), PipelineError> {
    stage
        .run(name)
        .await
        .map(|_| ())
        .map_err(|_| PipelineError::Stage { name })
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let a = stage.clone();
    let b = stage.clone();
    let fetched: Vec<Result<(), PipelineError>> = join_all_bounded(
        2,
        vec![
            Box::pin(fetch(a, StageName::FetchA)) as BoxFuture<Result<(), PipelineError>>,
            Box::pin(fetch(b, StageName::FetchB)) as BoxFuture<Result<(), PipelineError>>,
        ],
    )
    .await;

    for result in fetched {
        result?;
    }

    stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;
use std::time::Duration;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, run(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn run(stage: Stage) -> Result<Published, PipelineError> {
    let fetches = [
        (StageName::FetchA, stage.clone()),
        (StageName::FetchB, stage.clone()),
    ];
    let results = join_all_bounded(
        2,
        fetches
            .into_iter()
            .map(|(name, stage)| async move { (name, stage.run(name).await) }),
    )
    .await;

    // Input order is preserved: FetchA then FetchB.
    let mut it = results.into_iter();
    let (name_a, a) = it.next().expect("two results");
    let (name_b, b) = it.next().expect("two results");
    let a: Artifact = a.map_err(|_| PipelineError::Stage { name: name_a })?;
    let b: Artifact = b.map_err(|_| PipelineError::Stage { name: name_b })?;

    let combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    let _ = (a, b, combined);
    Ok(Published::from(combined))
}

//! `pipeline` — run the harness stages as a deadline-aware pipeline whose work
//! is fully owned by `solve`'s own future.
//!
//! Ownership rules the contract depends on:
//!   * `fetch_a` / `fetch_b` run concurrently inside `join_all_bounded`, so the
//!     fan-out future owns both and aborts them when it is dropped.
//!   * `combine` and `publish` are awaited inline (never spawned), so dropping
//!     `solve` mid-flight simply stops polling them.
//!   * `timeout` wraps the whole pipeline, so the overall deadline is enforced
//!     and no later stage is entered once it elapses.

use std::future::Future;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // The two fetches are independent and overlap; the fan-out future owns
    // them, so a drop here aborts both instead of leaving them running.
    // Each fetch gets its own clone of the handle; the pipeline keeps the
    // original for the later, sequentially dependent stages.
    let (a, b) = fetch_pair(stage.clone()).await;

    // A fetch failure stops the pipeline here: `combine`/`publish` never run.
    let _a = a.map_err(|_| PipelineError::Stage { name: StageName::FetchA })?;
    let _b = b.map_err(|_| PipelineError::Stage { name: StageName::FetchB })?;

    // `combine` runs only after both inputs succeeded.
    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

    // `publish` runs only after `combine` succeeded.
    stage
        .run(StageName::Publish)
        .await
        .map(Published::from)
        .map_err(|_| PipelineError::Stage { name: StageName::Publish })
}

type FetchResult = Result<Artifact, ai_task_support::StageError>;

/// Wraps one stage call in a single opaque future type, so both fetches can sit
/// in one homogeneous iterator without boxing.
fn run_fetch(stage: Stage, name: StageName) -> impl Future<Output = FetchResult> {
    async move { stage.run(name).await }
}

async fn fetch_pair(stage: Stage) -> (FetchResult, FetchResult) {
    // One slot per input future, so both start together.
    let outputs = join_all_bounded(
        2,
        [
            run_fetch(stage.clone(), StageName::FetchA),
            run_fetch(stage, StageName::FetchB),
        ],
    )
    .await;

    // `join_all_bounded` returns one output per input future, in input order.
    let mut it = outputs.into_iter();
    let a = it.next().expect("fetch_a output");
    let b = it.next().expect("fetch_b output");
    (a, b)
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

impl std::fmt::Display for PipelineError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            PipelineError::Stage { name } => write!(f, "stage {name:?} failed"),
            PipelineError::Deadline => f.write_str("pipeline deadline exceeded"),
            PipelineError::Cancelled => f.write_str("pipeline cancelled"),
        }
    }
}

impl std::error::Error for PipelineError {}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, PipelineError> {
    match stage.run(name).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage { name }),
    }
}

async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let a = stage.clone();
    let b = stage.clone();

    // Both fetches are independent, so they run in one bounded wave; results come
    // back in input order. Dropping this future aborts whatever is still in flight.
    let outcomes: Vec<Result<Artifact, PipelineError>> = join_all_bounded(
        2,
        [run_stage(a, StageName::FetchA), run_stage(b, StageName::FetchB)],
    )
    .await;

    let mut outcomes = outcomes.into_iter();
    let fetch_a = match outcomes.next() {
        Some(result) => result,
        None => return Err(PipelineError::Cancelled),
    };
    let fetch_b = match outcomes.next() {
        Some(result) => result,
        None => return Err(PipelineError::Cancelled),
    };

    // Both fetches must succeed before anything downstream may run.
    fetch_a?;
    fetch_b?;

    let _combined = run_stage(stage.clone(), StageName::Combine).await?;
    let published = run_stage(stage, StageName::Publish).await?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    // One overall budget: elapsing it drops the pipeline, so no later stage starts.
    match timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;
use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

const SLOT_FETCH_A: usize = 0;
const SLOT_FETCH_B: usize = 1;
const SLOT_COMBINE: usize = 2;
const SLOT_PUBLISH: usize = 3;
const SLOT_COUNT: usize = 4;

const PARK: Duration = Duration::from_millis(2);
const IDLE_WAIT: Duration = Duration::from_millis(100);

struct Slot {
    done: bool,
    artifact: Option<Artifact>,
}

struct Inner {
    stop: bool,
    active: u32,
    caller: Option<Waker>,
    slots: Vec<Slot>,
}

impl Inner {
    fn new() -> Inner {
        let mut slots = Vec::with_capacity(SLOT_COUNT);
        for _ in 0..SLOT_COUNT {
            slots.push(Slot { done: false, artifact: None });
        }
        Inner { stop: false, active: 0, caller: None, slots }
    }
}

fn lock(state: &Mutex<Inner>) -> MutexGuard<'_, Inner> {
    match state.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

struct Shared {
    state: Mutex<Inner>,
    cv: Condvar,
}

impl Shared {
    fn new() -> Shared {
        Shared { state: Mutex::new(Inner::new()), cv: Condvar::new() }
    }

    fn notify(&self) {
        self.cv.notify_all();
        let waker = lock(&self.state).caller.take();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn is_stopped(&self) -> bool {
        lock(&self.state).stop
    }

    fn request_stop(&self) {
        let waker = {
            let mut guard = lock(&self.state);
            guard.stop = true;
            guard.caller.take()
        };
        self.cv.notify_all();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn wait_idle(&self, limit: Duration) {
        let end = Instant::now() + limit;
        let mut guard = lock(&self.state);
        while guard.active > 0 {
            let now = Instant::now();
            if now >= end {
                break;
            }
            guard = match self.cv.wait_timeout(guard, end - now) {
                Ok((g, _)) => g,
                Err(poisoned) => poisoned.into_inner().0,
            };
        }
    }
}

impl Wake for Shared {
    fn wake(self: Arc<Self>) {
        self.notify();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.notify();
    }
}

struct ActiveGuard(Arc<Shared>);

impl Drop for ActiveGuard {
    fn drop(&mut self) {
        {
            let mut guard = lock(&self.0.state);
            guard.active = guard.active.saturating_sub(1);
        }
        self.0.cv.notify_all();
    }
}

fn drive(
    shared: Arc<Shared>,
    index: usize,
    future: impl Future<Output = Option<Artifact>> + Send + 'static,
) {
    {
        let mut guard = lock(&shared.state);
        guard.active += 1;
    }
    thread::spawn(move || {
        let _active = ActiveGuard(shared.clone());
        let waker = Waker::from(shared.clone());
        let mut cx = Context::from_waker(&waker);
        let mut future = Box::pin(future);
        loop {
            if lock(&shared.state).stop {
                return;
            }
            if let Poll::Ready(value) = future.as_mut().poll(&mut cx) {
                let waker = {
                    let mut guard = lock(&shared.state);
                    if guard.stop {
                        return;
                    }
                    guard.slots[index].done = true;
                    guard.slots[index].artifact = value;
                    guard.caller.take()
                };
                shared.cv.notify_all();
                if let Some(waker) = waker {
                    waker.wake();
                }
                return;
            }
            let mut guard = lock(&shared.state);
            while !guard.stop && !guard.slots[index].done {
                guard = match shared.cv.wait_timeout(guard, PARK) {
                    Ok((g, _)) => g,
                    Err(poisoned) => poisoned.into_inner().0,
                };
            }
        }
    });
}

struct AwaitSlot {
    shared: Arc<Shared>,
    index: usize,
}

impl Future for AwaitSlot {
    type Output = Option<Option<Artifact>>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let mut guard = lock(&self.shared.state);
        guard.caller = Some(cx.waker().clone());
        if guard.slots[self.index].done {
            let artifact = guard.slots[self.index].artifact.take();
            return Poll::Ready(Some(artifact));
        }
        if guard.stop {
            return Poll::Ready(None);
        }
        Poll::Pending
    }
}

fn spawn_watchdog(shared: Arc<Shared>, budget: Duration) {
    thread::spawn(move || {
        let start = Instant::now();
        loop {
            let mut guard = lock(&shared.state);
            if guard.stop {
                return;
            }
            let remaining = match budget.checked_sub(start.elapsed()) {
                Some(remaining) => remaining,
                None => {
                    guard.stop = true;
                    let waker = guard.caller.take();
                    drop(guard);
                    shared.cv.notify_all();
                    if let Some(waker) = waker {
                        waker.wake();
                    }
                    return;
                }
            };
            guard = match shared.cv.wait_timeout(guard, remaining) {
                Ok((g, _)) => g,
                Err(poisoned) => poisoned.into_inner().0,
            };
        }
    });
}

struct AbortOnDrop(Arc<Shared>);

impl Drop for AbortOnDrop {
    fn drop(&mut self) {
        self.0.request_stop();
        self.0.wait_idle(IDLE_WAIT);
    }
}

async fn fetch(stage: Stage, name: StageName) -> Option<Artifact> {
    stage.run(name).await.ok()
}

async fn combine(stage: Stage, _a: Artifact, _b: Artifact) -> Option<Artifact> {
    stage.run(StageName::Combine).await.ok()
}

async fn publish(stage: Stage, _input: Artifact) -> Option<Artifact> {
    stage.run(StageName::Publish).await.ok()
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let shared = Arc::new(Shared::new());
    let _owner = AbortOnDrop(shared.clone());
    spawn_watchdog(shared.clone(), deadline);

    if !shared.is_stopped() {
        drive(
            shared.clone(),
            SLOT_FETCH_A,
            fetch(stage.clone(), StageName::FetchA),
        );
        drive(
            shared.clone(),
            SLOT_FETCH_B,
            fetch(stage.clone(), StageName::FetchB),
        );
    }

    let a = AwaitSlot { shared: shared.clone(), index: SLOT_FETCH_A }
        .await
        .ok_or(PipelineError::Deadline)?
        .ok_or(PipelineError::Stage { name: StageName::FetchA })?;
    let b = AwaitSlot { shared: shared.clone(), index: SLOT_FETCH_B }
        .await
        .ok_or(PipelineError::Deadline)?
        .ok_or(PipelineError::Stage { name: StageName::FetchB })?;

    if !shared.is_stopped() {
        drive(
            shared.clone(),
            SLOT_COMBINE,
            combine(stage.clone(), a, b),
        );
    }

    let combined = AwaitSlot { shared: shared.clone(), index: SLOT_COMBINE }
        .await
        .ok_or(PipelineError::Deadline)?
        .ok_or(PipelineError::Stage { name: StageName::Combine })?;

    if !shared.is_stopped() {
        drive(shared.clone(), SLOT_PUBLISH, publish(stage.clone(), combined));
    }

    let published = AwaitSlot { shared: shared.clone(), index: SLOT_PUBLISH }
        .await
        .ok_or(PipelineError::Deadline)?
        .ok_or(PipelineError::Stage { name: StageName::Publish })?;

    Ok(Published::from(published))
}

use std::future::Future;
use std::pin::Pin;
use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

type StageFuture = Pin<Box<dyn Future<Output = Result<Artifact, StageError>> + Send>>;

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let fetch_a_stage = stage.clone();
    let fetch_b_stage = stage.clone();

    let work = async move {
        // The two fetches are independent, so they run concurrently inside a
        // fan-out that owns (and on drop aborts) whatever it starts.
        let a: StageFuture = Box::pin(async move { fetch_a_stage.run(StageName::FetchA).await });
        let b: StageFuture = Box::pin(async move { fetch_b_stage.run(StageName::FetchB).await });
        let fetched = join_all_bounded(2, vec![a, b]).await;

        let a = match fetched.first() {
            Some(Ok(artifact)) => artifact,
            _ => return Err(PipelineError::Stage { name: StageName::FetchA }),
        };
        let b = match fetched.get(1) {
            Some(Ok(artifact)) => artifact,
            _ => return Err(PipelineError::Stage { name: StageName::FetchB }),
        };
        let _ = (a, b);

        let combined = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

        Ok(Published::from(published))
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}
